-- =====================================================================
-- V4: Bộ nội dung đầy đủ - từ vựng theo chủ đề + ngữ pháp tiếng Anh, kèm bài kiểm tra.
-- File sinh tự động, nằm ở db/seed (không nạp trong test tích hợp, test dùng seed nhỏ V2).
--   * Mỗi từ vựng có 1 câu hỏi trắc nghiệm; mỗi chủ đề chia thành các bài kiểm tra ~10 câu.
--   * Mỗi chủ điểm ngữ pháp có phần giải thích, ví dụ và 1 bài kiểm tra 6 câu.
-- UUID cố định: topics 10.., grammar 20.., ví dụ 21.., từ 30.., quiz 40.., câu hỏi 41..
-- =====================================================================

-- ----------------------------------------------------------------- Từ vựng
UPDATE topics SET description = 'Từ vựng về sinh hoạt hằng ngày.' WHERE id = '10000000-0000-0000-0000-000000000001';
UPDATE topics SET description = 'Từ vựng về du lịch, chuyến đi và khách sạn.' WHERE id = '10000000-0000-0000-0000-000000000002';
UPDATE topics SET description = 'Từ vựng về đồ ăn và thức uống.' WHERE id = '10000000-0000-0000-0000-000000000003';
UPDATE topics SET description = 'Từ vựng về công nghệ và thiết bị.' WHERE id = '10000000-0000-0000-0000-000000000004';
UPDATE topics SET description = 'Từ vựng về kinh doanh và môi trường công sở.' WHERE id = '10000000-0000-0000-0000-000000000005';
-- Hai từ có sẵn từ V2 đứng đầu danh sách của chủ đề
UPDATE flashcards SET sort_order = 0 WHERE id IN ('30000000-0000-0000-0000-000000000001', '30000000-0000-0000-0000-000000000002');



-- total_words là counter: đếm lại từ số thẻ thật
UPDATE topics t SET t.total_words = (SELECT COUNT(*) FROM flashcards f WHERE f.topic_id = t.id AND f.deleted_at IS NULL);

-- Bài kiểm tra từ vựng

-- ----------------------------------------------------------------- Ngữ pháp
-- Cập nhật 5 chủ điểm có sẵn (nội dung đầy đủ, đúng thứ tự giáo trình)
UPDATE grammar_lessons SET title = 'Present Simple', description = 'Diễn tả thói quen, sự thật hiển nhiên và lịch trình cố định.', structure = 'S + V(s/es) + O', content = 'Thì hiện tại đơn dùng để nói về thói quen, sự thật hiển nhiên và lịch trình cố định.\nVới chủ ngữ ngôi thứ ba số ít (he, she, it), động từ thêm -s/-es: she works, he watches.\nPhủ định: do not (don''t) / does not (doesn''t) + động từ nguyên mẫu.\nNghi vấn: Do/Does + S + động từ nguyên mẫu?', usage_notes = 'Dấu hiệu nhận biết: always, usually, often, sometimes, never, every day, on Mondays.\nSau does/doesn''t, động từ luôn ở dạng nguyên mẫu (không thêm -s).', icon_name = 'account_tree', level = 'A1', estimated_minutes = 12, sort_order = 1, is_published = TRUE WHERE id = '20000000-0000-0000-0000-000000000001';
UPDATE grammar_lessons SET title = 'Present Continuous', description = 'Diễn tả hành động đang xảy ra tại thời điểm nói.', structure = 'S + am/is/are + V-ing', content = 'Thì hiện tại tiếp diễn diễn tả hành động đang diễn ra ngay lúc nói hoặc xung quanh thời điểm nói.\nCấu trúc: S + am/is/are + V-ing. Phủ định: S + am/is/are + not + V-ing.\nNghi vấn: Am/Is/Are + S + V-ing?', usage_notes = 'Dấu hiệu: now, right now, at the moment, today, look!, listen!.\nMột số động từ chỉ trạng thái (know, like, want, love) thường không dùng ở thì tiếp diễn.', icon_name = 'access_alarm', level = 'A1', estimated_minutes = 10, sort_order = 3, is_published = TRUE WHERE id = '20000000-0000-0000-0000-000000000002';
UPDATE grammar_lessons SET title = 'Past Simple', description = 'Diễn tả hành động đã xảy ra và kết thúc hoàn toàn trong quá khứ.', structure = 'S + V2/V-ed', content = 'Thì quá khứ đơn dùng cho hành động đã xảy ra và chấm dứt tại một thời điểm xác định trong quá khứ.\nĐộng từ có quy tắc thêm -ed (work - worked); động từ bất quy tắc có dạng riêng (go - went, see - saw, have - had).\nPhủ định: did not (didn''t) + động từ nguyên mẫu. Nghi vấn: Did + S + động từ nguyên mẫu?', usage_notes = 'Dấu hiệu: yesterday, last week/month/year, ago, in 2010, when I was a child.\nSau did/didn''t động từ trở về nguyên mẫu: She didn''t go (không nói didn''t went).', icon_name = 'history_edu', level = 'A2', estimated_minutes = 12, sort_order = 14, is_published = TRUE WHERE id = '20000000-0000-0000-0000-000000000003';
UPDATE grammar_lessons SET title = 'Present Perfect', description = 'Nói về trải nghiệm, kết quả ở hiện tại của hành động trong quá khứ.', structure = 'S + have / has + V3/V-ed', content = 'Thì hiện tại hoàn thành nối quá khứ với hiện tại. Dùng cho: trải nghiệm (I have been to Japan), hành động vừa xảy ra có kết quả ở hiện tại (She has lost her keys) và hành động kéo dài đến nay (I have lived here for five years).\nCấu trúc: S + have/has + V3/V-ed. Chủ ngữ he/she/it dùng has.', usage_notes = 'Dấu hiệu: ever, never, already, yet, just, since, for, so far, recently.\nKhông dùng với mốc thời gian đã kết thúc (yesterday, last year, in 2010): khi đó dùng quá khứ đơn.', icon_name = 'verified_user', level = 'A2', estimated_minutes = 12, sort_order = 18, is_published = TRUE WHERE id = '20000000-0000-0000-0000-000000000004';
UPDATE grammar_lessons SET title = 'First Conditional', description = 'Câu điều kiện loại 1 diễn tả tình huống có thể xảy ra ở tương lai.', structure = 'If + S + V(hiện tại), S + will + V', content = 'Câu điều kiện loại 1 nói về một điều kiện có thật hoặc có khả năng xảy ra ở hiện tại hoặc tương lai và kết quả của nó.\nMệnh đề if dùng hiện tại đơn, mệnh đề chính dùng will + động từ nguyên mẫu.\nCó thể dùng can, may, might, must hoặc câu mệnh lệnh thay cho will ở mệnh đề chính.', usage_notes = 'Không dùng will trong mệnh đề if: If it rains, we will stay (không nói If it will rain).\nUnless = if ... not: Unless you hurry, you will be late.', icon_name = 'alt_route', level = 'B1', estimated_minutes = 12, sort_order = 30, is_published = TRUE WHERE id = '20000000-0000-0000-0000-000000000005';


-- Bài kiểm tra ngữ pháp
