  ('30000000-0000-0000-0013-000000000013', '10000000-0000-0000-0000-000000000013', 'police officer', 'n.', '/pəˈliːs ˈɒfɪsə/', 'cảnh sát', 'The police officer helped us.', 'Viên cảnh sát đã giúp chúng tôi.', 13),
  ('30000000-0000-0000-0013-000000000014', '10000000-0000-0000-0000-000000000013', 'artist', 'n.', '/ˈɑːtɪst/', 'họa sĩ, nghệ sĩ', 'The artist painted a portrait.', 'Họa sĩ đã vẽ một bức chân dung.', 14),
