  ('30000000-0000-0000-0013-000000000025', '10000000-0000-0000-0000-000000000013', 'retire', 'v.', '/rɪˈtaɪə/', 'nghỉ hưu', 'My grandfather retired last year.', 'Ông tôi đã nghỉ hưu năm ngoái.', 25),
  ('30000000-0000-0000-0013-000000000026', '10000000-0000-0000-0000-000000000013', 'full-time', 'adj.', '/ˌfʊl ˈtaɪm/', 'toàn thời gian', 'She has a full-time job.', 'Cô ấy có một công việc toàn thời gian.', 26),
  ('30000000-0000-0000-0013-000000000027', '10000000-0000-0000-0000-000000000013', 'part-time', 'adj.', '/ˌpɑːt ˈtaɪm/', 'bán thời gian', 'I have a part-time job at a cafe.', 'Tôi có một công việc bán thời gian ở quán cà phê.', 27),
  ('30000000-0000-0000-0013-000000000028', '10000000-0000-0000-0000-000000000013', 'unemployed', 'adj.', '/ˌʌnɪmˈplɔɪd/', 'thất nghiệp', 'He has been unemployed for two months.', 'Anh ấy đã thất nghiệp được hai tháng.', 28),
  ('30000000-0000-0000-0013-000000000029', '10000000-0000-0000-0000-000000000013', 'responsible', 'adj.', '/rɪˈspɒnsəbl/', 'có trách nhiệm', 'She is responsible for the sales team.', 'Cô ấy chịu trách nhiệm về đội bán hàng.', 29),
  ('30000000-0000-0000-0013-000000000030', '10000000-0000-0000-0000-000000000013', 'teamwork', 'n.', '/ˈtiːmwɜːk/', 'làm việc nhóm', 'Good teamwork leads to success.', 'Làm việc nhóm tốt dẫn đến thành công.', 30),
  ('30000000-0000-0000-0014-000000000001', '10000000-0000-0000-0000-000000000014', 'dog', 'n.', '/dɒɡ/', 'con chó', 'My dog likes to play outside.', 'Con chó của tôi thích chơi ngoài trời.', 1),
  ('30000000-0000-0000-0014-000000000002', '10000000-0000-0000-0000-000000000014', 'cat', 'n.', '/kæt/', 'con mèo', 'The cat is sleeping on the sofa.', 'Con mèo đang ngủ trên ghế sofa.', 2),
  ('30000000-0000-0000-0014-000000000003', '10000000-0000-0000-0000-000000000014', 'bird', 'n.', '/bɜːd/', 'con chim', 'A bird is singing in the tree.', 'Một con chim đang hót trên cây.', 3),
  ('30000000-0000-0000-0014-000000000004', '10000000-0000-0000-0000-000000000014', 'fish', 'n.', '/fɪʃ/', 'con cá', 'The fish swims in the pond.', 'Con cá bơi trong ao.', 4),
  ('30000000-0000-0000-0014-000000000005', '10000000-0000-0000-0000-000000000014', 'horse', 'n.', '/hɔːs/', 'con ngựa', 'She can ride a horse.', 'Cô ấy biết cưỡi ngựa.', 5),
  ('30000000-0000-0000-0014-000000000006', '10000000-0000-0000-0000-000000000014', 'cow', 'n.', '/kaʊ/', 'con bò', 'The cow gives us milk.', 'Con bò cho chúng ta sữa.', 6),
  ('30000000-0000-0000-0014-000000000007', '10000000-0000-0000-0000-000000000014', 'pig', 'n.', '/pɪɡ/', 'con heo', 'The farmer feeds the pig.', 'Người nông dân cho con heo ăn.', 7),
  ('30000000-0000-0000-0014-000000000008', '10000000-0000-0000-0000-000000000014', 'chicken', 'n.', '/ˈtʃɪkɪn/', 'con gà', 'The chicken lays eggs.', 'Con gà đẻ trứng.', 8),
  ('30000000-0000-0000-0014-000000000009', '10000000-0000-0000-0000-000000000014', 'duck', 'n.', '/dʌk/', 'con vịt', 'The duck is swimming.', 'Con vịt đang bơi.', 9),
  ('30000000-0000-0000-0014-000000000010', '10000000-0000-0000-0000-000000000014', 'sheep', 'n.', '/ʃiːp/', 'con cừu', 'A sheep has soft wool.', 'Con cừu có bộ lông mềm.', 10),
  ('30000000-0000-0000-0014-000000000011', '10000000-0000-0000-0000-000000000014', 'rabbit', 'n.', '/ˈræbɪt/', 'con thỏ', 'The rabbit eats carrots.', 'Con thỏ ăn cà rốt.', 11),
  ('30000000-0000-0000-0014-000000000012', '10000000-0000-0000-0000-000000000014', 'mouse', 'n.', '/maʊs/', 'con chuột', 'The cat chased the mouse.', 'Con mèo đuổi theo con chuột.', 12),
  ('30000000-0000-0000-0014-000000000013', '10000000-0000-0000-0000-000000000014', 'elephant', 'n.', '/ˈelɪfənt/', 'con voi', 'An elephant is a very big animal.', 'Con voi là một loài động vật rất lớn.', 13),
  ('30000000-0000-0000-0014-000000000014', '10000000-0000-0000-0000-000000000014', 'lion', 'n.', '/ˈlaɪən/', 'con sư tử', 'The lion is the king of the jungle.', 'Sư tử là chúa tể của rừng xanh.', 14),
  ('30000000-0000-0000-0014-000000000015', '10000000-0000-0000-0000-000000000014', 'tiger', 'n.', '/ˈtaɪɡə/', 'con hổ', 'The tiger is a dangerous animal.', 'Con hổ là một loài động vật nguy hiểm.', 15),
  ('30000000-0000-0000-0014-000000000016', '10000000-0000-0000-0000-000000000014', 'monkey', 'n.', '/ˈmʌŋki/', 'con khỉ', 'The monkey climbed the tree.', 'Con khỉ trèo lên cây.', 16),
  ('30000000-0000-0000-0014-000000000017', '10000000-0000-0000-0000-000000000014', 'bear', 'n.', '/beə/', 'con gấu', 'A bear sleeps all winter.', 'Con gấu ngủ suốt mùa đông.', 17),
  ('30000000-0000-0000-0014-000000000018', '10000000-0000-0000-0000-000000000014', 'snake', 'n.', '/sneɪk/', 'con rắn', 'Be careful, there is a snake.', 'Hãy cẩn thận, có một con rắn.', 18),
  ('30000000-0000-0000-0014-000000000019', '10000000-0000-0000-0000-000000000014', 'frog', 'n.', '/frɒɡ/', 'con ếch', 'The frog jumped into the pond.', 'Con ếch nhảy xuống ao.', 19),
  ('30000000-0000-0000-0014-000000000020', '10000000-0000-0000-0000-000000000014', 'butterfly', 'n.', '/ˈbʌtəflaɪ/', 'con bướm', 'A butterfly landed on the flower.', 'Một con bướm đậu trên bông hoa.', 20),
  ('30000000-0000-0000-0014-000000000021', '10000000-0000-0000-0000-000000000014', 'bee', 'n.', '/biː/', 'con ong', 'The bee makes honey.', 'Con ong làm ra mật.', 21),
  ('30000000-0000-0000-0014-000000000022', '10000000-0000-0000-0000-000000000014', 'spider', 'n.', '/ˈspaɪdə/', 'con nhện', 'There is a spider on the wall.', 'Có một con nhện trên tường.', 22);
INSERT INTO flashcards (id, topic_id, word, part_of_speech, pronunciation, meaning, example, example_translation, sort_order) VALUES
  ('30000000-0000-0000-0014-000000000023', '10000000-0000-0000-0000-000000000014', 'turtle', 'n.', '/ˈtɜːtl/', 'con rùa', 'The turtle moves slowly.', 'Con rùa di chuyển chậm chạp.', 23),
  ('30000000-0000-0000-0014-000000000024', '10000000-0000-0000-0000-000000000014', 'dolphin', 'n.', '/ˈdɒlfɪn/', 'cá heo', 'The dolphin is very smart.', 'Cá heo rất thông minh.', 24),
  ('30000000-0000-0000-0014-000000000025', '10000000-0000-0000-0000-000000000014', 'shark', 'n.', '/ʃɑːk/', 'cá mập', 'A shark has sharp teeth.', 'Cá mập có hàm răng sắc nhọn.', 25),
  ('30000000-0000-0000-0014-000000000026', '10000000-0000-0000-0000-000000000014', 'wolf', 'n.', '/wʊlf/', 'con sói', 'The wolf howls at night.', 'Con sói hú vào ban đêm.', 26),
  ('30000000-0000-0000-0014-000000000027', '10000000-0000-0000-0000-000000000014', 'deer', 'n.', '/dɪə/', 'con hươu', 'A deer ran across the road.', 'Một con hươu chạy ngang qua đường.', 27),
  ('30000000-0000-0000-0014-000000000028', '10000000-0000-0000-0000-000000000014', 'giraffe', 'n.', '/dʒɪˈrɑːf/', 'con hươu cao cổ', 'A giraffe has a very long neck.', 'Con hươu cao cổ có cái cổ rất dài.', 28),
  ('30000000-0000-0000-0014-000000000029', '10000000-0000-0000-0000-000000000014', 'pet', 'n.', '/pet/', 'thú cưng', 'Do you have a pet?', 'Bạn có nuôi thú cưng không?', 29),
