  ('30000000-0000-0000-0015-000000000001', '10000000-0000-0000-0000-000000000015', 'happy', 'adj.', '/ˈhæpi/', 'vui vẻ, hạnh phúc', 'She looks happy today.', 'Hôm nay trông cô ấy rất vui.', 1),
  ('30000000-0000-0000-0015-000000000002', '10000000-0000-0000-0000-000000000015', 'sad', 'adj.', '/sæd/', 'buồn', 'He felt sad after the movie.', 'Anh ấy thấy buồn sau bộ phim.', 2),
  ('30000000-0000-0000-0015-000000000003', '10000000-0000-0000-0000-000000000015', 'angry', 'adj.', '/ˈæŋɡri/', 'tức giận', 'My father was angry with me.', 'Bố tôi đã giận tôi.', 3),
  ('30000000-0000-0000-0015-000000000004', '10000000-0000-0000-0000-000000000015', 'nervous', 'adj.', '/ˈnɜːvəs/', 'lo lắng, hồi hộp', 'I feel nervous before an exam.', 'Tôi thấy hồi hộp trước kỳ thi.', 4),
  ('30000000-0000-0000-0015-000000000005', '10000000-0000-0000-0000-000000000015', 'excited', 'adj.', '/ɪkˈsaɪtɪd/', 'hào hứng', 'The children are excited about the trip.', 'Bọn trẻ rất háo hức về chuyến đi.', 5),
  ('30000000-0000-0000-0015-000000000006', '10000000-0000-0000-0000-000000000015', 'bored', 'adj.', '/bɔːd/', 'chán', 'I am bored with this movie.', 'Tôi chán bộ phim này.', 6),
  ('30000000-0000-0000-0015-000000000007', '10000000-0000-0000-0000-000000000015', 'surprised', 'adj.', '/səˈpraɪzd/', 'ngạc nhiên', 'She was surprised by the news.', 'Cô ấy ngạc nhiên trước tin này.', 7),
  ('30000000-0000-0000-0015-000000000008', '10000000-0000-0000-0000-000000000015', 'afraid', 'adj.', '/əˈfreɪd/', 'sợ hãi', 'He is afraid of dogs.', 'Anh ấy sợ chó.', 8),
  ('30000000-0000-0000-0015-000000000009', '10000000-0000-0000-0000-000000000015', 'proud', 'adj.', '/praʊd/', 'tự hào', 'I am proud of you.', 'Tôi tự hào về bạn.', 9),
  ('30000000-0000-0000-0015-000000000010', '10000000-0000-0000-0000-000000000015', 'jealous', 'adj.', '/ˈdʒeləs/', 'ghen tị', 'She is jealous of her sister.', 'Cô ấy ghen tị với em gái.', 10),
  ('30000000-0000-0000-0015-000000000011', '10000000-0000-0000-0000-000000000015', 'lonely', 'adj.', '/ˈləʊnli/', 'cô đơn', 'He felt lonely in the big city.', 'Anh ấy cảm thấy cô đơn ở thành phố lớn.', 11),
  ('30000000-0000-0000-0015-000000000012', '10000000-0000-0000-0000-000000000015', 'worried', 'adj.', '/ˈwʌrid/', 'lo lắng', 'Her mother is worried about her.', 'Mẹ cô ấy lo lắng cho cô.', 12),
  ('30000000-0000-0000-0015-000000000013', '10000000-0000-0000-0000-000000000015', 'confident', 'adj.', '/ˈkɒnfɪdənt/', 'tự tin', 'She is confident about the interview.', 'Cô ấy tự tin về buổi phỏng vấn.', 13),
  ('30000000-0000-0000-0015-000000000014', '10000000-0000-0000-0000-000000000015', 'shy', 'adj.', '/ʃaɪ/', 'nhút nhát, ngại ngùng', 'He is too shy to speak in public.', 'Anh ấy quá nhút nhát để nói trước đám đông.', 14),
  ('30000000-0000-0000-0015-000000000015', '10000000-0000-0000-0000-000000000015', 'friendly', 'adj.', '/ˈfrendli/', 'thân thiện', 'Our new neighbor is very friendly.', 'Người hàng xóm mới của chúng tôi rất thân thiện.', 15),
  ('30000000-0000-0000-0015-000000000016', '10000000-0000-0000-0000-000000000015', 'kind', 'adj.', '/kaɪnd/', 'tốt bụng', 'She is kind to everyone.', 'Cô ấy tốt bụng với mọi người.', 16),
  ('30000000-0000-0000-0015-000000000017', '10000000-0000-0000-0000-000000000015', 'polite', 'adj.', '/pəˈlaɪt/', 'lịch sự', 'The students are polite.', 'Các học sinh rất lịch sự.', 17),
  ('30000000-0000-0000-0015-000000000018', '10000000-0000-0000-0000-000000000015', 'honest', 'adj.', '/ˈɒnɪst/', 'trung thực', 'An honest person never lies.', 'Một người trung thực không bao giờ nói dối.', 18),
  ('30000000-0000-0000-0015-000000000019', '10000000-0000-0000-0000-000000000015', 'generous', 'adj.', '/ˈdʒenərəs/', 'hào phóng', 'He is generous with his time.', 'Anh ấy hào phóng với thời gian của mình.', 19),
  ('30000000-0000-0000-0015-000000000020', '10000000-0000-0000-0000-000000000015', 'patient', 'adj.', '/ˈpeɪʃnt/', 'kiên nhẫn', 'A good teacher must be patient.', 'Một giáo viên giỏi phải biết kiên nhẫn.', 20),
  ('30000000-0000-0000-0015-000000000021', '10000000-0000-0000-0000-000000000015', 'lazy', 'adj.', '/ˈleɪzi/', 'lười biếng', 'He is too lazy to cook.', 'Anh ấy quá lười để nấu ăn.', 21),
  ('30000000-0000-0000-0015-000000000022', '10000000-0000-0000-0000-000000000015', 'hardworking', 'adj.', '/ˌhɑːdˈwɜːkɪŋ/', 'chăm chỉ', 'She is a hardworking student.', 'Cô ấy là một học sinh chăm chỉ.', 22),
  ('30000000-0000-0000-0015-000000000023', '10000000-0000-0000-0000-000000000015', 'creative', 'adj.', '/kriˈeɪtɪv/', 'sáng tạo', 'He has a creative mind.', 'Anh ấy có trí óc sáng tạo.', 23),
  ('30000000-0000-0000-0015-000000000024', '10000000-0000-0000-0000-000000000015', 'curious', 'adj.', '/ˈkjʊəriəs/', 'tò mò', 'Children are naturally curious.', 'Trẻ em vốn tò mò.', 24),
  ('30000000-0000-0000-0015-000000000025', '10000000-0000-0000-0000-000000000015', 'brave', 'adj.', '/breɪv/', 'dũng cảm', 'The firefighter was very brave.', 'Người lính cứu hỏa rất dũng cảm.', 25),
  ('30000000-0000-0000-0015-000000000026', '10000000-0000-0000-0000-000000000015', 'selfish', 'adj.', '/ˈselfɪʃ/', 'ích kỷ', 'Do not be so selfish.', 'Đừng ích kỷ như vậy.', 26),
  ('30000000-0000-0000-0015-000000000027', '10000000-0000-0000-0000-000000000015', 'grateful', 'adj.', '/ˈɡreɪtfl/', 'biết ơn', 'I am grateful for your help.', 'Tôi biết ơn sự giúp đỡ của bạn.', 27),
  ('30000000-0000-0000-0015-000000000028', '10000000-0000-0000-0000-000000000015', 'disappointed', 'adj.', '/ˌdɪsəˈpɔɪntɪd/', 'thất vọng', 'She was disappointed with the result.', 'Cô ấy thất vọng với kết quả.', 28),
  ('30000000-0000-0000-0015-000000000029', '10000000-0000-0000-0000-000000000015', 'embarrassed', 'adj.', '/ɪmˈbærəst/', 'xấu hổ, ngượng', 'He felt embarrassed about his mistake.', 'Anh ấy thấy ngượng về lỗi của mình.', 29),
  ('30000000-0000-0000-0016-000000000001', '10000000-0000-0000-0000-000000000016', 'city', 'n.', '/ˈsɪti/', 'thành phố', 'Ho Chi Minh City is a big city.', 'Thành phố Hồ Chí Minh là một thành phố lớn.', 1),
  ('30000000-0000-0000-0016-000000000002', '10000000-0000-0000-0000-000000000016', 'street', 'n.', '/striːt/', 'đường phố', 'The street is full of people.', 'Đường phố đầy người.', 2),
  ('30000000-0000-0000-0016-000000000003', '10000000-0000-0000-0000-000000000016', 'road', 'n.', '/rəʊd/', 'con đường', 'Be careful when you cross the road.', 'Hãy cẩn thận khi bạn băng qua đường.', 3);
INSERT INTO flashcards (id, topic_id, word, part_of_speech, pronunciation, meaning, example, example_translation, sort_order) VALUES
  ('30000000-0000-0000-0016-000000000004', '10000000-0000-0000-0000-000000000016', 'bridge', 'n.', '/brɪdʒ/', 'cây cầu', 'We walked across the bridge.', 'Chúng tôi đi bộ qua cây cầu.', 4),
  ('30000000-0000-0000-0016-000000000005', '10000000-0000-0000-0000-000000000016', 'traffic', 'n.', '/ˈtræfɪk/', 'giao thông', 'The traffic is terrible this morning.', 'Sáng nay giao thông tệ khủng khiếp.', 5),
  ('30000000-0000-0000-0016-000000000006', '10000000-0000-0000-0000-000000000016', 'bus', 'n.', '/bʌs/', 'xe buýt', 'I go to school by bus.', 'Tôi đi học bằng xe buýt.', 6),
  ('30000000-0000-0000-0016-000000000007', '10000000-0000-0000-0000-000000000016', 'train', 'n.', '/treɪn/', 'tàu hỏa', 'The train leaves at noon.', 'Tàu hỏa khởi hành vào buổi trưa.', 7),
  ('30000000-0000-0000-0016-000000000008', '10000000-0000-0000-0000-000000000016', 'taxi', 'n.', '/ˈtæksi/', 'xe taxi', 'Let us take a taxi.', 'Chúng ta hãy đi taxi.', 8),
  ('30000000-0000-0000-0016-000000000009', '10000000-0000-0000-0000-000000000016', 'bicycle', 'n.', '/ˈbaɪsɪkl/', 'xe đạp', 'He rides a bicycle to work.', 'Anh ấy đạp xe đạp đi làm.', 9),
  ('30000000-0000-0000-0016-000000000010', '10000000-0000-0000-0000-000000000016', 'motorbike', 'n.', '/ˈməʊtəbaɪk/', 'xe máy', 'Many people use a motorbike in Vietnam.', 'Nhiều người dùng xe máy ở Việt Nam.', 10),
  ('30000000-0000-0000-0016-000000000011', '10000000-0000-0000-0000-000000000016', 'subway', 'n.', '/ˈsʌbweɪ/', 'tàu điện ngầm', 'The subway is fast and cheap.', 'Tàu điện ngầm vừa nhanh vừa rẻ.', 11),
  ('30000000-0000-0000-0016-000000000012', '10000000-0000-0000-0000-000000000016', 'station', 'n.', '/ˈsteɪʃn/', 'nhà ga, trạm', 'The station is two blocks away.', 'Nhà ga cách đây hai dãy nhà.', 12),
  ('30000000-0000-0000-0016-000000000013', '10000000-0000-0000-0000-000000000016', 'bus stop', 'n.', '/ˈbʌs stɒp/', 'trạm xe buýt', 'I wait at the bus stop every morning.', 'Tôi đợi ở trạm xe buýt mỗi sáng.', 13),
