INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0001-000000000001', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0000-000000000001', 'Nghĩa của từ "beautiful" là gì?', 1, '"beautiful" /ˈbjuːtɪfl/ (adj.) nghĩa là "đẹp, xinh đẹp". Ví dụ: She is a beautiful girl. - Cô ấy là một cô gái xinh đẹp.', 1),
  ('41000000-0000-0000-0001-000000000002', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000001', 'Từ nào có nghĩa là "thức dậy"?', 0, '"wake up" /weɪk ʌp/ (phr.) nghĩa là "thức dậy". Ví dụ: I wake up at six every morning. - Tôi thức dậy lúc sáu giờ mỗi sáng.', 2),
  ('41000000-0000-0000-0001-000000000003', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000002', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We have ______ at seven."\n(Nghĩa: Chúng tôi ăn sáng lúc bảy giờ.)', 1, '"breakfast" /ˈbrekfəst/ (n.) nghĩa là "bữa sáng". Ví dụ: We have breakfast at seven. - Chúng tôi ăn sáng lúc bảy giờ.', 3),
  ('41000000-0000-0000-0001-000000000004', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000003', 'Nghĩa của từ "lunch" là gì?', 2, '"lunch" /lʌntʃ/ (n.) nghĩa là "bữa trưa". Ví dụ: She eats lunch at school. - Cô ấy ăn trưa ở trường.', 4),
  ('41000000-0000-0000-0001-000000000005', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000004', 'Từ nào có nghĩa là "bữa tối"?', 1, '"dinner" /ˈdɪnə/ (n.) nghĩa là "bữa tối". Ví dụ: Dinner is ready. - Bữa tối đã sẵn sàng.', 5),
  ('41000000-0000-0000-0001-000000000006', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000005', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I take a ______ every night."\n(Nghĩa: Tôi tắm mỗi tối.)', 1, '"shower" /ˈʃaʊə/ (n.) nghĩa là "vòi hoa sen, việc tắm". Ví dụ: I take a shower every night. - Tôi tắm mỗi tối.', 6),
  ('41000000-0000-0000-0001-000000000007', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000006', 'Nghĩa của từ "brush" là gì?', 1, '"brush" /brʌʃ/ (v.) nghĩa là "chải, đánh (răng)". Ví dụ: Please brush your teeth before bed. - Hãy đánh răng trước khi đi ngủ.', 7),
  ('41000000-0000-0000-0001-000000000008', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000007', 'Từ nào có nghĩa là "dọn dẹp, lau chùi"?', 2, '"clean" /kliːn/ (v.) nghĩa là "dọn dẹp, lau chùi". Ví dụ: I clean my room on Sundays. - Tôi dọn phòng vào các ngày Chủ nhật.', 8),
  ('41000000-0000-0000-0001-000000000009', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000008', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My mother likes to ______."\n(Nghĩa: Mẹ tôi thích nấu ăn.)', 2, '"cook" /kʊk/ (v.) nghĩa là "nấu ăn". Ví dụ: My mother likes to cook. - Mẹ tôi thích nấu ăn.', 9),
  ('41000000-0000-0000-0001-000000000010', '40000000-0000-0000-0001-000000000001', '30000000-0000-0000-0001-000000000009', 'Nghĩa của từ "wash" là gì?', 2, '"wash" /wɒʃ/ (v.) nghĩa là "rửa, giặt". Ví dụ: Please wash your hands. - Làm ơn rửa tay.', 10),
  ('41000000-0000-0000-0001-000000000011', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000010', 'Từ nào có nghĩa là "ngủ"?', 0, '"sleep" /sliːp/ (v.) nghĩa là "ngủ". Ví dụ: I sleep eight hours a night. - Tôi ngủ tám tiếng mỗi đêm.', 1),
  ('41000000-0000-0000-0001-000000000012', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000011', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Good ______, everyone!"\n(Nghĩa: Chào buổi sáng mọi người!)', 1, '"morning" /ˈmɔːnɪŋ/ (n.) nghĩa là "buổi sáng". Ví dụ: Good morning, everyone! - Chào buổi sáng mọi người!', 2),
  ('41000000-0000-0000-0001-000000000013', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000012', 'Nghĩa của từ "evening" là gì?', 2, '"evening" /ˈiːvnɪŋ/ (n.) nghĩa là "buổi tối". Ví dụ: We watch TV in the evening. - Chúng tôi xem TV vào buổi tối.', 3),
  ('41000000-0000-0000-0001-000000000014', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000013', 'Từ nào có nghĩa là "cuối tuần"?', 3, '"weekend" /ˌwiːkˈend/ (n.) nghĩa là "cuối tuần". Ví dụ: What do you do at the weekend? - Bạn làm gì vào cuối tuần?', 4),
  ('41000000-0000-0000-0001-000000000015', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000014', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Reading is a good ______."\n(Nghĩa: Đọc sách là một thói quen tốt.)', 0, '"habit" /ˈhæbɪt/ (n.) nghĩa là "thói quen". Ví dụ: Reading is a good habit. - Đọc sách là một thói quen tốt.', 5),
  ('41000000-0000-0000-0001-000000000016', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000015', 'Nghĩa của từ "busy" là gì?', 2, '"busy" /ˈbɪzi/ (adj.) nghĩa là "bận rộn". Ví dụ: I am busy today. - Hôm nay tôi bận.', 6),
  ('41000000-0000-0000-0001-000000000017', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000016', 'Từ nào có nghĩa là "sớm"?', 3, '"early" /ˈɜːli/ (adv.) nghĩa là "sớm". Ví dụ: She gets up early. - Cô ấy dậy sớm.', 7),
  ('41000000-0000-0000-0001-000000000018', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000017', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Don''t be ______ for school."\n(Nghĩa: Đừng đi học muộn.)', 3, '"late" /leɪt/ (adj.) nghĩa là "muộn, trễ". Ví dụ: Don''t be late for school. - Đừng đi học muộn.', 8),
  ('41000000-0000-0000-0001-000000000019', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000018', 'Nghĩa của từ "alarm" là gì?', 3, '"alarm" /əˈlɑːm/ (n.) nghĩa là "chuông báo thức". Ví dụ: My alarm rings at six. - Chuông báo thức của tôi reo lúc sáu giờ.', 9),
  ('41000000-0000-0000-0001-000000000020', '40000000-0000-0000-0001-000000000002', '30000000-0000-0000-0001-000000000019', 'Từ nào có nghĩa là "hàng xóm"?', 2, '"neighbor" /ˈneɪbə/ (n.) nghĩa là "hàng xóm". Ví dụ: Our neighbor is very friendly. - Hàng xóm của chúng tôi rất thân thiện.', 10),
  ('41000000-0000-0000-0001-000000000021', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000020', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We ______ after dinner."\n(Nghĩa: Chúng tôi trò chuyện sau bữa tối.)', 3, '"chat" /tʃæt/ (v.) nghĩa là "trò chuyện". Ví dụ: We chat after dinner. - Chúng tôi trò chuyện sau bữa tối.', 1),
  ('41000000-0000-0000-0001-000000000022', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000021', 'Nghĩa của từ "laundry" là gì?', 2, '"laundry" /ˈlɔːndri/ (n.) nghĩa là "quần áo cần giặt". Ví dụ: I do the laundry on Saturdays. - Tôi giặt quần áo vào thứ Bảy.', 2),
  ('41000000-0000-0000-0001-000000000023', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000022', 'Từ nào có nghĩa là "thói quen hằng ngày"?', 3, '"routine" /ruːˈtiːn/ (n.) nghĩa là "thói quen hằng ngày". Ví dụ: My daily routine is simple. - Thói quen hằng ngày của tôi rất đơn giản.', 3),
  ('41000000-0000-0000-0001-000000000024', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000023', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I ______ by listening to music."\n(Nghĩa: Tôi thư giãn bằng cách nghe nhạc.)', 1, '"relax" /rɪˈlæks/ (v.) nghĩa là "thư giãn". Ví dụ: I relax by listening to music. - Tôi thư giãn bằng cách nghe nhạc.', 4),
  ('41000000-0000-0000-0001-000000000025', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000024', 'Nghĩa của từ "commute" là gì?', 2, '"commute" /kəˈmjuːt/ (v.) nghĩa là "đi làm, đi học hằng ngày". Ví dụ: Many people commute by train. - Nhiều người đi làm hằng ngày bằng tàu.', 5),
  ('41000000-0000-0000-0001-000000000026', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000025', 'Từ nào có nghĩa là "gọn gàng"?', 3, '"tidy" /ˈtaɪdi/ (adj.) nghĩa là "gọn gàng". Ví dụ: Keep your room tidy. - Hãy giữ phòng của bạn gọn gàng.', 6),
  ('41000000-0000-0000-0001-000000000027', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000026', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Washing dishes is my ______."\n(Nghĩa: Rửa bát là việc nhà của tôi.)', 0, '"chore" /tʃɔː/ (n.) nghĩa là "việc nhà". Ví dụ: Washing dishes is my chore. - Rửa bát là việc nhà của tôi.', 7),
  ('41000000-0000-0000-0001-000000000028', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000027', 'Nghĩa của từ "nap" là gì?', 2, '"nap" /næp/ (n.) nghĩa là "giấc ngủ ngắn". Ví dụ: I take a nap after lunch. - Tôi ngủ trưa sau bữa trưa.', 8),
  ('41000000-0000-0000-0001-000000000029', '40000000-0000-0000-0001-000000000003', '30000000-0000-0000-0001-000000000028', 'Từ nào có nghĩa là "lịch trình"?', 1, '"schedule" /ˈʃedjuːl/ (n.) nghĩa là "lịch trình". Ví dụ: I have a busy schedule today. - Hôm nay tôi có lịch trình bận rộn.', 9),
  ('41000000-0000-0000-0002-000000000001', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000001', 'Nghĩa của từ "passport" là gì?', 0, '"passport" /ˈpɑːspɔːt/ (n.) nghĩa là "hộ chiếu". Ví dụ: Don''t forget your passport. - Đừng quên hộ chiếu của bạn.', 1),
  ('41000000-0000-0000-0002-000000000002', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000002', 'Từ nào có nghĩa là "vé"?', 0, '"ticket" /ˈtɪkɪt/ (n.) nghĩa là "vé". Ví dụ: I bought two tickets to Hanoi. - Tôi đã mua hai vé đi Hà Nội.', 2),
  ('41000000-0000-0000-0002-000000000003', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ is very heavy."\n(Nghĩa: Hành lý của tôi rất nặng.)', 1, '"luggage" /ˈlʌɡɪdʒ/ (n.) nghĩa là "hành lý". Ví dụ: My luggage is very heavy. - Hành lý của tôi rất nặng.', 3),
  ('41000000-0000-0000-0002-000000000004', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000004', 'Nghĩa của từ "suitcase" là gì?', 0, '"suitcase" /ˈsuːtkeɪs/ (n.) nghĩa là "va li". Ví dụ: She packed her suitcase last night. - Tối qua cô ấy đã xếp va li.', 4),
  ('41000000-0000-0000-0002-000000000005', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000005', 'Từ nào có nghĩa là "sân bay"?', 2, '"airport" /ˈeəpɔːt/ (n.) nghĩa là "sân bay". Ví dụ: We arrived at the airport early. - Chúng tôi đến sân bay sớm.', 5),
  ('41000000-0000-0000-0002-000000000006', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ takes two hours."\n(Nghĩa: Chuyến bay mất hai tiếng.)', 2, '"flight" /flaɪt/ (n.) nghĩa là "chuyến bay". Ví dụ: The flight takes two hours. - Chuyến bay mất hai tiếng.', 6),
  ('41000000-0000-0000-0002-000000000007', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000007', 'Nghĩa của từ "hotel" là gì?', 2, '"hotel" /həʊˈtel/ (n.) nghĩa là "khách sạn". Ví dụ: We stayed at a small hotel. - Chúng tôi ở một khách sạn nhỏ.', 7),
  ('41000000-0000-0000-0002-000000000008', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000008', 'Từ nào có nghĩa là "sự đặt chỗ"?', 3, '"reservation" /ˌrezəˈveɪʃn/ (n.) nghĩa là "sự đặt chỗ". Ví dụ: I have a reservation for tonight. - Tôi có đặt chỗ cho tối nay.', 8),
  ('41000000-0000-0000-0002-000000000009', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Every ______ loves this beach."\n(Nghĩa: Mọi khách du lịch đều thích bãi biển này.)', 2, '"tourist" /ˈtʊərɪst/ (n.) nghĩa là "khách du lịch". Ví dụ: Every tourist loves this beach. - Mọi khách du lịch đều thích bãi biển này.', 9),
  ('41000000-0000-0000-0002-000000000010', '40000000-0000-0000-0002-000000000001', '30000000-0000-0000-0002-000000000010', 'Nghĩa của từ "journey" là gì?', 3, '"journey" /ˈdʒɜːni/ (n.) nghĩa là "hành trình". Ví dụ: It was a long journey. - Đó là một hành trình dài.', 10),
  ('41000000-0000-0000-0002-000000000011', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000011', 'Từ nào có nghĩa là "điểm đến"?', 0, '"destination" /ˌdestɪˈneɪʃn/ (n.) nghĩa là "điểm đến". Ví dụ: Our destination is Paris. - Điểm đến của chúng tôi là Paris.', 1);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0002-000000000012', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Can you show me on the ______?"\n(Nghĩa: Bạn có thể chỉ cho tôi trên bản đồ không?)', 3, '"map" /mæp/ (n.) nghĩa là "bản đồ". Ví dụ: Can you show me on the map? - Bạn có thể chỉ cho tôi trên bản đồ không?', 2),
  ('41000000-0000-0000-0002-000000000013', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000013', 'Nghĩa của từ "guide" là gì?', 1, '"guide" /ɡaɪd/ (n.) nghĩa là "hướng dẫn viên". Ví dụ: The guide speaks English well. - Hướng dẫn viên nói tiếng Anh tốt.', 3),
  ('41000000-0000-0000-0002-000000000014', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000014', 'Từ nào có nghĩa là "thị thực"?', 1, '"visa" /ˈviːzə/ (n.) nghĩa là "thị thực". Ví dụ: You need a visa to enter this country. - Bạn cần thị thực để vào nước này.', 4),
  ('41000000-0000-0000-0002-000000000015', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Each ______ must wear a seat belt."\n(Nghĩa: Mỗi hành khách phải thắt dây an toàn.)', 3, '"passenger" /ˈpæsɪndʒə/ (n.) nghĩa là "hành khách". Ví dụ: Each passenger must wear a seat belt. - Mỗi hành khách phải thắt dây an toàn.', 5),
  ('41000000-0000-0000-0002-000000000016', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000016', 'Nghĩa của từ "departure" là gì?', 3, '"departure" /dɪˈpɑːtʃə/ (n.) nghĩa là "sự khởi hành". Ví dụ: The departure time is nine a.m. - Giờ khởi hành là chín giờ sáng.', 6),
  ('41000000-0000-0000-0002-000000000017', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000017', 'Từ nào có nghĩa là "sự đến nơi"?', 3, '"arrival" /əˈraɪvl/ (n.) nghĩa là "sự đến nơi". Ví dụ: Our arrival is at noon. - Giờ đến nơi của chúng tôi là giữa trưa.', 7),
  ('41000000-0000-0000-0002-000000000018', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"There is a ______ of one hour."\n(Nghĩa: Có sự chậm trễ một giờ.)', 2, '"delay" /dɪˈleɪ/ (n.) nghĩa là "sự chậm trễ". Ví dụ: There is a delay of one hour. - Có sự chậm trễ một giờ.', 8),
  ('41000000-0000-0000-0002-000000000019', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000019', 'Nghĩa của từ "book" là gì?', 2, '"book" /bʊk/ (v.) nghĩa là "đặt (vé, phòng)". Ví dụ: I want to book a room. - Tôi muốn đặt một phòng.', 9),
  ('41000000-0000-0000-0002-000000000020', '40000000-0000-0000-0002-000000000002', '30000000-0000-0000-0002-000000000020', 'Từ nào có nghĩa là "khám phá"?', 0, '"explore" /ɪkˈsplɔː/ (v.) nghĩa là "khám phá". Ví dụ: We love to explore new cities. - Chúng tôi thích khám phá những thành phố mới.', 10),
  ('41000000-0000-0000-0002-000000000021', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We went ______ in Hue."\n(Nghĩa: Chúng tôi đi tham quan ở Huế.)', 0, '"sightseeing" /ˈsaɪtsiːɪŋ/ (n.) nghĩa là "việc tham quan". Ví dụ: We went sightseeing in Hue. - Chúng tôi đi tham quan ở Huế.', 1),
  ('41000000-0000-0000-0002-000000000022', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000022', 'Nghĩa của từ "souvenir" là gì?', 3, '"souvenir" /ˌsuːvəˈnɪə/ (n.) nghĩa là "quà lưu niệm". Ví dụ: I bought a souvenir for my mother. - Tôi mua một món quà lưu niệm cho mẹ.', 2),
  ('41000000-0000-0000-0002-000000000023', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000023', 'Từ nào có nghĩa là "bãi biển"?', 3, '"beach" /biːtʃ/ (n.) nghĩa là "bãi biển". Ví dụ: The beach is beautiful in summer. - Bãi biển rất đẹp vào mùa hè.', 3),
  ('41000000-0000-0000-0002-000000000024', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"What is the local ______?"\n(Nghĩa: Tiền tệ địa phương là gì?)', 1, '"currency" /ˈkʌrənsi/ (n.) nghĩa là "tiền tệ". Ví dụ: What is the local currency? - Tiền tệ địa phương là gì?', 4),
  ('41000000-0000-0000-0002-000000000025', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000025', 'Nghĩa của từ "customs" là gì?', 3, '"customs" /ˈkʌstəmz/ (n.) nghĩa là "hải quan". Ví dụ: We passed through customs quickly. - Chúng tôi qua hải quan rất nhanh.', 5),
  ('41000000-0000-0000-0002-000000000026', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000026', 'Từ nào có nghĩa là "ba lô"?', 0, '"backpack" /ˈbækpæk/ (n.) nghĩa là "ba lô". Ví dụ: He carries a heavy backpack. - Anh ấy mang một chiếc ba lô nặng.', 6),
  ('41000000-0000-0000-0002-000000000027', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Travel is a great ______."\n(Nghĩa: Du lịch là một cuộc phiêu lưu tuyệt vời.)', 2, '"adventure" /ədˈventʃə/ (n.) nghĩa là "cuộc phiêu lưu". Ví dụ: Travel is a great adventure. - Du lịch là một cuộc phiêu lưu tuyệt vời.', 7),
  ('41000000-0000-0000-0002-000000000028', '40000000-0000-0000-0002-000000000003', '30000000-0000-0000-0002-000000000028', 'Nghĩa của từ "abroad" là gì?', 3, '"abroad" /əˈbrɔːd/ (adv.) nghĩa là "ở nước ngoài". Ví dụ: She studies abroad. - Cô ấy du học ở nước ngoài.', 8),
  ('41000000-0000-0000-0003-000000000001', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000001', 'Nghĩa của từ "apple" là gì?', 1, '"apple" /ˈæpl/ (n.) nghĩa là "quả táo". Ví dụ: I eat an apple every day. - Tôi ăn một quả táo mỗi ngày.', 1),
  ('41000000-0000-0000-0003-000000000002', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000002', 'Từ nào có nghĩa là "quả chuối"?', 0, '"banana" /bəˈnɑːnə/ (n.) nghĩa là "quả chuối". Ví dụ: I want a banana. - Tôi muốn một quả chuối.', 2),
  ('41000000-0000-0000-0003-000000000003', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We need some ______."\n(Nghĩa: Chúng ta cần một ít bánh mì.)', 0, '"bread" /bred/ (n.) nghĩa là "bánh mì". Ví dụ: We need some bread. - Chúng ta cần một ít bánh mì.', 3),
  ('41000000-0000-0000-0003-000000000004', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000004', 'Nghĩa của từ "rice" là gì?', 2, '"rice" /raɪs/ (n.) nghĩa là "gạo, cơm". Ví dụ: Vietnamese people eat rice every day. - Người Việt ăn cơm mỗi ngày.', 4),
  ('41000000-0000-0000-0003-000000000005', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000005', 'Từ nào có nghĩa là "mì, bún, phở"?', 3, '"noodle" /ˈnuːdl/ (n.) nghĩa là "mì, bún, phở". Ví dụ: I like noodle soup. - Tôi thích món mì nước.', 5),
  ('41000000-0000-0000-0003-000000000006', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She boiled an ______."\n(Nghĩa: Cô ấy luộc một quả trứng.)', 3, '"egg" /eɡ/ (n.) nghĩa là "quả trứng". Ví dụ: She boiled an egg. - Cô ấy luộc một quả trứng.', 6),
  ('41000000-0000-0000-0003-000000000007', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000007', 'Nghĩa của từ "milk" là gì?', 2, '"milk" /mɪlk/ (n.) nghĩa là "sữa". Ví dụ: Children should drink milk. - Trẻ em nên uống sữa.', 7),
  ('41000000-0000-0000-0003-000000000008', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000008', 'Từ nào có nghĩa là "nước"?', 3, '"water" /ˈwɔːtə/ (n.) nghĩa là "nước". Ví dụ: Please give me a glass of water. - Làm ơn cho tôi một cốc nước.', 8),
  ('41000000-0000-0000-0003-000000000009', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I drink ______ in the morning."\n(Nghĩa: Tôi uống cà phê vào buổi sáng.)', 1, '"coffee" /ˈkɒfi/ (n.) nghĩa là "cà phê". Ví dụ: I drink coffee in the morning. - Tôi uống cà phê vào buổi sáng.', 9),
  ('41000000-0000-0000-0003-000000000010', '40000000-0000-0000-0003-000000000001', '30000000-0000-0000-0003-000000000010', 'Nghĩa của từ "tea" là gì?', 1, '"tea" /tiː/ (n.) nghĩa là "trà". Ví dụ: Would you like some tea? - Bạn có muốn uống chút trà không?', 10),
  ('41000000-0000-0000-0003-000000000011', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000011', 'Từ nào có nghĩa là "nước ép"?', 2, '"juice" /dʒuːs/ (n.) nghĩa là "nước ép". Ví dụ: Orange juice is my favorite. - Nước cam ép là món tôi thích nhất.', 1),
  ('41000000-0000-0000-0003-000000000012', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He doesn''t eat ______."\n(Nghĩa: Anh ấy không ăn thịt.)', 1, '"meat" /miːt/ (n.) nghĩa là "thịt". Ví dụ: He doesn''t eat meat. - Anh ấy không ăn thịt.', 2),
  ('41000000-0000-0000-0003-000000000013', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000013', 'Nghĩa của từ "chicken" là gì?', 1, '"chicken" /ˈtʃɪkɪn/ (n.) nghĩa là "thịt gà, con gà". Ví dụ: We had chicken for dinner. - Chúng tôi ăn gà vào bữa tối.', 3),
  ('41000000-0000-0000-0003-000000000014', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000014', 'Từ nào có nghĩa là "cá"?', 0, '"fish" /fɪʃ/ (n.) nghĩa là "cá". Ví dụ: Fish is good for your health. - Cá tốt cho sức khỏe của bạn.', 4),
  ('41000000-0000-0000-0003-000000000015', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"A carrot is a ______."\n(Nghĩa: Cà rốt là một loại rau củ.)', 0, '"vegetable" /ˈvedʒtəbl/ (n.) nghĩa là "rau củ". Ví dụ: A carrot is a vegetable. - Cà rốt là một loại rau củ.', 5),
  ('41000000-0000-0000-0003-000000000016', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000016', 'Nghĩa của từ "fruit" là gì?', 1, '"fruit" /fruːt/ (n.) nghĩa là "trái cây". Ví dụ: I eat fruit after lunch. - Tôi ăn trái cây sau bữa trưa.', 6),
  ('41000000-0000-0000-0003-000000000017', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000017', 'Từ nào có nghĩa là "đường"?', 0, '"sugar" /ˈʃʊɡə/ (n.) nghĩa là "đường". Ví dụ: Do you take sugar in your tea? - Bạn có cho đường vào trà không?', 7),
  ('41000000-0000-0000-0003-000000000018', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Pass me the ______, please."\n(Nghĩa: Làm ơn đưa tôi lọ muối.)', 3, '"salt" /sɔːlt/ (n.) nghĩa là "muối". Ví dụ: Pass me the salt, please. - Làm ơn đưa tôi lọ muối.', 8),
  ('41000000-0000-0000-0003-000000000019', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000019', 'Nghĩa của từ "soup" là gì?', 3, '"soup" /suːp/ (n.) nghĩa là "súp, canh". Ví dụ: This soup is delicious. - Món súp này rất ngon.', 9),
  ('41000000-0000-0000-0003-000000000020', '40000000-0000-0000-0003-000000000002', '30000000-0000-0000-0003-000000000020', 'Từ nào có nghĩa là "bánh sandwich"?', 2, '"sandwich" /ˈsænwɪdʒ/ (n.) nghĩa là "bánh sandwich". Ví dụ: He made a cheese sandwich. - Anh ấy làm một chiếc bánh sandwich phô mai.', 10),
  ('41000000-0000-0000-0003-000000000021', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"What is for ______?"\n(Nghĩa: Món tráng miệng là gì?)', 3, '"dessert" /dɪˈzɜːt/ (n.) nghĩa là "món tráng miệng". Ví dụ: What is for dessert? - Món tráng miệng là gì?', 1),
  ('41000000-0000-0000-0003-000000000022', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000022', 'Nghĩa của từ "delicious" là gì?', 3, '"delicious" /dɪˈlɪʃəs/ (adj.) nghĩa là "ngon". Ví dụ: The cake is delicious. - Chiếc bánh rất ngon.', 2),
  ('41000000-0000-0000-0003-000000000023', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000023', 'Từ nào có nghĩa là "đói"?', 1, '"hungry" /ˈhʌŋɡri/ (adj.) nghĩa là "đói". Ví dụ: I am very hungry. - Tôi rất đói.', 3);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0003-000000000024', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She feels ______."\n(Nghĩa: Cô ấy cảm thấy khát.)', 2, '"thirsty" /ˈθɜːsti/ (adj.) nghĩa là "khát". Ví dụ: She feels thirsty. - Cô ấy cảm thấy khát.', 4),
  ('41000000-0000-0000-0003-000000000025', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000025', 'Nghĩa của từ "spicy" là gì?', 0, '"spicy" /ˈspaɪsi/ (adj.) nghĩa là "cay". Ví dụ: I don''t like spicy food. - Tôi không thích đồ ăn cay.', 5),
  ('41000000-0000-0000-0003-000000000026', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000026', 'Từ nào có nghĩa là "thực đơn"?', 0, '"menu" /ˈmenjuː/ (n.) nghĩa là "thực đơn". Ví dụ: Can I see the menu, please? - Cho tôi xem thực đơn được không?', 6),
  ('41000000-0000-0000-0003-000000000027', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Could we have the ______, please?"\n(Nghĩa: Làm ơn cho chúng tôi hóa đơn.)', 0, '"bill" /bɪl/ (n.) nghĩa là "hóa đơn (nhà hàng)". Ví dụ: Could we have the bill, please? - Làm ơn cho chúng tôi hóa đơn.', 7),
  ('41000000-0000-0000-0003-000000000028', '40000000-0000-0000-0003-000000000003', '30000000-0000-0000-0003-000000000028', 'Nghĩa của từ "order" là gì?', 2, '"order" /ˈɔːdə/ (v.) nghĩa là "gọi món". Ví dụ: I would like to order now. - Tôi muốn gọi món bây giờ.', 8),
  ('41000000-0000-0000-0004-000000000001', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000001', 'Nghĩa của từ "computer" là gì?', 1, '"computer" /kəmˈpjuːtə/ (n.) nghĩa là "máy tính". Ví dụ: My computer is very fast. - Máy tính của tôi rất nhanh.', 1),
  ('41000000-0000-0000-0004-000000000002', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000002', 'Từ nào có nghĩa là "máy tính xách tay"?', 1, '"laptop" /ˈlæptɒp/ (n.) nghĩa là "máy tính xách tay". Ví dụ: She works on her laptop. - Cô ấy làm việc trên máy tính xách tay.', 2),
  ('41000000-0000-0000-0004-000000000003', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I bought a new ______."\n(Nghĩa: Tôi đã mua một chiếc điện thoại thông minh mới.)', 0, '"smartphone" /ˈsmɑːtfəʊn/ (n.) nghĩa là "điện thoại thông minh". Ví dụ: I bought a new smartphone. - Tôi đã mua một chiếc điện thoại thông minh mới.', 3),
  ('41000000-0000-0000-0004-000000000004', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000004', 'Nghĩa của từ "internet" là gì?', 3, '"internet" /ˈɪntənet/ (n.) nghĩa là "mạng Internet". Ví dụ: The internet is down. - Mạng Internet bị mất.', 4),
  ('41000000-0000-0000-0004-000000000005', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000005', 'Từ nào có nghĩa là "trang web"?', 2, '"website" /ˈwebsaɪt/ (n.) nghĩa là "trang web". Ví dụ: Visit our website for more information. - Hãy truy cập trang web của chúng tôi để biết thêm thông tin.', 5),
  ('41000000-0000-0000-0004-000000000006', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This ______ is free."\n(Nghĩa: Phần mềm này miễn phí.)', 1, '"software" /ˈsɒftweə/ (n.) nghĩa là "phần mềm". Ví dụ: This software is free. - Phần mềm này miễn phí.', 6),
  ('41000000-0000-0000-0004-000000000007', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000007', 'Nghĩa của từ "download" là gì?', 0, '"download" /ˌdaʊnˈləʊd/ (v.) nghĩa là "tải xuống". Ví dụ: You can download the app for free. - Bạn có thể tải ứng dụng miễn phí.', 7),
  ('41000000-0000-0000-0004-000000000008', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000008', 'Từ nào có nghĩa là "tải lên"?', 3, '"upload" /ˌʌpˈləʊd/ (v.) nghĩa là "tải lên". Ví dụ: I will upload the photos tonight. - Tối nay tôi sẽ tải ảnh lên.', 8),
  ('41000000-0000-0000-0004-000000000009', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Never share your ______."\n(Nghĩa: Đừng bao giờ chia sẻ mật khẩu của bạn.)', 2, '"password" /ˈpɑːswɜːd/ (n.) nghĩa là "mật khẩu". Ví dụ: Never share your password. - Đừng bao giờ chia sẻ mật khẩu của bạn.', 9),
  ('41000000-0000-0000-0004-000000000010', '40000000-0000-0000-0004-000000000001', '30000000-0000-0000-0004-000000000010', 'Nghĩa của từ "screen" là gì?', 1, '"screen" /skriːn/ (n.) nghĩa là "màn hình". Ví dụ: The screen is too bright. - Màn hình quá sáng.', 10),
  ('41000000-0000-0000-0004-000000000011', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000011', 'Từ nào có nghĩa là "bàn phím"?', 1, '"keyboard" /ˈkiːbɔːd/ (n.) nghĩa là "bàn phím". Ví dụ: This keyboard is comfortable. - Bàn phím này rất thoải mái.', 1),
  ('41000000-0000-0000-0004-000000000012', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ is low."\n(Nghĩa: Pin của tôi sắp hết.)', 2, '"battery" /ˈbætri/ (n.) nghĩa là "pin". Ví dụ: My battery is low. - Pin của tôi sắp hết.', 2),
  ('41000000-0000-0000-0004-000000000013', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000013', 'Nghĩa của từ "charge" là gì?', 0, '"charge" /tʃɑːdʒ/ (v.) nghĩa là "sạc". Ví dụ: I need to charge my phone. - Tôi cần sạc điện thoại.', 3),
  ('41000000-0000-0000-0004-000000000014', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000014', 'Từ nào có nghĩa là "cài đặt"?', 0, '"install" /ɪnˈstɔːl/ (v.) nghĩa là "cài đặt". Ví dụ: Please install the update. - Vui lòng cài đặt bản cập nhật.', 4),
  ('41000000-0000-0000-0004-000000000015', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"There is a new ______ available."\n(Nghĩa: Có một bản cập nhật mới.)', 1, '"update" /ˈʌpdeɪt/ (n.) nghĩa là "bản cập nhật". Ví dụ: There is a new update available. - Có một bản cập nhật mới.', 5),
  ('41000000-0000-0000-0004-000000000016', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000016', 'Nghĩa của từ "network" là gì?', 2, '"network" /ˈnetwɜːk/ (n.) nghĩa là "mạng lưới". Ví dụ: The network is very slow today. - Hôm nay mạng rất chậm.', 6),
  ('41000000-0000-0000-0004-000000000017', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000017', 'Từ nào có nghĩa là "dữ liệu"?', 1, '"data" /ˈdeɪtə/ (n.) nghĩa là "dữ liệu". Ví dụ: We store the data in the cloud. - Chúng tôi lưu dữ liệu trên đám mây.', 7),
  ('41000000-0000-0000-0004-000000000018', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This ______ is easy to use."\n(Nghĩa: Ứng dụng này dễ sử dụng.)', 3, '"application" /ˌæplɪˈkeɪʃn/ (n.) nghĩa là "ứng dụng". Ví dụ: This application is easy to use. - Ứng dụng này dễ sử dụng.', 8),
  ('41000000-0000-0000-0004-000000000019', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000019', 'Nghĩa của từ "robot" là gì?', 1, '"robot" /ˈrəʊbɒt/ (n.) nghĩa là "người máy". Ví dụ: The robot cleans the floor. - Người máy lau sàn nhà.', 9),
  ('41000000-0000-0000-0004-000000000020', '40000000-0000-0000-0004-000000000002', '30000000-0000-0000-0004-000000000020', 'Từ nào có nghĩa là "máy ảnh"?', 2, '"camera" /ˈkæmərə/ (n.) nghĩa là "máy ảnh". Ví dụ: This phone has a great camera. - Chiếc điện thoại này có camera rất tốt.', 10),
  ('41000000-0000-0000-0004-000000000021', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I study English ______."\n(Nghĩa: Tôi học tiếng Anh trực tuyến.)', 0, '"online" /ˌɒnˈlaɪn/ (adj.) nghĩa là "trực tuyến". Ví dụ: I study English online. - Tôi học tiếng Anh trực tuyến.', 1),
  ('41000000-0000-0000-0004-000000000022', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000022', 'Nghĩa của từ "digital" là gì?', 0, '"digital" /ˈdɪdʒɪtl/ (adj.) nghĩa là "kỹ thuật số". Ví dụ: We live in a digital world. - Chúng ta sống trong thế giới kỹ thuật số.', 2),
  ('41000000-0000-0000-0004-000000000023', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000023', 'Từ nào có nghĩa là "vi-rút"?', 2, '"virus" /ˈvaɪrəs/ (n.) nghĩa là "vi-rút". Ví dụ: My computer has a virus. - Máy tính của tôi bị nhiễm vi-rút.', 3),
  ('41000000-0000-0000-0004-000000000024', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Save the file to the ______."\n(Nghĩa: Hãy lưu tập tin lên đám mây.)', 2, '"cloud" /klaʊd/ (n.) nghĩa là "đám mây (lưu trữ)". Ví dụ: Save the file to the cloud. - Hãy lưu tập tin lên đám mây.', 4),
  ('41000000-0000-0000-0004-000000000025', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000025', 'Nghĩa của từ "technology" là gì?', 0, '"technology" /tekˈnɒlədʒi/ (n.) nghĩa là "công nghệ". Ví dụ: Technology makes life easier. - Công nghệ làm cuộc sống dễ dàng hơn.', 5),
  ('41000000-0000-0000-0004-000000000026', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000026', 'Từ nào có nghĩa là "thiết bị"?', 2, '"device" /dɪˈvaɪs/ (n.) nghĩa là "thiết bị". Ví dụ: This device is waterproof. - Thiết bị này chống nước.', 6),
  ('41000000-0000-0000-0004-000000000027', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I use ______ headphones."\n(Nghĩa: Tôi dùng tai nghe không dây.)', 0, '"wireless" /ˈwaɪələs/ (adj.) nghĩa là "không dây". Ví dụ: I use wireless headphones. - Tôi dùng tai nghe không dây.', 7),
  ('41000000-0000-0000-0004-000000000028', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000028', 'Nghĩa của từ "search" là gì?', 0, '"search" /sɜːtʃ/ (v.) nghĩa là "tìm kiếm". Ví dụ: Let us search for it online. - Chúng ta hãy tìm kiếm nó trên mạng.', 8),
  ('41000000-0000-0000-0004-000000000029', '40000000-0000-0000-0004-000000000003', '30000000-0000-0000-0004-000000000029', 'Từ nào có nghĩa là "trí tuệ nhân tạo"?', 1, '"artificial intelligence" /ˌɑːtɪfɪʃl ɪnˈtelɪdʒəns/ (n.) nghĩa là "trí tuệ nhân tạo". Ví dụ: Artificial intelligence is changing our lives. - Trí tuệ nhân tạo đang thay đổi cuộc sống của chúng ta.', 9),
  ('41000000-0000-0000-0005-000000000001', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0000-000000000002', 'Nghĩa của từ "opportunity" là gì?', 3, '"opportunity" /ˌɒpəˈtjuːnəti/ (n.) nghĩa là "cơ hội". Ví dụ: This is a great opportunity for you. - Đây là một cơ hội tuyệt vời cho bạn.', 1),
  ('41000000-0000-0000-0005-000000000002', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000001', 'Từ nào có nghĩa là "công ty"?', 0, '"company" /ˈkʌmpəni/ (n.) nghĩa là "công ty". Ví dụ: She works for a large company. - Cô ấy làm việc cho một công ty lớn.', 2),
  ('41000000-0000-0000-0005-000000000003', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000002', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is in a meeting."\n(Nghĩa: Quản lý đang họp.)', 3, '"manager" /ˈmænɪdʒə/ (n.) nghĩa là "quản lý". Ví dụ: The manager is in a meeting. - Quản lý đang họp.', 3),
  ('41000000-0000-0000-0005-000000000004', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000003', 'Nghĩa của từ "employee" là gì?', 3, '"employee" /ɪmˈplɔɪiː/ (n.) nghĩa là "nhân viên". Ví dụ: Each employee gets a bonus. - Mỗi nhân viên nhận được một khoản thưởng.', 4),
  ('41000000-0000-0000-0005-000000000005', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000004', 'Từ nào có nghĩa là "khách hàng"?', 0, '"customer" /ˈkʌstəmə/ (n.) nghĩa là "khách hàng". Ví dụ: The customer is always right. - Khách hàng luôn luôn đúng.', 5),
  ('41000000-0000-0000-0005-000000000006', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000005', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We have a ______ at ten."\n(Nghĩa: Chúng tôi có một cuộc họp lúc mười giờ.)', 1, '"meeting" /ˈmiːtɪŋ/ (n.) nghĩa là "cuộc họp". Ví dụ: We have a meeting at ten. - Chúng tôi có một cuộc họp lúc mười giờ.', 6);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0005-000000000007', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000006', 'Nghĩa của từ "contract" là gì?', 3, '"contract" /ˈkɒntrækt/ (n.) nghĩa là "hợp đồng". Ví dụ: Please sign the contract. - Vui lòng ký hợp đồng.', 7),
  ('41000000-0000-0000-0005-000000000008', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000007', 'Từ nào có nghĩa là "lợi nhuận"?', 3, '"profit" /ˈprɒfɪt/ (n.) nghĩa là "lợi nhuận". Ví dụ: The company made a big profit. - Công ty đã thu được lợi nhuận lớn.', 8),
  ('41000000-0000-0000-0005-000000000009', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000008', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Her ______ is paid monthly."\n(Nghĩa: Lương của cô ấy được trả hằng tháng.)', 1, '"salary" /ˈsæləri/ (n.) nghĩa là "tiền lương". Ví dụ: Her salary is paid monthly. - Lương của cô ấy được trả hằng tháng.', 9),
  ('41000000-0000-0000-0005-000000000010', '40000000-0000-0000-0005-000000000001', '30000000-0000-0000-0005-000000000009', 'Nghĩa của từ "budget" là gì?', 2, '"budget" /ˈbʌdʒɪt/ (n.) nghĩa là "ngân sách". Ví dụ: We have a small budget. - Chúng tôi có ngân sách nhỏ.', 10),
  ('41000000-0000-0000-0005-000000000011', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000010', 'Từ nào có nghĩa là "hạn chót"?', 2, '"deadline" /ˈdedlaɪn/ (n.) nghĩa là "hạn chót". Ví dụ: The deadline is Friday. - Hạn chót là thứ Sáu.', 1),
  ('41000000-0000-0000-0005-000000000012', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000011', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This ______ is very important."\n(Nghĩa: Dự án này rất quan trọng.)', 3, '"project" /ˈprɒdʒekt/ (n.) nghĩa là "dự án". Ví dụ: This project is very important. - Dự án này rất quan trọng.', 2),
  ('41000000-0000-0000-0005-000000000013', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000012', 'Nghĩa của từ "client" là gì?', 1, '"client" /ˈklaɪənt/ (n.) nghĩa là "khách hàng (dịch vụ)". Ví dụ: We have a meeting with a new client. - Chúng tôi có cuộc họp với một khách hàng mới.', 3),
  ('41000000-0000-0000-0005-000000000014', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000013', 'Từ nào có nghĩa là "thị trường"?', 2, '"market" /ˈmɑːkɪt/ (n.) nghĩa là "thị trường". Ví dụ: The market is growing fast. - Thị trường đang phát triển nhanh.', 4),
  ('41000000-0000-0000-0005-000000000015', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000014', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This ______ sells well."\n(Nghĩa: Sản phẩm này bán rất chạy.)', 1, '"product" /ˈprɒdʌkt/ (n.) nghĩa là "sản phẩm". Ví dụ: This product sells well. - Sản phẩm này bán rất chạy.', 5),
  ('41000000-0000-0000-0005-000000000016', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000015', 'Nghĩa của từ "price" là gì?', 2, '"price" /praɪs/ (n.) nghĩa là "giá cả". Ví dụ: The price is too high. - Giá quá cao.', 6),
  ('41000000-0000-0000-0005-000000000017', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000016', 'Từ nào có nghĩa là "việc bán hàng, đợt giảm giá"?', 0, '"sale" /seɪl/ (n.) nghĩa là "việc bán hàng, đợt giảm giá". Ví dụ: The sale ends tomorrow. - Đợt giảm giá kết thúc vào ngày mai.', 7),
  ('41000000-0000-0000-0005-000000000018', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000017', 'Chọn từ thích hợp để điền vào chỗ trống:\n"They ______ on television."\n(Nghĩa: Họ quảng cáo trên truyền hình.)', 0, '"advertise" /ˈædvətaɪz/ (v.) nghĩa là "quảng cáo". Ví dụ: They advertise on television. - Họ quảng cáo trên truyền hình.', 8),
  ('41000000-0000-0000-0005-000000000019', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000018', 'Nghĩa của từ "negotiate" là gì?', 0, '"negotiate" /nɪˈɡəʊʃieɪt/ (v.) nghĩa là "đàm phán". Ví dụ: We need to negotiate the price. - Chúng ta cần đàm phán về giá.', 9),
  ('41000000-0000-0000-0005-000000000020', '40000000-0000-0000-0005-000000000002', '30000000-0000-0000-0005-000000000019', 'Từ nào có nghĩa là "đầu tư"?', 3, '"invest" /ɪnˈvest/ (v.) nghĩa là "đầu tư". Ví dụ: He wants to invest in a new business. - Anh ấy muốn đầu tư vào một công việc kinh doanh mới.', 10),
  ('41000000-0000-0000-0005-000000000021', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000020', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We ______ coffee to many countries."\n(Nghĩa: Chúng tôi xuất khẩu cà phê sang nhiều nước.)', 1, '"export" /ɪkˈspɔːt/ (v.) nghĩa là "xuất khẩu". Ví dụ: We export coffee to many countries. - Chúng tôi xuất khẩu cà phê sang nhiều nước.', 1),
  ('41000000-0000-0000-0005-000000000022', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000021', 'Nghĩa của từ "import" là gì?', 0, '"import" /ɪmˈpɔːt/ (v.) nghĩa là "nhập khẩu". Ví dụ: We import machines from Japan. - Chúng tôi nhập khẩu máy móc từ Nhật Bản.', 2),
  ('41000000-0000-0000-0005-000000000023', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000022', 'Từ nào có nghĩa là "đối tác"?', 2, '"partner" /ˈpɑːtnə/ (n.) nghĩa là "đối tác". Ví dụ: He is my business partner. - Anh ấy là đối tác kinh doanh của tôi.', 3),
  ('41000000-0000-0000-0005-000000000024', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000023', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ wants to see you."\n(Nghĩa: Giám đốc muốn gặp bạn.)', 0, '"director" /dəˈrektə/ (n.) nghĩa là "giám đốc". Ví dụ: The director wants to see you. - Giám đốc muốn gặp bạn.', 4),
  ('41000000-0000-0000-0005-000000000025', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000024', 'Nghĩa của từ "presentation" là gì?', 1, '"presentation" /ˌpreznˈteɪʃn/ (n.) nghĩa là "bài thuyết trình". Ví dụ: She gave a great presentation. - Cô ấy đã có một bài thuyết trình tuyệt vời.', 5),
  ('41000000-0000-0000-0005-000000000026', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000025', 'Từ nào có nghĩa là "báo cáo"?', 3, '"report" /rɪˈpɔːt/ (n.) nghĩa là "báo cáo". Ví dụ: I must finish the report today. - Hôm nay tôi phải hoàn thành báo cáo.', 6),
  ('41000000-0000-0000-0005-000000000027', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000026', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Please send me the ______."\n(Nghĩa: Vui lòng gửi cho tôi hóa đơn.)', 2, '"invoice" /ˈɪnvɔɪs/ (n.) nghĩa là "hóa đơn thương mại". Ví dụ: Please send me the invoice. - Vui lòng gửi cho tôi hóa đơn.', 7),
  ('41000000-0000-0000-0005-000000000028', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000027', 'Nghĩa của từ "competitor" là gì?', 0, '"competitor" /kəmˈpetɪtə/ (n.) nghĩa là "đối thủ cạnh tranh". Ví dụ: Our main competitor lowered its prices. - Đối thủ cạnh tranh chính của chúng tôi đã hạ giá.', 8),
  ('41000000-0000-0000-0005-000000000029', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000028', 'Từ nào có nghĩa là "từ chức"?', 1, '"resign" /rɪˈzaɪn/ (v.) nghĩa là "từ chức". Ví dụ: He decided to resign. - Anh ấy quyết định từ chức.', 9),
  ('41000000-0000-0000-0005-000000000030', '40000000-0000-0000-0005-000000000003', '30000000-0000-0000-0005-000000000029', 'Chọn từ thích hợp để điền vào chỗ trống:\n"They ______ good employees."\n(Nghĩa: Họ thăng chức cho những nhân viên giỏi.)', 0, '"promote" /prəˈməʊt/ (v.) nghĩa là "thăng chức, quảng bá". Ví dụ: They promote good employees. - Họ thăng chức cho những nhân viên giỏi.', 10),
  ('41000000-0000-0000-0006-000000000001', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000001', 'Nghĩa của từ "family" là gì?', 3, '"family" /ˈfæməli/ (n.) nghĩa là "gia đình". Ví dụ: I love my family. - Tôi yêu gia đình tôi.', 1),
  ('41000000-0000-0000-0006-000000000002', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000002', 'Từ nào có nghĩa là "cha hoặc mẹ"?', 2, '"parent" /ˈpeərənt/ (n.) nghĩa là "cha hoặc mẹ". Ví dụ: Her parent works at a bank. - Cha (hoặc mẹ) của cô ấy làm việc ở ngân hàng.', 2),
  ('41000000-0000-0000-0006-000000000003', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ is a teacher."\n(Nghĩa: Mẹ tôi là giáo viên.)', 2, '"mother" /ˈmʌðə/ (n.) nghĩa là "mẹ". Ví dụ: My mother is a teacher. - Mẹ tôi là giáo viên.', 3),
  ('41000000-0000-0000-0006-000000000004', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000004', 'Nghĩa của từ "father" là gì?', 1, '"father" /ˈfɑːðə/ (n.) nghĩa là "bố". Ví dụ: My father drives a taxi. - Bố tôi lái xe taxi.', 4),
  ('41000000-0000-0000-0006-000000000005', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000005', 'Từ nào có nghĩa là "anh, em trai"?', 3, '"brother" /ˈbrʌðə/ (n.) nghĩa là "anh, em trai". Ví dụ: I have one brother. - Tôi có một người anh (em) trai.', 5),
  ('41000000-0000-0000-0006-000000000006', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ is ten years old."\n(Nghĩa: Em gái tôi mười tuổi.)', 1, '"sister" /ˈsɪstə/ (n.) nghĩa là "chị, em gái". Ví dụ: My sister is ten years old. - Em gái tôi mười tuổi.', 6),
  ('41000000-0000-0000-0006-000000000007', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000007', 'Nghĩa của từ "son" là gì?', 0, '"son" /sʌn/ (n.) nghĩa là "con trai". Ví dụ: They have a son. - Họ có một cậu con trai.', 7),
  ('41000000-0000-0000-0006-000000000008', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000008', 'Từ nào có nghĩa là "con gái"?', 1, '"daughter" /ˈdɔːtə/ (n.) nghĩa là "con gái". Ví dụ: Their daughter is very smart. - Con gái của họ rất thông minh.', 8),
  ('41000000-0000-0000-0006-000000000009', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ tells great stories."\n(Nghĩa: Bà tôi kể những câu chuyện hay.)', 3, '"grandmother" /ˈɡrænmʌðə/ (n.) nghĩa là "bà". Ví dụ: My grandmother tells great stories. - Bà tôi kể những câu chuyện hay.', 9),
  ('41000000-0000-0000-0006-000000000010', '40000000-0000-0000-0006-000000000001', '30000000-0000-0000-0006-000000000010', 'Nghĩa của từ "grandfather" là gì?', 3, '"grandfather" /ˈɡrænfɑːðə/ (n.) nghĩa là "ông". Ví dụ: My grandfather lives in the countryside. - Ông tôi sống ở quê.', 10),
  ('41000000-0000-0000-0006-000000000011', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000011', 'Từ nào có nghĩa là "chú, bác, cậu"?', 0, '"uncle" /ˈʌŋkl/ (n.) nghĩa là "chú, bác, cậu". Ví dụ: My uncle is a doctor. - Chú tôi là bác sĩ.', 1),
  ('41000000-0000-0000-0006-000000000012', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ lives in Hue."\n(Nghĩa: Dì tôi sống ở Huế.)', 0, '"aunt" /ɑːnt/ (n.) nghĩa là "cô, dì, thím". Ví dụ: My aunt lives in Hue. - Dì tôi sống ở Huế.', 2),
  ('41000000-0000-0000-0006-000000000013', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000013', 'Nghĩa của từ "cousin" là gì?', 1, '"cousin" /ˈkʌzn/ (n.) nghĩa là "anh chị em họ". Ví dụ: My cousin visits us every summer. - Anh họ tôi đến thăm chúng tôi mỗi mùa hè.', 3),
  ('41000000-0000-0000-0006-000000000014', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000014', 'Từ nào có nghĩa là "chồng"?', 3, '"husband" /ˈhʌzbənd/ (n.) nghĩa là "chồng". Ví dụ: Her husband is a chef. - Chồng cô ấy là đầu bếp.', 4),
  ('41000000-0000-0000-0006-000000000015', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"His ______ works at a hospital."\n(Nghĩa: Vợ anh ấy làm việc ở bệnh viện.)', 0, '"wife" /waɪf/ (n.) nghĩa là "vợ". Ví dụ: His wife works at a hospital. - Vợ anh ấy làm việc ở bệnh viện.', 5),
  ('41000000-0000-0000-0006-000000000016', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000016', 'Nghĩa của từ "baby" là gì?', 2, '"baby" /ˈbeɪbi/ (n.) nghĩa là "em bé". Ví dụ: The baby is sleeping. - Em bé đang ngủ.', 6);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0006-000000000017', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000017', 'Từ nào có nghĩa là "đứa trẻ"?', 3, '"child" /tʃaɪld/ (n.) nghĩa là "đứa trẻ". Ví dụ: Every child needs love. - Mỗi đứa trẻ đều cần tình thương.', 7),
  ('41000000-0000-0000-0006-000000000018', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She is my best ______."\n(Nghĩa: Cô ấy là bạn thân nhất của tôi.)', 0, '"friend" /frend/ (n.) nghĩa là "bạn bè". Ví dụ: She is my best friend. - Cô ấy là bạn thân nhất của tôi.', 8),
  ('41000000-0000-0000-0006-000000000019', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000019', 'Nghĩa của từ "classmate" là gì?', 3, '"classmate" /ˈklɑːsmeɪt/ (n.) nghĩa là "bạn cùng lớp". Ví dụ: My classmate helps me with math. - Bạn cùng lớp giúp tôi học toán.', 9),
  ('41000000-0000-0000-0006-000000000020', '40000000-0000-0000-0006-000000000002', '30000000-0000-0000-0006-000000000020', 'Từ nào có nghĩa là "họ hàng"?', 1, '"relative" /ˈrelətɪv/ (n.) nghĩa là "họ hàng". Ví dụ: Many relatives came to the party. - Nhiều họ hàng đã đến dự bữa tiệc.', 10),
  ('41000000-0000-0000-0006-000000000021', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"They are ______."\n(Nghĩa: Họ đã kết hôn.)', 1, '"married" /ˈmærid/ (adj.) nghĩa là "đã kết hôn". Ví dụ: They are married. - Họ đã kết hôn.', 1),
  ('41000000-0000-0000-0006-000000000022', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000022', 'Nghĩa của từ "single" là gì?', 2, '"single" /ˈsɪŋɡl/ (adj.) nghĩa là "độc thân". Ví dụ: He is single. - Anh ấy còn độc thân.', 2),
  ('41000000-0000-0000-0006-000000000023', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000023', 'Từ nào có nghĩa là "anh chị em sinh đôi"?', 0, '"twin" /twɪn/ (n.) nghĩa là "anh chị em sinh đôi". Ví dụ: She has a twin sister. - Cô ấy có một người chị (em) sinh đôi.', 3),
  ('41000000-0000-0000-0006-000000000024', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000024', 'Nghĩa của từ "generation" là gì?', 2, '"generation" /ˌdʒenəˈreɪʃn/ (n.) nghĩa là "thế hệ". Ví dụ: Three generations live in this house. - Ba thế hệ sống trong ngôi nhà này.', 4),
  ('41000000-0000-0000-0006-000000000025', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000025', 'Nghĩa của từ "neighbour" là gì?', 3, '"neighbour" /ˈneɪbə/ (n.) nghĩa là "người hàng xóm". Ví dụ: Our neighbour brings us fruit. - Hàng xóm mang trái cây cho chúng tôi.', 5),
  ('41000000-0000-0000-0006-000000000026', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000026', 'Từ nào có nghĩa là "sinh nhật"?', 0, '"birthday" /ˈbɜːθdeɪ/ (n.) nghĩa là "sinh nhật". Ví dụ: Today is my birthday. - Hôm nay là sinh nhật của tôi.', 6),
  ('41000000-0000-0000-0006-000000000027', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We went to her ______."\n(Nghĩa: Chúng tôi đã đến dự đám cưới của cô ấy.)', 1, '"wedding" /ˈwedɪŋ/ (n.) nghĩa là "đám cưới". Ví dụ: We went to her wedding. - Chúng tôi đã đến dự đám cưới của cô ấy.', 7),
  ('41000000-0000-0000-0006-000000000028', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000028', 'Nghĩa của từ "together" là gì?', 1, '"together" /təˈɡeðə/ (adv.) nghĩa là "cùng nhau". Ví dụ: We have dinner together. - Chúng tôi ăn tối cùng nhau.', 8),
  ('41000000-0000-0000-0006-000000000029', '40000000-0000-0000-0006-000000000003', '30000000-0000-0000-0006-000000000029', 'Từ nào có nghĩa là "hòa thuận"?', 0, '"get along" /ɡet əˈlɒŋ/ (phr.) nghĩa là "hòa thuận". Ví dụ: I get along with my sister. - Tôi hòa thuận với em gái.', 9),
  ('41000000-0000-0000-0007-000000000001', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000001', 'Nghĩa của từ "school" là gì?', 3, '"school" /skuːl/ (n.) nghĩa là "trường học". Ví dụ: My school is near my house. - Trường của tôi ở gần nhà tôi.', 1),
  ('41000000-0000-0000-0007-000000000002', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000002', 'Từ nào có nghĩa là "giáo viên"?', 2, '"teacher" /ˈtiːtʃə/ (n.) nghĩa là "giáo viên". Ví dụ: Our teacher is very kind. - Giáo viên của chúng tôi rất tốt bụng.', 2),
  ('41000000-0000-0000-0007-000000000003', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He is a good ______."\n(Nghĩa: Cậu ấy là một học sinh giỏi.)', 3, '"student" /ˈstjuːdnt/ (n.) nghĩa là "học sinh, sinh viên". Ví dụ: He is a good student. - Cậu ấy là một học sinh giỏi.', 3),
  ('41000000-0000-0000-0007-000000000004', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000004', 'Nghĩa của từ "classroom" là gì?', 0, '"classroom" /ˈklɑːsruːm/ (n.) nghĩa là "lớp học". Ví dụ: The classroom is clean. - Lớp học rất sạch sẽ.', 4),
  ('41000000-0000-0000-0007-000000000005', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000005', 'Từ nào có nghĩa là "bài học"?', 2, '"lesson" /ˈlesn/ (n.) nghĩa là "bài học". Ví dụ: Today''s lesson is about animals. - Bài học hôm nay nói về động vật.', 5),
  ('41000000-0000-0000-0007-000000000006', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I finish my ______ before dinner."\n(Nghĩa: Tôi làm xong bài tập về nhà trước bữa tối.)', 1, '"homework" /ˈhəʊmwɜːk/ (n.) nghĩa là "bài tập về nhà". Ví dụ: I finish my homework before dinner. - Tôi làm xong bài tập về nhà trước bữa tối.', 6),
  ('41000000-0000-0000-0007-000000000007', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000007', 'Nghĩa của từ "exam" là gì?', 0, '"exam" /ɪɡˈzæm/ (n.) nghĩa là "kỳ thi". Ví dụ: The exam starts at eight. - Kỳ thi bắt đầu lúc tám giờ.', 7),
  ('41000000-0000-0000-0007-000000000008', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000008', 'Từ nào có nghĩa là "bài kiểm tra"?', 3, '"test" /test/ (n.) nghĩa là "bài kiểm tra". Ví dụ: We have a test on Friday. - Chúng tôi có bài kiểm tra vào thứ Sáu.', 8),
  ('41000000-0000-0000-0007-000000000009', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This ______ is very interesting."\n(Nghĩa: Quyển sách này rất thú vị.)', 2, '"book" /bʊk/ (n.) nghĩa là "quyển sách". Ví dụ: This book is very interesting. - Quyển sách này rất thú vị.', 9),
  ('41000000-0000-0000-0007-000000000010', '40000000-0000-0000-0007-000000000001', '30000000-0000-0000-0007-000000000010', 'Nghĩa của từ "notebook" là gì?', 0, '"notebook" /ˈnəʊtbʊk/ (n.) nghĩa là "vở ghi chép". Ví dụ: I write new words in my notebook. - Tôi viết từ mới vào vở.', 10),
  ('41000000-0000-0000-0007-000000000011', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000011', 'Từ nào có nghĩa là "bút chì"?', 2, '"pencil" /ˈpensl/ (n.) nghĩa là "bút chì". Ví dụ: Can I borrow your pencil? - Tôi mượn bút chì của bạn được không?', 1),
  ('41000000-0000-0000-0007-000000000012', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This ______ does not work."\n(Nghĩa: Cây bút này không viết được.)', 3, '"pen" /pen/ (n.) nghĩa là "bút mực". Ví dụ: This pen does not work. - Cây bút này không viết được.', 2),
  ('41000000-0000-0000-0007-000000000013', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000013', 'Nghĩa của từ "ruler" là gì?', 0, '"ruler" /ˈruːlə/ (n.) nghĩa là "thước kẻ". Ví dụ: Use a ruler to draw a straight line. - Hãy dùng thước kẻ để vẽ một đường thẳng.', 3),
  ('41000000-0000-0000-0007-000000000014', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000014', 'Từ nào có nghĩa là "từ điển"?', 2, '"dictionary" /ˈdɪkʃənri/ (n.) nghĩa là "từ điển". Ví dụ: I look up the word in a dictionary. - Tôi tra từ trong từ điển.', 4),
  ('41000000-0000-0000-0007-000000000015', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We study in the ______."\n(Nghĩa: Chúng tôi học trong thư viện.)', 2, '"library" /ˈlaɪbrəri/ (n.) nghĩa là "thư viện". Ví dụ: We study in the library. - Chúng tôi học trong thư viện.', 5),
  ('41000000-0000-0000-0007-000000000016', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000016', 'Nghĩa của từ "subject" là gì?', 3, '"subject" /ˈsʌbdʒɪkt/ (n.) nghĩa là "môn học". Ví dụ: Math is my favorite subject. - Toán là môn học yêu thích của tôi.', 6),
  ('41000000-0000-0000-0007-000000000017', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000017', 'Từ nào có nghĩa là "điểm số, lớp"?', 0, '"grade" /ɡreɪd/ (n.) nghĩa là "điểm số, lớp". Ví dụ: She got a good grade in English. - Cô ấy được điểm cao môn tiếng Anh.', 7),
  ('41000000-0000-0000-0007-000000000018', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He studies at a famous ______."\n(Nghĩa: Anh ấy học ở một trường đại học nổi tiếng.)', 3, '"university" /ˌjuːnɪˈvɜːsəti/ (n.) nghĩa là "trường đại học". Ví dụ: He studies at a famous university. - Anh ấy học ở một trường đại học nổi tiếng.', 8),
  ('41000000-0000-0000-0007-000000000019', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000019', 'Nghĩa của từ "degree" là gì?', 2, '"degree" /dɪˈɡriː/ (n.) nghĩa là "bằng cấp". Ví dụ: She has a degree in biology. - Cô ấy có bằng về sinh học.', 9),
  ('41000000-0000-0000-0007-000000000020', '40000000-0000-0000-0007-000000000002', '30000000-0000-0000-0007-000000000020', 'Từ nào có nghĩa là "học bổng"?', 2, '"scholarship" /ˈskɒləʃɪp/ (n.) nghĩa là "học bổng". Ví dụ: He won a scholarship to study abroad. - Anh ấy giành được học bổng du học.', 10),
  ('41000000-0000-0000-0007-000000000021', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I ______ ten new words every day."\n(Nghĩa: Mỗi ngày tôi học mười từ mới.)', 3, '"learn" /lɜːn/ (v.) nghĩa là "học, học hỏi". Ví dụ: I learn ten new words every day. - Mỗi ngày tôi học mười từ mới.', 1),
  ('41000000-0000-0000-0007-000000000022', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000022', 'Nghĩa của từ "teach" là gì?', 1, '"teach" /tiːtʃ/ (v.) nghĩa là "dạy". Ví dụ: She teaches us English. - Cô ấy dạy chúng tôi tiếng Anh.', 2),
  ('41000000-0000-0000-0007-000000000023', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000023', 'Từ nào có nghĩa là "học, nghiên cứu"?', 3, '"study" /ˈstʌdi/ (v.) nghĩa là "học, nghiên cứu". Ví dụ: I study for two hours every evening. - Mỗi tối tôi học hai tiếng.', 3),
  ('41000000-0000-0000-0007-000000000024', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Please ______ the text aloud."\n(Nghĩa: Hãy đọc to đoạn văn này.)', 3, '"read" /riːd/ (v.) nghĩa là "đọc". Ví dụ: Please read the text aloud. - Hãy đọc to đoạn văn này.', 4),
  ('41000000-0000-0000-0007-000000000025', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000025', 'Nghĩa của từ "write" là gì?', 0, '"write" /raɪt/ (v.) nghĩa là "viết". Ví dụ: Write your name on the paper. - Hãy viết tên bạn lên tờ giấy.', 5),
  ('41000000-0000-0000-0007-000000000026', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000026', 'Từ nào có nghĩa là "lắng nghe"?', 3, '"listen" /ˈlɪsn/ (v.) nghĩa là "lắng nghe". Ví dụ: Listen carefully to the teacher. - Hãy lắng nghe giáo viên cẩn thận.', 6),
  ('41000000-0000-0000-0007-000000000027', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"You should ______ every day."\n(Nghĩa: Bạn nên luyện tập mỗi ngày.)', 2, '"practice" /ˈpræktɪs/ (v.) nghĩa là "luyện tập". Ví dụ: You should practice every day. - Bạn nên luyện tập mỗi ngày.', 7);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0007-000000000028', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000028', 'Nghĩa của từ "understand" là gì?', 3, '"understand" /ˌʌndəˈstænd/ (v.) nghĩa là "hiểu". Ví dụ: I do not understand this question. - Tôi không hiểu câu hỏi này.', 8),
  ('41000000-0000-0000-0007-000000000029', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000029', 'Từ nào có nghĩa là "nhớ"?', 3, '"remember" /rɪˈmembə/ (v.) nghĩa là "nhớ". Ví dụ: I cannot remember her name. - Tôi không nhớ tên cô ấy.', 9),
  ('41000000-0000-0000-0007-000000000030', '40000000-0000-0000-0007-000000000003', '30000000-0000-0000-0007-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He will ______ next year."\n(Nghĩa: Năm sau anh ấy sẽ tốt nghiệp.)', 2, '"graduate" /ˈɡrædʒuət/ (v.) nghĩa là "tốt nghiệp". Ví dụ: He will graduate next year. - Năm sau anh ấy sẽ tốt nghiệp.', 10),
  ('41000000-0000-0000-0008-000000000001', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000001', 'Nghĩa của từ "head" là gì?', 2, '"head" /hed/ (n.) nghĩa là "cái đầu". Ví dụ: My head hurts. - Tôi bị đau đầu.', 1),
  ('41000000-0000-0000-0008-000000000002', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000002', 'Từ nào có nghĩa là "con mắt"?', 1, '"eye" /aɪ/ (n.) nghĩa là "con mắt". Ví dụ: She has beautiful blue eyes. - Cô ấy có đôi mắt xanh rất đẹp.', 2),
  ('41000000-0000-0000-0008-000000000003', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He whispered in my ______."\n(Nghĩa: Anh ấy thì thầm vào tai tôi.)', 1, '"ear" /ɪə/ (n.) nghĩa là "cái tai". Ví dụ: He whispered in my ear. - Anh ấy thì thầm vào tai tôi.', 3),
  ('41000000-0000-0000-0008-000000000004', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000004', 'Nghĩa của từ "nose" là gì?', 1, '"nose" /nəʊz/ (n.) nghĩa là "cái mũi". Ví dụ: My nose is running. - Tôi bị sổ mũi.', 4),
  ('41000000-0000-0000-0008-000000000005', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000005', 'Từ nào có nghĩa là "cái miệng"?', 3, '"mouth" /maʊθ/ (n.) nghĩa là "cái miệng". Ví dụ: Open your mouth, please. - Làm ơn há miệng ra.', 5),
  ('41000000-0000-0000-0008-000000000006', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I have a pain in my ______."\n(Nghĩa: Tôi bị đau răng.)', 2, '"tooth" /tuːθ/ (n.) nghĩa là "cái răng". Ví dụ: I have a pain in my tooth. - Tôi bị đau răng.', 6),
  ('41000000-0000-0000-0008-000000000007', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000007', 'Nghĩa của từ "hand" là gì?', 2, '"hand" /hænd/ (n.) nghĩa là "bàn tay". Ví dụ: Raise your hand if you know the answer. - Hãy giơ tay nếu bạn biết câu trả lời.', 7),
  ('41000000-0000-0000-0008-000000000008', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000008', 'Từ nào có nghĩa là "cánh tay"?', 0, '"arm" /ɑːm/ (n.) nghĩa là "cánh tay". Ví dụ: He broke his arm. - Anh ấy bị gãy tay.', 8),
  ('41000000-0000-0000-0008-000000000009', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ hurts after running."\n(Nghĩa: Chân tôi đau sau khi chạy.)', 3, '"leg" /leɡ/ (n.) nghĩa là "cái chân". Ví dụ: My leg hurts after running. - Chân tôi đau sau khi chạy.', 9),
  ('41000000-0000-0000-0008-000000000010', '40000000-0000-0000-0008-000000000001', '30000000-0000-0000-0008-000000000010', 'Nghĩa của từ "back" là gì?', 2, '"back" /bæk/ (n.) nghĩa là "lưng". Ví dụ: She has a bad back. - Cô ấy bị đau lưng.', 10),
  ('41000000-0000-0000-0008-000000000011', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000011', 'Từ nào có nghĩa là "bụng, dạ dày"?', 3, '"stomach" /ˈstʌmək/ (n.) nghĩa là "bụng, dạ dày". Ví dụ: I have a stomach ache. - Tôi bị đau bụng.', 1),
  ('41000000-0000-0000-0008-000000000012', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Exercise is good for your ______."\n(Nghĩa: Tập thể dục tốt cho tim.)', 3, '"heart" /hɑːt/ (n.) nghĩa là "trái tim". Ví dụ: Exercise is good for your heart. - Tập thể dục tốt cho tim.', 2),
  ('41000000-0000-0000-0008-000000000013', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000013', 'Nghĩa của từ "doctor" là gì?', 1, '"doctor" /ˈdɒktə/ (n.) nghĩa là "bác sĩ". Ví dụ: You should see a doctor. - Bạn nên đi khám bác sĩ.', 3),
  ('41000000-0000-0000-0008-000000000014', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000014', 'Từ nào có nghĩa là "y tá"?', 1, '"nurse" /nɜːs/ (n.) nghĩa là "y tá". Ví dụ: The nurse took my temperature. - Y tá đã đo nhiệt độ cho tôi.', 4),
  ('41000000-0000-0000-0008-000000000015', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He is in the ______."\n(Nghĩa: Anh ấy đang ở bệnh viện.)', 0, '"hospital" /ˈhɒspɪtl/ (n.) nghĩa là "bệnh viện". Ví dụ: He is in the hospital. - Anh ấy đang ở bệnh viện.', 5),
  ('41000000-0000-0000-0008-000000000016', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000016', 'Nghĩa của từ "medicine" là gì?', 0, '"medicine" /ˈmedsn/ (n.) nghĩa là "thuốc". Ví dụ: Take this medicine twice a day. - Hãy uống thuốc này hai lần mỗi ngày.', 6),
  ('41000000-0000-0000-0008-000000000017', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000017', 'Từ nào có nghĩa là "hiệu thuốc"?', 1, '"pharmacy" /ˈfɑːməsi/ (n.) nghĩa là "hiệu thuốc". Ví dụ: The pharmacy is next to the bank. - Hiệu thuốc ở cạnh ngân hàng.', 7),
  ('41000000-0000-0000-0008-000000000018', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The child has a high ______."\n(Nghĩa: Đứa trẻ bị sốt cao.)', 0, '"fever" /ˈfiːvə/ (n.) nghĩa là "cơn sốt". Ví dụ: The child has a high fever. - Đứa trẻ bị sốt cao.', 8),
  ('41000000-0000-0000-0008-000000000019', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000019', 'Nghĩa của từ "cough" là gì?', 3, '"cough" /kɒf/ (n.) nghĩa là "cơn ho". Ví dụ: I have a bad cough. - Tôi bị ho nặng.', 9),
  ('41000000-0000-0000-0008-000000000020', '40000000-0000-0000-0008-000000000002', '30000000-0000-0000-0008-000000000020', 'Từ nào có nghĩa là "bệnh cảm lạnh"?', 0, '"cold" /kəʊld/ (n.) nghĩa là "bệnh cảm lạnh". Ví dụ: I caught a cold last week. - Tuần trước tôi bị cảm lạnh.', 10),
  ('41000000-0000-0000-0008-000000000021', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I have a terrible ______."\n(Nghĩa: Tôi bị đau đầu kinh khủng.)', 3, '"headache" /ˈhedeɪk/ (n.) nghĩa là "chứng đau đầu". Ví dụ: I have a terrible headache. - Tôi bị đau đầu kinh khủng.', 1),
  ('41000000-0000-0000-0008-000000000022', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000022', 'Nghĩa của từ "pain" là gì?', 3, '"pain" /peɪn/ (n.) nghĩa là "cơn đau". Ví dụ: I feel a sharp pain in my knee. - Tôi thấy đau nhói ở đầu gối.', 2),
  ('41000000-0000-0000-0008-000000000023', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000023', 'Từ nào có nghĩa là "khỏe mạnh"?', 1, '"healthy" /ˈhelθi/ (adj.) nghĩa là "khỏe mạnh". Ví dụ: Eating vegetables keeps you healthy. - Ăn rau giúp bạn khỏe mạnh.', 3),
  ('41000000-0000-0000-0008-000000000024', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She is ______ today."\n(Nghĩa: Hôm nay cô ấy bị ốm.)', 2, '"sick" /sɪk/ (adj.) nghĩa là "ốm, bệnh". Ví dụ: She is sick today. - Hôm nay cô ấy bị ốm.', 4),
  ('41000000-0000-0000-0008-000000000025', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000025', 'Nghĩa của từ "tired" là gì?', 2, '"tired" /ˈtaɪəd/ (adj.) nghĩa là "mệt mỏi". Ví dụ: I am tired after work. - Tôi mệt sau giờ làm.', 5),
  ('41000000-0000-0000-0008-000000000026', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000026', 'Từ nào có nghĩa là "bài tập thể dục"?', 2, '"exercise" /ˈeksəsaɪz/ (n.) nghĩa là "bài tập thể dục". Ví dụ: Regular exercise is important. - Tập thể dục đều đặn là rất quan trọng.', 6),
  ('41000000-0000-0000-0008-000000000027', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"A balanced ______ is good for you."\n(Nghĩa: Một chế độ ăn cân bằng tốt cho bạn.)', 3, '"diet" /ˈdaɪət/ (n.) nghĩa là "chế độ ăn". Ví dụ: A balanced diet is good for you. - Một chế độ ăn cân bằng tốt cho bạn.', 7),
  ('41000000-0000-0000-0008-000000000028', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000028', 'Nghĩa của từ "injury" là gì?', 2, '"injury" /ˈɪndʒəri/ (n.) nghĩa là "vết thương, chấn thương". Ví dụ: He had a serious injury. - Anh ấy bị chấn thương nặng.', 8),
  ('41000000-0000-0000-0008-000000000029', '40000000-0000-0000-0008-000000000003', '30000000-0000-0000-0008-000000000029', 'Từ nào có nghĩa là "hồi phục"?', 0, '"recover" /rɪˈkʌvə/ (v.) nghĩa là "hồi phục". Ví dụ: She will recover soon. - Cô ấy sẽ sớm hồi phục.', 9),
  ('41000000-0000-0000-0009-000000000001', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000001', 'Nghĩa của từ "shop" là gì?', 1, '"shop" /ʃɒp/ (n.) nghĩa là "cửa hàng". Ví dụ: The shop opens at nine. - Cửa hàng mở cửa lúc chín giờ.', 1),
  ('41000000-0000-0000-0009-000000000002', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000002', 'Từ nào có nghĩa là "siêu thị"?', 1, '"supermarket" /ˈsuːpəmɑːkɪt/ (n.) nghĩa là "siêu thị". Ví dụ: We buy food at the supermarket. - Chúng tôi mua đồ ăn ở siêu thị.', 2),
  ('41000000-0000-0000-0009-000000000003', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Let us go to the ______."\n(Nghĩa: Chúng ta hãy đi trung tâm thương mại.)', 2, '"mall" /mɔːl/ (n.) nghĩa là "trung tâm thương mại". Ví dụ: Let us go to the mall. - Chúng ta hãy đi trung tâm thương mại.', 3),
  ('41000000-0000-0000-0009-000000000004', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000004', 'Nghĩa của từ "buy" là gì?', 3, '"buy" /baɪ/ (v.) nghĩa là "mua". Ví dụ: I want to buy a new bag. - Tôi muốn mua một chiếc túi mới.', 4),
  ('41000000-0000-0000-0009-000000000005', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000005', 'Từ nào có nghĩa là "bán"?', 3, '"sell" /sel/ (v.) nghĩa là "bán". Ví dụ: They sell fresh fruit here. - Họ bán trái cây tươi ở đây.', 5),
  ('41000000-0000-0000-0009-000000000006', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"How would you like to ______?"\n(Nghĩa: Bạn muốn thanh toán như thế nào?)', 3, '"pay" /peɪ/ (v.) nghĩa là "trả tiền". Ví dụ: How would you like to pay? - Bạn muốn thanh toán như thế nào?', 6),
  ('41000000-0000-0000-0009-000000000007', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000007', 'Nghĩa của từ "spend" là gì?', 3, '"spend" /spend/ (v.) nghĩa là "tiêu (tiền)". Ví dụ: I spend too much money on books. - Tôi tiêu quá nhiều tiền vào sách.', 7),
  ('41000000-0000-0000-0009-000000000008', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000008', 'Từ nào có nghĩa là "tiết kiệm"?', 0, '"save" /seɪv/ (v.) nghĩa là "tiết kiệm". Ví dụ: I want to save money for a trip. - Tôi muốn tiết kiệm tiền cho một chuyến đi.', 8);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0009-000000000009', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"How much does it ______?"\n(Nghĩa: Cái này giá bao nhiêu?)', 0, '"cost" /kɒst/ (v.) nghĩa là "có giá". Ví dụ: How much does it cost? - Cái này giá bao nhiêu?', 9),
  ('41000000-0000-0000-0009-000000000010', '40000000-0000-0000-0009-000000000001', '30000000-0000-0000-0009-000000000010', 'Nghĩa của từ "cheap" là gì?', 0, '"cheap" /tʃiːp/ (adj.) nghĩa là "rẻ". Ví dụ: This shirt is cheap. - Chiếc áo sơ mi này rẻ.', 10),
  ('41000000-0000-0000-0009-000000000011', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000011', 'Từ nào có nghĩa là "đắt"?', 2, '"expensive" /ɪkˈspensɪv/ (adj.) nghĩa là "đắt". Ví dụ: That watch is too expensive. - Chiếc đồng hồ đó quá đắt.', 1),
  ('41000000-0000-0000-0009-000000000012', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"They give a ten percent ______."\n(Nghĩa: Họ giảm giá mười phần trăm.)', 1, '"discount" /ˈdɪskaʊnt/ (n.) nghĩa là "giảm giá". Ví dụ: They give a ten percent discount. - Họ giảm giá mười phần trăm.', 2),
  ('41000000-0000-0000-0009-000000000013', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000013', 'Nghĩa của từ "money" là gì?', 3, '"money" /ˈmʌni/ (n.) nghĩa là "tiền". Ví dụ: I do not have much money. - Tôi không có nhiều tiền.', 3),
  ('41000000-0000-0000-0009-000000000014', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000014', 'Từ nào có nghĩa là "tiền mặt"?', 1, '"cash" /kæʃ/ (n.) nghĩa là "tiền mặt". Ví dụ: Do you accept cash? - Bạn có nhận tiền mặt không?', 4),
  ('41000000-0000-0000-0009-000000000015', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Can I pay by ______?"\n(Nghĩa: Tôi trả bằng thẻ tín dụng được không?)', 3, '"credit card" /ˈkredɪt kɑːd/ (n.) nghĩa là "thẻ tín dụng". Ví dụ: Can I pay by credit card? - Tôi trả bằng thẻ tín dụng được không?', 5),
  ('41000000-0000-0000-0009-000000000016', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000016', 'Nghĩa của từ "change" là gì?', 2, '"change" /tʃeɪndʒ/ (n.) nghĩa là "tiền thừa". Ví dụ: Keep the change. - Bạn cứ giữ lại tiền thừa.', 6),
  ('41000000-0000-0000-0009-000000000017', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000017', 'Từ nào có nghĩa là "biên lai"?', 3, '"receipt" /rɪˈsiːt/ (n.) nghĩa là "biên lai". Ví dụ: Please keep the receipt. - Vui lòng giữ lại biên lai.', 7),
  ('41000000-0000-0000-0009-000000000018', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is looking for a jacket."\n(Nghĩa: Vị khách đang tìm một chiếc áo khoác.)', 0, '"customer" /ˈkʌstəmə/ (n.) nghĩa là "khách mua hàng". Ví dụ: The customer is looking for a jacket. - Vị khách đang tìm một chiếc áo khoác.', 8),
  ('41000000-0000-0000-0009-000000000019', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000019', 'Nghĩa của từ "cashier" là gì?', 2, '"cashier" /kæˈʃɪə/ (n.) nghĩa là "nhân viên thu ngân". Ví dụ: The cashier smiled at me. - Nhân viên thu ngân mỉm cười với tôi.', 9),
  ('41000000-0000-0000-0009-000000000020', '40000000-0000-0000-0009-000000000002', '30000000-0000-0000-0009-000000000020', 'Từ nào có nghĩa là "cái giỏ"?', 0, '"basket" /ˈbɑːskɪt/ (n.) nghĩa là "cái giỏ". Ví dụ: Put the apples in the basket. - Hãy bỏ những quả táo vào giỏ.', 10),
  ('41000000-0000-0000-0009-000000000021', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"This coat was a real ______."\n(Nghĩa: Chiếc áo khoác này đúng là một món hời.)', 3, '"bargain" /ˈbɑːɡɪn/ (n.) nghĩa là "món hời". Ví dụ: This coat was a real bargain. - Chiếc áo khoác này đúng là một món hời.', 1),
  ('41000000-0000-0000-0009-000000000022', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000022', 'Nghĩa của từ "size" là gì?', 0, '"size" /saɪz/ (n.) nghĩa là "cỡ, kích thước". Ví dụ: Do you have this in a larger size? - Bạn có cái này cỡ lớn hơn không?', 2),
  ('41000000-0000-0000-0009-000000000023', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000023', 'Từ nào có nghĩa là "thử (quần áo)"?', 2, '"try on" /traɪ ɒn/ (phr.) nghĩa là "thử (quần áo)". Ví dụ: Can I try on this dress? - Tôi thử chiếc váy này được không?', 3),
  ('41000000-0000-0000-0009-000000000024', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I would like a ______."\n(Nghĩa: Tôi muốn được hoàn tiền.)', 3, '"refund" /ˈriːfʌnd/ (n.) nghĩa là "sự hoàn tiền". Ví dụ: I would like a refund. - Tôi muốn được hoàn tiền.', 4),
  ('41000000-0000-0000-0009-000000000025', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000025', 'Nghĩa của từ "bank" là gì?', 2, '"bank" /bæŋk/ (n.) nghĩa là "ngân hàng". Ví dụ: I need to go to the bank. - Tôi cần đến ngân hàng.', 5),
  ('41000000-0000-0000-0009-000000000026', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000026', 'Từ nào có nghĩa là "đồng xu"?', 0, '"coin" /kɔɪn/ (n.) nghĩa là "đồng xu". Ví dụ: He found a coin on the street. - Anh ấy nhặt được một đồng xu trên đường.', 6),
  ('41000000-0000-0000-0009-000000000027', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I lost my ______."\n(Nghĩa: Tôi bị mất ví.)', 1, '"wallet" /ˈwɒlɪt/ (n.) nghĩa là "ví tiền". Ví dụ: I lost my wallet. - Tôi bị mất ví.', 7),
  ('41000000-0000-0000-0009-000000000028', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000028', 'Nghĩa của từ "price tag" là gì?', 1, '"price tag" /ˈpraɪs tæɡ/ (n.) nghĩa là "nhãn giá". Ví dụ: Check the price tag first. - Hãy kiểm tra nhãn giá trước.', 8),
  ('41000000-0000-0000-0009-000000000029', '40000000-0000-0000-0009-000000000003', '30000000-0000-0000-0009-000000000029', 'Từ nào có nghĩa là "có đủ tiền để mua"?', 0, '"afford" /əˈfɔːd/ (v.) nghĩa là "có đủ tiền để mua". Ví dụ: I cannot afford a new car. - Tôi không đủ tiền mua một chiếc xe mới.', 9),
  ('41000000-0000-0000-0010-000000000001', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000001', 'Nghĩa của từ "sport" là gì?', 1, '"sport" /spɔːt/ (n.) nghĩa là "môn thể thao". Ví dụ: Football is my favorite sport. - Bóng đá là môn thể thao yêu thích của tôi.', 1),
  ('41000000-0000-0000-0010-000000000002', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000002', 'Từ nào có nghĩa là "bóng đá"?', 3, '"football" /ˈfʊtbɔːl/ (n.) nghĩa là "bóng đá". Ví dụ: They play football every weekend. - Họ chơi bóng đá mỗi cuối tuần.', 2),
  ('41000000-0000-0000-0010-000000000003', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He is good at ______."\n(Nghĩa: Anh ấy chơi bóng rổ giỏi.)', 0, '"basketball" /ˈbɑːskɪtbɔːl/ (n.) nghĩa là "bóng rổ". Ví dụ: He is good at basketball. - Anh ấy chơi bóng rổ giỏi.', 3),
  ('41000000-0000-0000-0010-000000000004', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000004', 'Nghĩa của từ "tennis" là gì?', 2, '"tennis" /ˈtenɪs/ (n.) nghĩa là "quần vợt". Ví dụ: We play tennis on Sundays. - Chúng tôi chơi quần vợt vào Chủ nhật.', 4),
  ('41000000-0000-0000-0010-000000000005', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000005', 'Từ nào có nghĩa là "bơi lội"?', 3, '"swimming" /ˈswɪmɪŋ/ (n.) nghĩa là "bơi lội". Ví dụ: Swimming is good exercise. - Bơi lội là một bài tập tốt.', 5),
  ('41000000-0000-0000-0010-000000000006', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"______ keeps me fit."\n(Nghĩa: Chạy bộ giúp tôi cân đối.)', 3, '"running" /ˈrʌnɪŋ/ (n.) nghĩa là "chạy bộ". Ví dụ: Running keeps me fit. - Chạy bộ giúp tôi cân đối.', 6),
  ('41000000-0000-0000-0010-000000000007', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000007', 'Nghĩa của từ "cycling" là gì?', 1, '"cycling" /ˈsaɪklɪŋ/ (n.) nghĩa là "đạp xe". Ví dụ: Cycling is popular in this city. - Đạp xe rất phổ biến ở thành phố này.', 7),
  ('41000000-0000-0000-0010-000000000008', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000008', 'Từ nào có nghĩa là "cầu lông"?', 1, '"badminton" /ˈbædmɪntən/ (n.) nghĩa là "cầu lông". Ví dụ: My sister plays badminton well. - Em gái tôi chơi cầu lông giỏi.', 8),
  ('41000000-0000-0000-0010-000000000009', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Our ______ won the match."\n(Nghĩa: Đội của chúng tôi đã thắng trận đấu.)', 3, '"team" /tiːm/ (n.) nghĩa là "đội". Ví dụ: Our team won the match. - Đội của chúng tôi đã thắng trận đấu.', 9),
  ('41000000-0000-0000-0010-000000000010', '40000000-0000-0000-0010-000000000001', '30000000-0000-0000-0010-000000000010', 'Nghĩa của từ "player" là gì?', 1, '"player" /ˈpleɪə/ (n.) nghĩa là "cầu thủ, người chơi". Ví dụ: He is the best player in the team. - Anh ấy là cầu thủ giỏi nhất đội.', 10),
  ('41000000-0000-0000-0010-000000000011', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000011', 'Từ nào có nghĩa là "huấn luyện viên"?', 0, '"coach" /kəʊtʃ/ (n.) nghĩa là "huấn luyện viên". Ví dụ: The coach is very strict. - Huấn luyện viên rất nghiêm khắc.', 1),
  ('41000000-0000-0000-0010-000000000012', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ starts at seven."\n(Nghĩa: Trận đấu bắt đầu lúc bảy giờ.)', 1, '"match" /mætʃ/ (n.) nghĩa là "trận đấu". Ví dụ: The match starts at seven. - Trận đấu bắt đầu lúc bảy giờ.', 2),
  ('41000000-0000-0000-0010-000000000013', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000013', 'Nghĩa của từ "win" là gì?', 3, '"win" /wɪn/ (v.) nghĩa là "chiến thắng". Ví dụ: We hope to win the game. - Chúng tôi hy vọng thắng trận này.', 3),
  ('41000000-0000-0000-0010-000000000014', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000014', 'Từ nào có nghĩa là "thua, mất"?', 2, '"lose" /luːz/ (v.) nghĩa là "thua, mất". Ví dụ: They did not want to lose. - Họ không muốn thua.', 4),
  ('41000000-0000-0000-0010-000000000015', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000015', 'Nghĩa của từ "score" là gì?', 1, '"score" /skɔː/ (v.) nghĩa là "ghi bàn, ghi điểm". Ví dụ: He scored two goals. - Anh ấy ghi hai bàn thắng.', 5),
  ('41000000-0000-0000-0010-000000000016', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000016', 'Nghĩa của từ "race" là gì?', 1, '"race" /reɪs/ (n.) nghĩa là "cuộc đua". Ví dụ: She won the race. - Cô ấy đã thắng cuộc đua.', 6),
  ('41000000-0000-0000-0010-000000000017', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000017', 'Từ nào có nghĩa là "phòng tập thể hình"?', 1, '"gym" /dʒɪm/ (n.) nghĩa là "phòng tập thể hình". Ví dụ: I go to the gym three times a week. - Tôi đến phòng tập ba lần một tuần.', 7),
  ('41000000-0000-0000-0010-000000000018', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ is photography."\n(Nghĩa: Sở thích của tôi là chụp ảnh.)', 3, '"hobby" /ˈhɒbi/ (n.) nghĩa là "sở thích". Ví dụ: My hobby is photography. - Sở thích của tôi là chụp ảnh.', 8),
  ('41000000-0000-0000-0010-000000000019', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000019', 'Nghĩa của từ "music" là gì?', 3, '"music" /ˈmjuːzɪk/ (n.) nghĩa là "âm nhạc". Ví dụ: I listen to music every day. - Tôi nghe nhạc mỗi ngày.', 9);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0010-000000000020', '40000000-0000-0000-0010-000000000002', '30000000-0000-0000-0010-000000000020', 'Từ nào có nghĩa là "đàn ghi-ta"?', 1, '"guitar" /ɡɪˈtɑː/ (n.) nghĩa là "đàn ghi-ta". Ví dụ: He plays the guitar very well. - Anh ấy chơi ghi-ta rất giỏi.', 10),
  ('41000000-0000-0000-0010-000000000021', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She likes to ______ landscapes."\n(Nghĩa: Cô ấy thích vẽ phong cảnh.)', 2, '"paint" /peɪnt/ (v.) nghĩa là "vẽ tranh, sơn". Ví dụ: She likes to paint landscapes. - Cô ấy thích vẽ phong cảnh.', 1),
  ('41000000-0000-0000-0010-000000000022', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000022', 'Nghĩa của từ "draw" là gì?', 0, '"draw" /drɔː/ (v.) nghĩa là "vẽ (bằng bút)". Ví dụ: Can you draw a cat? - Bạn vẽ một con mèo được không?', 2),
  ('41000000-0000-0000-0010-000000000023', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000023', 'Từ nào có nghĩa là "nhảy múa"?', 2, '"dance" /dɑːns/ (v.) nghĩa là "nhảy múa". Ví dụ: They dance at the party. - Họ nhảy múa trong bữa tiệc.', 3),
  ('41000000-0000-0000-0010-000000000024', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She loves to ______."\n(Nghĩa: Cô ấy thích hát.)', 1, '"sing" /sɪŋ/ (v.) nghĩa là "hát". Ví dụ: She loves to sing. - Cô ấy thích hát.', 4),
  ('41000000-0000-0000-0010-000000000025', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000025', 'Nghĩa của từ "photography" là gì?', 0, '"photography" /fəˈtɒɡrəfi/ (n.) nghĩa là "nhiếp ảnh". Ví dụ: Photography is an expensive hobby. - Nhiếp ảnh là một thú vui tốn kém.', 5),
  ('41000000-0000-0000-0010-000000000026', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000026', 'Từ nào có nghĩa là "sưu tầm"?', 3, '"collect" /kəˈlekt/ (v.) nghĩa là "sưu tầm". Ví dụ: He likes to collect stamps. - Anh ấy thích sưu tầm tem.', 6),
  ('41000000-0000-0000-0010-000000000027', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We went ______ last summer."\n(Nghĩa: Hè năm ngoái chúng tôi đi cắm trại.)', 1, '"camping" /ˈkæmpɪŋ/ (n.) nghĩa là "cắm trại". Ví dụ: We went camping last summer. - Hè năm ngoái chúng tôi đi cắm trại.', 7),
  ('41000000-0000-0000-0010-000000000028', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000028', 'Nghĩa của từ "fishing" là gì?', 1, '"fishing" /ˈfɪʃɪŋ/ (n.) nghĩa là "câu cá". Ví dụ: My grandfather loves fishing. - Ông tôi rất thích câu cá.', 8),
  ('41000000-0000-0000-0010-000000000029', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000029', 'Từ nào có nghĩa là "cờ vua"?', 0, '"chess" /tʃes/ (n.) nghĩa là "cờ vua". Ví dụ: Do you want to play chess? - Bạn có muốn chơi cờ vua không?', 9),
  ('41000000-0000-0000-0010-000000000030', '40000000-0000-0000-0010-000000000003', '30000000-0000-0000-0010-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"______ your legs before you run."\n(Nghĩa: Hãy giãn chân trước khi chạy.)', 0, '"stretch" /stretʃ/ (v.) nghĩa là "duỗi, giãn cơ". Ví dụ: Stretch your legs before you run. - Hãy giãn chân trước khi chạy.', 10),
  ('41000000-0000-0000-0011-000000000001', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000001', 'Nghĩa của từ "weather" là gì?', 1, '"weather" /ˈweðə/ (n.) nghĩa là "thời tiết". Ví dụ: The weather is nice today. - Hôm nay thời tiết đẹp.', 1),
  ('41000000-0000-0000-0011-000000000002', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000002', 'Từ nào có nghĩa là "mặt trời"?', 3, '"sun" /sʌn/ (n.) nghĩa là "mặt trời". Ví dụ: The sun rises in the east. - Mặt trời mọc ở hướng đông.', 2),
  ('41000000-0000-0000-0011-000000000003', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We stayed home because of the ______."\n(Nghĩa: Chúng tôi ở nhà vì trời mưa.)', 1, '"rain" /reɪn/ (n.) nghĩa là "cơn mưa". Ví dụ: We stayed home because of the rain. - Chúng tôi ở nhà vì trời mưa.', 3),
  ('41000000-0000-0000-0011-000000000004', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000004', 'Nghĩa của từ "snow" là gì?', 1, '"snow" /snəʊ/ (n.) nghĩa là "tuyết". Ví dụ: Children love playing in the snow. - Trẻ em thích chơi trong tuyết.', 4),
  ('41000000-0000-0000-0011-000000000005', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000005', 'Từ nào có nghĩa là "gió"?', 0, '"wind" /wɪnd/ (n.) nghĩa là "gió". Ví dụ: The wind is strong today. - Hôm nay gió rất mạnh.', 5),
  ('41000000-0000-0000-0011-000000000006', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"There is not a ______ in the sky."\n(Nghĩa: Trên trời không có một đám mây nào.)', 0, '"cloud" /klaʊd/ (n.) nghĩa là "đám mây". Ví dụ: There is not a cloud in the sky. - Trên trời không có một đám mây nào.', 6),
  ('41000000-0000-0000-0011-000000000007', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000007', 'Nghĩa của từ "storm" là gì?', 0, '"storm" /stɔːm/ (n.) nghĩa là "cơn bão". Ví dụ: A storm is coming. - Một cơn bão đang đến.', 7),
  ('41000000-0000-0000-0011-000000000008', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000008', 'Từ nào có nghĩa là "sấm"?', 0, '"thunder" /ˈθʌndə/ (n.) nghĩa là "sấm". Ví dụ: I heard thunder last night. - Tối qua tôi nghe thấy tiếng sấm.', 8),
  ('41000000-0000-0000-0011-000000000009', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"______ lit up the sky."\n(Nghĩa: Tia chớp làm sáng cả bầu trời.)', 2, '"lightning" /ˈlaɪtnɪŋ/ (n.) nghĩa là "tia chớp". Ví dụ: Lightning lit up the sky. - Tia chớp làm sáng cả bầu trời.', 9),
  ('41000000-0000-0000-0011-000000000010', '40000000-0000-0000-0011-000000000001', '30000000-0000-0000-0011-000000000010', 'Nghĩa của từ "fog" là gì?', 0, '"fog" /fɒɡ/ (n.) nghĩa là "sương mù". Ví dụ: Thick fog covered the city. - Sương mù dày đặc bao phủ thành phố.', 10),
  ('41000000-0000-0000-0011-000000000011', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000011', 'Từ nào có nghĩa là "nóng"?', 0, '"hot" /hɒt/ (adj.) nghĩa là "nóng". Ví dụ: It is very hot in July. - Tháng Bảy trời rất nóng.', 1),
  ('41000000-0000-0000-0011-000000000012', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The water is too ______."\n(Nghĩa: Nước lạnh quá.)', 2, '"cold" /kəʊld/ (adj.) nghĩa là "lạnh". Ví dụ: The water is too cold. - Nước lạnh quá.', 2),
  ('41000000-0000-0000-0011-000000000013', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000013', 'Nghĩa của từ "warm" là gì?', 3, '"warm" /wɔːm/ (adj.) nghĩa là "ấm áp". Ví dụ: Wear a warm jacket. - Hãy mặc một chiếc áo khoác ấm.', 3),
  ('41000000-0000-0000-0011-000000000014', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000014', 'Từ nào có nghĩa là "mát mẻ"?', 3, '"cool" /kuːl/ (adj.) nghĩa là "mát mẻ". Ví dụ: It is cool in the evening. - Buổi tối trời mát mẻ.', 4),
  ('41000000-0000-0000-0011-000000000015', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"It is a ______ day."\n(Nghĩa: Hôm nay là một ngày nắng.)', 2, '"sunny" /ˈsʌni/ (adj.) nghĩa là "có nắng". Ví dụ: It is a sunny day. - Hôm nay là một ngày nắng.', 5),
  ('41000000-0000-0000-0011-000000000016', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000016', 'Nghĩa của từ "rainy" là gì?', 2, '"rainy" /ˈreɪni/ (adj.) nghĩa là "có mưa". Ví dụ: The rainy season starts in May. - Mùa mưa bắt đầu từ tháng Năm.', 6),
  ('41000000-0000-0000-0011-000000000017', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000017', 'Từ nào có nghĩa là "có gió"?', 1, '"windy" /ˈwɪndi/ (adj.) nghĩa là "có gió". Ví dụ: It is windy on the beach. - Trên bãi biển có gió.', 7),
  ('41000000-0000-0000-0011-000000000018', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The sky is ______ this morning."\n(Nghĩa: Sáng nay trời nhiều mây.)', 3, '"cloudy" /ˈklaʊdi/ (adj.) nghĩa là "nhiều mây". Ví dụ: The sky is cloudy this morning. - Sáng nay trời nhiều mây.', 8),
  ('41000000-0000-0000-0011-000000000019', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000019', 'Nghĩa của từ "spring" là gì?', 2, '"spring" /sprɪŋ/ (n.) nghĩa là "mùa xuân". Ví dụ: Flowers bloom in spring. - Hoa nở vào mùa xuân.', 9),
  ('41000000-0000-0000-0011-000000000020', '40000000-0000-0000-0011-000000000002', '30000000-0000-0000-0011-000000000020', 'Từ nào có nghĩa là "mùa hè"?', 0, '"summer" /ˈsʌmə/ (n.) nghĩa là "mùa hè". Ví dụ: We go to the beach in summer. - Chúng tôi đi biển vào mùa hè.', 10),
  ('41000000-0000-0000-0011-000000000021', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The leaves fall in ______."\n(Nghĩa: Lá rụng vào mùa thu.)', 1, '"autumn" /ˈɔːtəm/ (n.) nghĩa là "mùa thu". Ví dụ: The leaves fall in autumn. - Lá rụng vào mùa thu.', 1),
  ('41000000-0000-0000-0011-000000000022', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000022', 'Nghĩa của từ "winter" là gì?', 0, '"winter" /ˈwɪntə/ (n.) nghĩa là "mùa đông". Ví dụ: Winter is the coldest season. - Mùa đông là mùa lạnh nhất.', 2),
  ('41000000-0000-0000-0011-000000000023', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000023', 'Từ nào có nghĩa là "ngọn núi"?', 1, '"mountain" /ˈmaʊntən/ (n.) nghĩa là "ngọn núi". Ví dụ: We climbed the mountain. - Chúng tôi đã leo lên ngọn núi.', 3),
  ('41000000-0000-0000-0011-000000000024', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is very long."\n(Nghĩa: Con sông rất dài.)', 0, '"river" /ˈrɪvə/ (n.) nghĩa là "dòng sông". Ví dụ: The river is very long. - Con sông rất dài.', 4),
  ('41000000-0000-0000-0011-000000000025', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000025', 'Nghĩa của từ "forest" là gì?', 2, '"forest" /ˈfɒrɪst/ (n.) nghĩa là "khu rừng". Ví dụ: Many animals live in the forest. - Nhiều loài động vật sống trong rừng.', 5),
  ('41000000-0000-0000-0011-000000000026', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000026', 'Từ nào có nghĩa là "đại dương"?', 1, '"ocean" /ˈəʊʃn/ (n.) nghĩa là "đại dương". Ví dụ: The ocean is deep. - Đại dương rất sâu.', 6),
  ('41000000-0000-0000-0011-000000000027', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She gave me a red ______."\n(Nghĩa: Cô ấy tặng tôi một bông hoa đỏ.)', 3, '"flower" /ˈflaʊə/ (n.) nghĩa là "bông hoa". Ví dụ: She gave me a red flower. - Cô ấy tặng tôi một bông hoa đỏ.', 7),
  ('41000000-0000-0000-0011-000000000028', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000028', 'Nghĩa của từ "tree" là gì?', 2, '"tree" /triː/ (n.) nghĩa là "cái cây". Ví dụ: There is a big tree in our garden. - Có một cái cây lớn trong vườn nhà chúng tôi.', 8),
  ('41000000-0000-0000-0011-000000000029', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000029', 'Từ nào có nghĩa là "nhiệt độ"?', 1, '"temperature" /ˈtemprətʃə/ (n.) nghĩa là "nhiệt độ". Ví dụ: The temperature is thirty degrees. - Nhiệt độ là ba mươi độ.', 9);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0011-000000000030', '40000000-0000-0000-0011-000000000003', '30000000-0000-0000-0011-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ says it will rain."\n(Nghĩa: Dự báo nói trời sẽ mưa.)', 1, '"forecast" /ˈfɔːkɑːst/ (n.) nghĩa là "dự báo". Ví dụ: The forecast says it will rain. - Dự báo nói trời sẽ mưa.', 10),
  ('41000000-0000-0000-0012-000000000001', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000001', 'Nghĩa của từ "house" là gì?', 1, '"house" /haʊs/ (n.) nghĩa là "ngôi nhà". Ví dụ: They live in a big house. - Họ sống trong một ngôi nhà lớn.', 1),
  ('41000000-0000-0000-0012-000000000002', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000002', 'Từ nào có nghĩa là "căn hộ"?', 2, '"apartment" /əˈpɑːtmənt/ (n.) nghĩa là "căn hộ". Ví dụ: We rent a small apartment. - Chúng tôi thuê một căn hộ nhỏ.', 2),
  ('41000000-0000-0000-0012-000000000003', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My ______ is on the second floor."\n(Nghĩa: Phòng của tôi ở tầng hai.)', 0, '"room" /ruːm/ (n.) nghĩa là "căn phòng". Ví dụ: My room is on the second floor. - Phòng của tôi ở tầng hai.', 3),
  ('41000000-0000-0000-0012-000000000004', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000004', 'Nghĩa của từ "bedroom" là gì?', 3, '"bedroom" /ˈbedruːm/ (n.) nghĩa là "phòng ngủ". Ví dụ: The bedroom is quiet. - Phòng ngủ rất yên tĩnh.', 4),
  ('41000000-0000-0000-0012-000000000005', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000005', 'Từ nào có nghĩa là "phòng tắm"?', 2, '"bathroom" /ˈbɑːθruːm/ (n.) nghĩa là "phòng tắm". Ví dụ: The bathroom is next to the kitchen. - Phòng tắm ở cạnh nhà bếp.', 5),
  ('41000000-0000-0000-0012-000000000006', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Mom is cooking in the ______."\n(Nghĩa: Mẹ đang nấu ăn trong bếp.)', 2, '"kitchen" /ˈkɪtʃɪn/ (n.) nghĩa là "nhà bếp". Ví dụ: Mom is cooking in the kitchen. - Mẹ đang nấu ăn trong bếp.', 6),
  ('41000000-0000-0000-0012-000000000007', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000007', 'Nghĩa của từ "living room" là gì?', 1, '"living room" /ˈlɪvɪŋ ruːm/ (n.) nghĩa là "phòng khách". Ví dụ: We watch TV in the living room. - Chúng tôi xem TV trong phòng khách.', 7),
  ('41000000-0000-0000-0012-000000000008', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000008', 'Từ nào có nghĩa là "khu vườn"?', 2, '"garden" /ˈɡɑːdn/ (n.) nghĩa là "khu vườn". Ví dụ: They grow vegetables in the garden. - Họ trồng rau trong vườn.', 8),
  ('41000000-0000-0000-0012-000000000009', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Please close the ______."\n(Nghĩa: Làm ơn đóng cửa lại.)', 2, '"door" /dɔː/ (n.) nghĩa là "cửa ra vào". Ví dụ: Please close the door. - Làm ơn đóng cửa lại.', 9),
  ('41000000-0000-0000-0012-000000000010', '40000000-0000-0000-0012-000000000001', '30000000-0000-0000-0012-000000000010', 'Nghĩa của từ "window" là gì?', 2, '"window" /ˈwɪndəʊ/ (n.) nghĩa là "cửa sổ". Ví dụ: Open the window, please. - Làm ơn mở cửa sổ ra.', 10),
  ('41000000-0000-0000-0012-000000000011', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000011', 'Từ nào có nghĩa là "sàn nhà, tầng"?', 1, '"floor" /flɔː/ (n.) nghĩa là "sàn nhà, tầng". Ví dụ: The floor is wet. - Sàn nhà ướt.', 1),
  ('41000000-0000-0000-0012-000000000012', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"There is a picture on the ______."\n(Nghĩa: Có một bức tranh trên tường.)', 2, '"wall" /wɔːl/ (n.) nghĩa là "bức tường". Ví dụ: There is a picture on the wall. - Có một bức tranh trên tường.', 2),
  ('41000000-0000-0000-0012-000000000013', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000013', 'Nghĩa của từ "roof" là gì?', 3, '"roof" /ruːf/ (n.) nghĩa là "mái nhà". Ví dụ: The roof is red. - Mái nhà màu đỏ.', 3),
  ('41000000-0000-0000-0012-000000000014', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000014', 'Từ nào có nghĩa là "cầu thang"?', 1, '"stairs" /steəz/ (n.) nghĩa là "cầu thang". Ví dụ: Be careful on the stairs. - Hãy cẩn thận trên cầu thang.', 4),
  ('41000000-0000-0000-0012-000000000015', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Put the books on the ______."\n(Nghĩa: Hãy đặt sách lên bàn.)', 1, '"table" /ˈteɪbl/ (n.) nghĩa là "cái bàn". Ví dụ: Put the books on the table. - Hãy đặt sách lên bàn.', 5),
  ('41000000-0000-0000-0012-000000000016', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000016', 'Nghĩa của từ "chair" là gì?', 3, '"chair" /tʃeə/ (n.) nghĩa là "cái ghế". Ví dụ: Take a chair and sit down. - Hãy lấy một cái ghế và ngồi xuống.', 6),
  ('41000000-0000-0000-0012-000000000017', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000017', 'Từ nào có nghĩa là "ghế sofa"?', 0, '"sofa" /ˈsəʊfə/ (n.) nghĩa là "ghế sofa". Ví dụ: The cat is sleeping on the sofa. - Con mèo đang ngủ trên ghế sofa.', 7),
  ('41000000-0000-0000-0012-000000000018', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I go to ______ at ten."\n(Nghĩa: Tôi đi ngủ lúc mười giờ.)', 2, '"bed" /bed/ (n.) nghĩa là "cái giường". Ví dụ: I go to bed at ten. - Tôi đi ngủ lúc mười giờ.', 8),
  ('41000000-0000-0000-0012-000000000019', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000019', 'Nghĩa của từ "desk" là gì?', 1, '"desk" /desk/ (n.) nghĩa là "bàn làm việc". Ví dụ: His desk is always tidy. - Bàn làm việc của anh ấy luôn gọn gàng.', 9),
  ('41000000-0000-0000-0012-000000000020', '40000000-0000-0000-0012-000000000002', '30000000-0000-0000-0012-000000000020', 'Từ nào có nghĩa là "cái kệ"?', 0, '"shelf" /ʃelf/ (n.) nghĩa là "cái kệ". Ví dụ: The books are on the shelf. - Những quyển sách ở trên kệ.', 10),
  ('41000000-0000-0000-0012-000000000021', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Turn on the ______, please."\n(Nghĩa: Làm ơn bật đèn lên.)', 1, '"lamp" /læmp/ (n.) nghĩa là "cái đèn". Ví dụ: Turn on the lamp, please. - Làm ơn bật đèn lên.', 1),
  ('41000000-0000-0000-0012-000000000022', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000022', 'Nghĩa của từ "mirror" là gì?', 2, '"mirror" /ˈmɪrə/ (n.) nghĩa là "cái gương". Ví dụ: She looks at herself in the mirror. - Cô ấy soi mình trong gương.', 2),
  ('41000000-0000-0000-0012-000000000023', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000023', 'Từ nào có nghĩa là "rèm cửa"?', 1, '"curtain" /ˈkɜːtn/ (n.) nghĩa là "rèm cửa". Ví dụ: Close the curtain, it is too bright. - Hãy kéo rèm lại, trời quá sáng.', 3),
  ('41000000-0000-0000-0012-000000000024', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"There is some milk in the ______."\n(Nghĩa: Có một ít sữa trong tủ lạnh.)', 1, '"fridge" /frɪdʒ/ (n.) nghĩa là "tủ lạnh". Ví dụ: There is some milk in the fridge. - Có một ít sữa trong tủ lạnh.', 4),
  ('41000000-0000-0000-0012-000000000025', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000025', 'Nghĩa của từ "oven" là gì?', 0, '"oven" /ˈʌvn/ (n.) nghĩa là "cái lò nướng". Ví dụ: The cake is in the oven. - Chiếc bánh đang ở trong lò nướng.', 5),
  ('41000000-0000-0000-0012-000000000026', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000026', 'Từ nào có nghĩa là "máy giặt"?', 2, '"washing machine" /ˈwɒʃɪŋ məˌʃiːn/ (n.) nghĩa là "máy giặt". Ví dụ: The washing machine is broken. - Máy giặt bị hỏng.', 6),
  ('41000000-0000-0000-0012-000000000027', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Turn on the ______, it is hot."\n(Nghĩa: Hãy bật quạt lên, trời nóng.)', 0, '"fan" /fæn/ (n.) nghĩa là "cái quạt". Ví dụ: Turn on the fan, it is hot. - Hãy bật quạt lên, trời nóng.', 7),
  ('41000000-0000-0000-0012-000000000028', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000028', 'Nghĩa của từ "carpet" là gì?', 0, '"carpet" /ˈkɑːpɪt/ (n.) nghĩa là "tấm thảm". Ví dụ: The carpet is soft. - Tấm thảm rất mềm.', 8),
  ('41000000-0000-0000-0012-000000000029', '40000000-0000-0000-0012-000000000003', '30000000-0000-0000-0012-000000000029', 'Từ nào có nghĩa là "đồ nội thất"?', 2, '"furniture" /ˈfɜːnɪtʃə/ (n.) nghĩa là "đồ nội thất". Ví dụ: We bought new furniture. - Chúng tôi đã mua đồ nội thất mới.', 9),
  ('41000000-0000-0000-0013-000000000001', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000001', 'Nghĩa của từ "job" là gì?', 2, '"job" /dʒɒb/ (n.) nghĩa là "công việc". Ví dụ: She is looking for a new job. - Cô ấy đang tìm một công việc mới.', 1),
  ('41000000-0000-0000-0013-000000000002', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000002', 'Từ nào có nghĩa là "sự nghiệp"?', 3, '"career" /kəˈrɪə/ (n.) nghĩa là "sự nghiệp". Ví dụ: He has a successful career. - Anh ấy có một sự nghiệp thành công.', 2),
  ('41000000-0000-0000-0013-000000000003', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I work in an ______."\n(Nghĩa: Tôi làm việc trong một văn phòng.)', 3, '"office" /ˈɒfɪs/ (n.) nghĩa là "văn phòng". Ví dụ: I work in an office. - Tôi làm việc trong một văn phòng.', 3),
  ('41000000-0000-0000-0013-000000000004', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000004', 'Nghĩa của từ "factory" là gì?', 1, '"factory" /ˈfæktri/ (n.) nghĩa là "nhà máy". Ví dụ: My father works in a factory. - Bố tôi làm việc trong một nhà máy.', 4),
  ('41000000-0000-0000-0013-000000000005', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000005', 'Từ nào có nghĩa là "kỹ sư"?', 0, '"engineer" /ˌendʒɪˈnɪə/ (n.) nghĩa là "kỹ sư". Ví dụ: He is a software engineer. - Anh ấy là một kỹ sư phần mềm.', 5),
  ('41000000-0000-0000-0013-000000000006', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ designed this bridge."\n(Nghĩa: Kiến trúc sư đã thiết kế cây cầu này.)', 2, '"architect" /ˈɑːkɪtekt/ (n.) nghĩa là "kiến trúc sư". Ví dụ: The architect designed this bridge. - Kiến trúc sư đã thiết kế cây cầu này.', 6),
  ('41000000-0000-0000-0013-000000000007', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000007', 'Nghĩa của từ "lawyer" là gì?', 3, '"lawyer" /ˈlɔːjə/ (n.) nghĩa là "luật sư". Ví dụ: My uncle is a lawyer. - Chú tôi là một luật sư.', 7),
  ('41000000-0000-0000-0013-000000000008', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000008', 'Từ nào có nghĩa là "tài xế"?', 1, '"driver" /ˈdraɪvə/ (n.) nghĩa là "tài xế". Ví dụ: The driver was very polite. - Tài xế rất lịch sự.', 8),
  ('41000000-0000-0000-0013-000000000009', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ grows rice."\n(Nghĩa: Người nông dân trồng lúa.)', 0, '"farmer" /ˈfɑːmə/ (n.) nghĩa là "nông dân". Ví dụ: The farmer grows rice. - Người nông dân trồng lúa.', 9),
  ('41000000-0000-0000-0013-000000000010', '40000000-0000-0000-0013-000000000001', '30000000-0000-0000-0013-000000000010', 'Nghĩa của từ "chef" là gì?', 3, '"chef" /ʃef/ (n.) nghĩa là "đầu bếp". Ví dụ: The chef makes delicious soup. - Đầu bếp nấu món súp rất ngon.', 10);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0013-000000000011', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000011', 'Từ nào có nghĩa là "bồi bàn nam"?', 3, '"waiter" /ˈweɪtə/ (n.) nghĩa là "bồi bàn nam". Ví dụ: The waiter brought our drinks. - Người bồi bàn mang đồ uống đến cho chúng tôi.', 1),
  ('41000000-0000-0000-0013-000000000012', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ welcomed the passengers."\n(Nghĩa: Phi công chào đón các hành khách.)', 0, '"pilot" /ˈpaɪlət/ (n.) nghĩa là "phi công". Ví dụ: The pilot welcomed the passengers. - Phi công chào đón các hành khách.', 2),
  ('41000000-0000-0000-0013-000000000013', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000013', 'Nghĩa của từ "police officer" là gì?', 1, '"police officer" /pəˈliːs ˈɒfɪsə/ (n.) nghĩa là "cảnh sát". Ví dụ: The police officer helped us. - Viên cảnh sát đã giúp chúng tôi.', 3),
  ('41000000-0000-0000-0013-000000000014', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000014', 'Từ nào có nghĩa là "họa sĩ, nghệ sĩ"?', 2, '"artist" /ˈɑːtɪst/ (n.) nghĩa là "họa sĩ, nghệ sĩ". Ví dụ: The artist painted a portrait. - Họa sĩ đã vẽ một bức chân dung.', 4),
  ('41000000-0000-0000-0013-000000000015', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ checks the numbers."\n(Nghĩa: Kế toán kiểm tra các con số.)', 3, '"accountant" /əˈkaʊntənt/ (n.) nghĩa là "kế toán". Ví dụ: The accountant checks the numbers. - Kế toán kiểm tra các con số.', 5),
  ('41000000-0000-0000-0013-000000000016', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000016', 'Nghĩa của từ "colleague" là gì?', 1, '"colleague" /ˈkɒliːɡ/ (n.) nghĩa là "đồng nghiệp". Ví dụ: My colleague helped me finish the task. - Đồng nghiệp đã giúp tôi hoàn thành nhiệm vụ.', 6),
  ('41000000-0000-0000-0013-000000000017', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000017', 'Từ nào có nghĩa là "ông chủ, sếp"?', 3, '"boss" /bɒs/ (n.) nghĩa là "ông chủ, sếp". Ví dụ: My boss is very kind. - Sếp của tôi rất tốt bụng.', 7),
  ('41000000-0000-0000-0013-000000000018', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I have a job ______ tomorrow."\n(Nghĩa: Ngày mai tôi có một buổi phỏng vấn xin việc.)', 0, '"interview" /ˈɪntəvjuː/ (n.) nghĩa là "buổi phỏng vấn". Ví dụ: I have a job interview tomorrow. - Ngày mai tôi có một buổi phỏng vấn xin việc.', 8),
  ('41000000-0000-0000-0013-000000000019', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000019', 'Nghĩa của từ "apply" là gì?', 0, '"apply" /əˈplaɪ/ (v.) nghĩa là "nộp đơn, ứng tuyển". Ví dụ: I want to apply for this position. - Tôi muốn ứng tuyển vào vị trí này.', 9),
  ('41000000-0000-0000-0013-000000000020', '40000000-0000-0000-0013-000000000002', '30000000-0000-0000-0013-000000000020', 'Từ nào có nghĩa là "thuê, tuyển dụng"?', 0, '"hire" /ˈhaɪə/ (v.) nghĩa là "thuê, tuyển dụng". Ví dụ: They plan to hire two new employees. - Họ dự định tuyển hai nhân viên mới.', 10),
  ('41000000-0000-0000-0013-000000000021', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"She has five years of ______."\n(Nghĩa: Cô ấy có năm năm kinh nghiệm.)', 1, '"experience" /ɪkˈspɪəriəns/ (n.) nghĩa là "kinh nghiệm". Ví dụ: She has five years of experience. - Cô ấy có năm năm kinh nghiệm.', 1),
  ('41000000-0000-0000-0013-000000000022', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000022', 'Nghĩa của từ "skill" là gì?', 3, '"skill" /skɪl/ (n.) nghĩa là "kỹ năng". Ví dụ: Communication is an important skill. - Giao tiếp là một kỹ năng quan trọng.', 2),
  ('41000000-0000-0000-0013-000000000023', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000023', 'Từ nào có nghĩa là "sơ yếu lý lịch"?', 1, '"resume" /ˈrezjumeɪ/ (n.) nghĩa là "sơ yếu lý lịch". Ví dụ: Please send your resume by email. - Vui lòng gửi sơ yếu lý lịch qua email.', 3),
  ('41000000-0000-0000-0013-000000000024', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He works ______ every Friday."\n(Nghĩa: Anh ấy làm thêm giờ vào mỗi thứ Sáu.)', 3, '"overtime" /ˈəʊvətaɪm/ (n.) nghĩa là "giờ làm thêm". Ví dụ: He works overtime every Friday. - Anh ấy làm thêm giờ vào mỗi thứ Sáu.', 4),
  ('41000000-0000-0000-0013-000000000025', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000025', 'Nghĩa của từ "retire" là gì?', 2, '"retire" /rɪˈtaɪə/ (v.) nghĩa là "nghỉ hưu". Ví dụ: My grandfather retired last year. - Ông tôi đã nghỉ hưu năm ngoái.', 5),
  ('41000000-0000-0000-0013-000000000026', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000026', 'Từ nào có nghĩa là "toàn thời gian"?', 1, '"full-time" /ˌfʊl ˈtaɪm/ (adj.) nghĩa là "toàn thời gian". Ví dụ: She has a full-time job. - Cô ấy có một công việc toàn thời gian.', 6),
  ('41000000-0000-0000-0013-000000000027', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I have a ______ job at a cafe."\n(Nghĩa: Tôi có một công việc bán thời gian ở quán cà phê.)', 2, '"part-time" /ˌpɑːt ˈtaɪm/ (adj.) nghĩa là "bán thời gian". Ví dụ: I have a part-time job at a cafe. - Tôi có một công việc bán thời gian ở quán cà phê.', 7),
  ('41000000-0000-0000-0013-000000000028', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000028', 'Nghĩa của từ "unemployed" là gì?', 3, '"unemployed" /ˌʌnɪmˈplɔɪd/ (adj.) nghĩa là "thất nghiệp". Ví dụ: He has been unemployed for two months. - Anh ấy đã thất nghiệp được hai tháng.', 8),
  ('41000000-0000-0000-0013-000000000029', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000029', 'Từ nào có nghĩa là "có trách nhiệm"?', 2, '"responsible" /rɪˈspɒnsəbl/ (adj.) nghĩa là "có trách nhiệm". Ví dụ: She is responsible for the sales team. - Cô ấy chịu trách nhiệm về đội bán hàng.', 9),
  ('41000000-0000-0000-0013-000000000030', '40000000-0000-0000-0013-000000000003', '30000000-0000-0000-0013-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Good ______ leads to success."\n(Nghĩa: Làm việc nhóm tốt dẫn đến thành công.)', 3, '"teamwork" /ˈtiːmwɜːk/ (n.) nghĩa là "làm việc nhóm". Ví dụ: Good teamwork leads to success. - Làm việc nhóm tốt dẫn đến thành công.', 10),
  ('41000000-0000-0000-0014-000000000001', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000001', 'Nghĩa của từ "dog" là gì?', 0, '"dog" /dɒɡ/ (n.) nghĩa là "con chó". Ví dụ: My dog likes to play outside. - Con chó của tôi thích chơi ngoài trời.', 1),
  ('41000000-0000-0000-0014-000000000002', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000002', 'Từ nào có nghĩa là "con mèo"?', 1, '"cat" /kæt/ (n.) nghĩa là "con mèo". Ví dụ: The cat is sleeping on the sofa. - Con mèo đang ngủ trên ghế sofa.', 2),
  ('41000000-0000-0000-0014-000000000003', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"A ______ is singing in the tree."\n(Nghĩa: Một con chim đang hót trên cây.)', 1, '"bird" /bɜːd/ (n.) nghĩa là "con chim". Ví dụ: A bird is singing in the tree. - Một con chim đang hót trên cây.', 3),
  ('41000000-0000-0000-0014-000000000004', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000004', 'Nghĩa của từ "fish" là gì?', 2, '"fish" /fɪʃ/ (n.) nghĩa là "con cá". Ví dụ: The fish swims in the pond. - Con cá bơi trong ao.', 4),
  ('41000000-0000-0000-0014-000000000005', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000005', 'Từ nào có nghĩa là "con ngựa"?', 1, '"horse" /hɔːs/ (n.) nghĩa là "con ngựa". Ví dụ: She can ride a horse. - Cô ấy biết cưỡi ngựa.', 5),
  ('41000000-0000-0000-0014-000000000006', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ gives us milk."\n(Nghĩa: Con bò cho chúng ta sữa.)', 1, '"cow" /kaʊ/ (n.) nghĩa là "con bò". Ví dụ: The cow gives us milk. - Con bò cho chúng ta sữa.', 6),
  ('41000000-0000-0000-0014-000000000007', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000007', 'Nghĩa của từ "pig" là gì?', 3, '"pig" /pɪɡ/ (n.) nghĩa là "con heo". Ví dụ: The farmer feeds the pig. - Người nông dân cho con heo ăn.', 7),
  ('41000000-0000-0000-0014-000000000008', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000008', 'Từ nào có nghĩa là "con gà"?', 1, '"chicken" /ˈtʃɪkɪn/ (n.) nghĩa là "con gà". Ví dụ: The chicken lays eggs. - Con gà đẻ trứng.', 8),
  ('41000000-0000-0000-0014-000000000009', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is swimming."\n(Nghĩa: Con vịt đang bơi.)', 0, '"duck" /dʌk/ (n.) nghĩa là "con vịt". Ví dụ: The duck is swimming. - Con vịt đang bơi.', 9),
  ('41000000-0000-0000-0014-000000000010', '40000000-0000-0000-0014-000000000001', '30000000-0000-0000-0014-000000000010', 'Nghĩa của từ "sheep" là gì?', 3, '"sheep" /ʃiːp/ (n.) nghĩa là "con cừu". Ví dụ: A sheep has soft wool. - Con cừu có bộ lông mềm.', 10),
  ('41000000-0000-0000-0014-000000000011', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000011', 'Từ nào có nghĩa là "con thỏ"?', 0, '"rabbit" /ˈræbɪt/ (n.) nghĩa là "con thỏ". Ví dụ: The rabbit eats carrots. - Con thỏ ăn cà rốt.', 1),
  ('41000000-0000-0000-0014-000000000012', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The cat chased the ______."\n(Nghĩa: Con mèo đuổi theo con chuột.)', 2, '"mouse" /maʊs/ (n.) nghĩa là "con chuột". Ví dụ: The cat chased the mouse. - Con mèo đuổi theo con chuột.', 2),
  ('41000000-0000-0000-0014-000000000013', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000013', 'Nghĩa của từ "elephant" là gì?', 3, '"elephant" /ˈelɪfənt/ (n.) nghĩa là "con voi". Ví dụ: An elephant is a very big animal. - Con voi là một loài động vật rất lớn.', 3),
  ('41000000-0000-0000-0014-000000000014', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000014', 'Từ nào có nghĩa là "con sư tử"?', 1, '"lion" /ˈlaɪən/ (n.) nghĩa là "con sư tử". Ví dụ: The lion is the king of the jungle. - Sư tử là chúa tể của rừng xanh.', 4),
  ('41000000-0000-0000-0014-000000000015', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is a dangerous animal."\n(Nghĩa: Con hổ là một loài động vật nguy hiểm.)', 1, '"tiger" /ˈtaɪɡə/ (n.) nghĩa là "con hổ". Ví dụ: The tiger is a dangerous animal. - Con hổ là một loài động vật nguy hiểm.', 5),
  ('41000000-0000-0000-0014-000000000016', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000016', 'Nghĩa của từ "monkey" là gì?', 1, '"monkey" /ˈmʌŋki/ (n.) nghĩa là "con khỉ". Ví dụ: The monkey climbed the tree. - Con khỉ trèo lên cây.', 6),
  ('41000000-0000-0000-0014-000000000017', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000017', 'Từ nào có nghĩa là "con gấu"?', 0, '"bear" /beə/ (n.) nghĩa là "con gấu". Ví dụ: A bear sleeps all winter. - Con gấu ngủ suốt mùa đông.', 7),
  ('41000000-0000-0000-0014-000000000018', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Be careful, there is a ______."\n(Nghĩa: Hãy cẩn thận, có một con rắn.)', 3, '"snake" /sneɪk/ (n.) nghĩa là "con rắn". Ví dụ: Be careful, there is a snake. - Hãy cẩn thận, có một con rắn.', 8),
  ('41000000-0000-0000-0014-000000000019', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000019', 'Nghĩa của từ "frog" là gì?', 1, '"frog" /frɒɡ/ (n.) nghĩa là "con ếch". Ví dụ: The frog jumped into the pond. - Con ếch nhảy xuống ao.', 9),
  ('41000000-0000-0000-0014-000000000020', '40000000-0000-0000-0014-000000000002', '30000000-0000-0000-0014-000000000020', 'Từ nào có nghĩa là "con bướm"?', 0, '"butterfly" /ˈbʌtəflaɪ/ (n.) nghĩa là "con bướm". Ví dụ: A butterfly landed on the flower. - Một con bướm đậu trên bông hoa.', 10);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0014-000000000021', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ makes honey."\n(Nghĩa: Con ong làm ra mật.)', 1, '"bee" /biː/ (n.) nghĩa là "con ong". Ví dụ: The bee makes honey. - Con ong làm ra mật.', 1),
  ('41000000-0000-0000-0014-000000000022', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000022', 'Nghĩa của từ "spider" là gì?', 3, '"spider" /ˈspaɪdə/ (n.) nghĩa là "con nhện". Ví dụ: There is a spider on the wall. - Có một con nhện trên tường.', 2),
  ('41000000-0000-0000-0014-000000000023', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000023', 'Từ nào có nghĩa là "con rùa"?', 0, '"turtle" /ˈtɜːtl/ (n.) nghĩa là "con rùa". Ví dụ: The turtle moves slowly. - Con rùa di chuyển chậm chạp.', 3),
  ('41000000-0000-0000-0014-000000000024', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is very smart."\n(Nghĩa: Cá heo rất thông minh.)', 3, '"dolphin" /ˈdɒlfɪn/ (n.) nghĩa là "cá heo". Ví dụ: The dolphin is very smart. - Cá heo rất thông minh.', 4),
  ('41000000-0000-0000-0014-000000000025', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000025', 'Nghĩa của từ "shark" là gì?', 2, '"shark" /ʃɑːk/ (n.) nghĩa là "cá mập". Ví dụ: A shark has sharp teeth. - Cá mập có hàm răng sắc nhọn.', 5),
  ('41000000-0000-0000-0014-000000000026', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000026', 'Từ nào có nghĩa là "con sói"?', 3, '"wolf" /wʊlf/ (n.) nghĩa là "con sói". Ví dụ: The wolf howls at night. - Con sói hú vào ban đêm.', 6),
  ('41000000-0000-0000-0014-000000000027', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"A ______ ran across the road."\n(Nghĩa: Một con hươu chạy ngang qua đường.)', 2, '"deer" /dɪə/ (n.) nghĩa là "con hươu". Ví dụ: A deer ran across the road. - Một con hươu chạy ngang qua đường.', 7),
  ('41000000-0000-0000-0014-000000000028', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000028', 'Nghĩa của từ "giraffe" là gì?', 2, '"giraffe" /dʒɪˈrɑːf/ (n.) nghĩa là "con hươu cao cổ". Ví dụ: A giraffe has a very long neck. - Con hươu cao cổ có cái cổ rất dài.', 8),
  ('41000000-0000-0000-0014-000000000029', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000029', 'Từ nào có nghĩa là "thú cưng"?', 1, '"pet" /pet/ (n.) nghĩa là "thú cưng". Ví dụ: Do you have a pet? - Bạn có nuôi thú cưng không?', 9),
  ('41000000-0000-0000-0014-000000000030', '40000000-0000-0000-0014-000000000003', '30000000-0000-0000-0014-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"______ animals live in the forest."\n(Nghĩa: Động vật hoang dã sống trong rừng.)', 2, '"wild" /waɪld/ (adj.) nghĩa là "hoang dã". Ví dụ: Wild animals live in the forest. - Động vật hoang dã sống trong rừng.', 10),
  ('41000000-0000-0000-0015-000000000001', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000001', 'Nghĩa của từ "happy" là gì?', 2, '"happy" /ˈhæpi/ (adj.) nghĩa là "vui vẻ, hạnh phúc". Ví dụ: She looks happy today. - Hôm nay trông cô ấy rất vui.', 1),
  ('41000000-0000-0000-0015-000000000002', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000002', 'Từ nào có nghĩa là "buồn"?', 3, '"sad" /sæd/ (adj.) nghĩa là "buồn". Ví dụ: He felt sad after the movie. - Anh ấy thấy buồn sau bộ phim.', 2),
  ('41000000-0000-0000-0015-000000000003', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"My father was ______ with me."\n(Nghĩa: Bố tôi đã giận tôi.)', 3, '"angry" /ˈæŋɡri/ (adj.) nghĩa là "tức giận". Ví dụ: My father was angry with me. - Bố tôi đã giận tôi.', 3),
  ('41000000-0000-0000-0015-000000000004', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000004', 'Nghĩa của từ "nervous" là gì?', 3, '"nervous" /ˈnɜːvəs/ (adj.) nghĩa là "lo lắng, hồi hộp". Ví dụ: I feel nervous before an exam. - Tôi thấy hồi hộp trước kỳ thi.', 4),
  ('41000000-0000-0000-0015-000000000005', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000005', 'Từ nào có nghĩa là "hào hứng"?', 0, '"excited" /ɪkˈsaɪtɪd/ (adj.) nghĩa là "hào hứng". Ví dụ: The children are excited about the trip. - Bọn trẻ rất háo hức về chuyến đi.', 5),
  ('41000000-0000-0000-0015-000000000006', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I am ______ with this movie."\n(Nghĩa: Tôi chán bộ phim này.)', 2, '"bored" /bɔːd/ (adj.) nghĩa là "chán". Ví dụ: I am bored with this movie. - Tôi chán bộ phim này.', 6),
  ('41000000-0000-0000-0015-000000000007', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000007', 'Nghĩa của từ "surprised" là gì?', 2, '"surprised" /səˈpraɪzd/ (adj.) nghĩa là "ngạc nhiên". Ví dụ: She was surprised by the news. - Cô ấy ngạc nhiên trước tin này.', 7),
  ('41000000-0000-0000-0015-000000000008', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000008', 'Từ nào có nghĩa là "sợ hãi"?', 1, '"afraid" /əˈfreɪd/ (adj.) nghĩa là "sợ hãi". Ví dụ: He is afraid of dogs. - Anh ấy sợ chó.', 8),
  ('41000000-0000-0000-0015-000000000009', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I am ______ of you."\n(Nghĩa: Tôi tự hào về bạn.)', 2, '"proud" /praʊd/ (adj.) nghĩa là "tự hào". Ví dụ: I am proud of you. - Tôi tự hào về bạn.', 9),
  ('41000000-0000-0000-0015-000000000010', '40000000-0000-0000-0015-000000000001', '30000000-0000-0000-0015-000000000010', 'Nghĩa của từ "jealous" là gì?', 3, '"jealous" /ˈdʒeləs/ (adj.) nghĩa là "ghen tị". Ví dụ: She is jealous of her sister. - Cô ấy ghen tị với em gái.', 10),
  ('41000000-0000-0000-0015-000000000011', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000011', 'Từ nào có nghĩa là "cô đơn"?', 3, '"lonely" /ˈləʊnli/ (adj.) nghĩa là "cô đơn". Ví dụ: He felt lonely in the big city. - Anh ấy cảm thấy cô đơn ở thành phố lớn.', 1),
  ('41000000-0000-0000-0015-000000000012', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Her mother is ______ about her."\n(Nghĩa: Mẹ cô ấy lo lắng cho cô.)', 3, '"worried" /ˈwʌrid/ (adj.) nghĩa là "lo lắng". Ví dụ: Her mother is worried about her. - Mẹ cô ấy lo lắng cho cô.', 2),
  ('41000000-0000-0000-0015-000000000013', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000013', 'Nghĩa của từ "confident" là gì?', 1, '"confident" /ˈkɒnfɪdənt/ (adj.) nghĩa là "tự tin". Ví dụ: She is confident about the interview. - Cô ấy tự tin về buổi phỏng vấn.', 3),
  ('41000000-0000-0000-0015-000000000014', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000014', 'Từ nào có nghĩa là "nhút nhát, ngại ngùng"?', 2, '"shy" /ʃaɪ/ (adj.) nghĩa là "nhút nhát, ngại ngùng". Ví dụ: He is too shy to speak in public. - Anh ấy quá nhút nhát để nói trước đám đông.', 4),
  ('41000000-0000-0000-0015-000000000015', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Our new neighbor is very ______."\n(Nghĩa: Người hàng xóm mới của chúng tôi rất thân thiện.)', 0, '"friendly" /ˈfrendli/ (adj.) nghĩa là "thân thiện". Ví dụ: Our new neighbor is very friendly. - Người hàng xóm mới của chúng tôi rất thân thiện.', 5),
  ('41000000-0000-0000-0015-000000000016', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000016', 'Nghĩa của từ "kind" là gì?', 0, '"kind" /kaɪnd/ (adj.) nghĩa là "tốt bụng". Ví dụ: She is kind to everyone. - Cô ấy tốt bụng với mọi người.', 6),
  ('41000000-0000-0000-0015-000000000017', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000017', 'Từ nào có nghĩa là "lịch sự"?', 1, '"polite" /pəˈlaɪt/ (adj.) nghĩa là "lịch sự". Ví dụ: The students are polite. - Các học sinh rất lịch sự.', 7),
  ('41000000-0000-0000-0015-000000000018', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"An ______ person never lies."\n(Nghĩa: Một người trung thực không bao giờ nói dối.)', 2, '"honest" /ˈɒnɪst/ (adj.) nghĩa là "trung thực". Ví dụ: An honest person never lies. - Một người trung thực không bao giờ nói dối.', 8),
  ('41000000-0000-0000-0015-000000000019', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000019', 'Nghĩa của từ "generous" là gì?', 0, '"generous" /ˈdʒenərəs/ (adj.) nghĩa là "hào phóng". Ví dụ: He is generous with his time. - Anh ấy hào phóng với thời gian của mình.', 9),
  ('41000000-0000-0000-0015-000000000020', '40000000-0000-0000-0015-000000000002', '30000000-0000-0000-0015-000000000020', 'Từ nào có nghĩa là "kiên nhẫn"?', 2, '"patient" /ˈpeɪʃnt/ (adj.) nghĩa là "kiên nhẫn". Ví dụ: A good teacher must be patient. - Một giáo viên giỏi phải biết kiên nhẫn.', 10),
  ('41000000-0000-0000-0015-000000000021', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He is too ______ to cook."\n(Nghĩa: Anh ấy quá lười để nấu ăn.)', 1, '"lazy" /ˈleɪzi/ (adj.) nghĩa là "lười biếng". Ví dụ: He is too lazy to cook. - Anh ấy quá lười để nấu ăn.', 1),
  ('41000000-0000-0000-0015-000000000022', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000022', 'Nghĩa của từ "hardworking" là gì?', 1, '"hardworking" /ˌhɑːdˈwɜːkɪŋ/ (adj.) nghĩa là "chăm chỉ". Ví dụ: She is a hardworking student. - Cô ấy là một học sinh chăm chỉ.', 2),
  ('41000000-0000-0000-0015-000000000023', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000023', 'Từ nào có nghĩa là "sáng tạo"?', 0, '"creative" /kriˈeɪtɪv/ (adj.) nghĩa là "sáng tạo". Ví dụ: He has a creative mind. - Anh ấy có trí óc sáng tạo.', 3),
  ('41000000-0000-0000-0015-000000000024', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Children are naturally ______."\n(Nghĩa: Trẻ em vốn tò mò.)', 1, '"curious" /ˈkjʊəriəs/ (adj.) nghĩa là "tò mò". Ví dụ: Children are naturally curious. - Trẻ em vốn tò mò.', 4),
  ('41000000-0000-0000-0015-000000000025', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000025', 'Nghĩa của từ "brave" là gì?', 0, '"brave" /breɪv/ (adj.) nghĩa là "dũng cảm". Ví dụ: The firefighter was very brave. - Người lính cứu hỏa rất dũng cảm.', 5),
  ('41000000-0000-0000-0015-000000000026', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000026', 'Từ nào có nghĩa là "ích kỷ"?', 2, '"selfish" /ˈselfɪʃ/ (adj.) nghĩa là "ích kỷ". Ví dụ: Do not be so selfish. - Đừng ích kỷ như vậy.', 6),
  ('41000000-0000-0000-0015-000000000027', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I am ______ for your help."\n(Nghĩa: Tôi biết ơn sự giúp đỡ của bạn.)', 2, '"grateful" /ˈɡreɪtfl/ (adj.) nghĩa là "biết ơn". Ví dụ: I am grateful for your help. - Tôi biết ơn sự giúp đỡ của bạn.', 7),
  ('41000000-0000-0000-0015-000000000028', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000028', 'Nghĩa của từ "disappointed" là gì?', 3, '"disappointed" /ˌdɪsəˈpɔɪntɪd/ (adj.) nghĩa là "thất vọng". Ví dụ: She was disappointed with the result. - Cô ấy thất vọng với kết quả.', 8),
  ('41000000-0000-0000-0015-000000000029', '40000000-0000-0000-0015-000000000003', '30000000-0000-0000-0015-000000000029', 'Từ nào có nghĩa là "xấu hổ, ngượng"?', 0, '"embarrassed" /ɪmˈbærəst/ (adj.) nghĩa là "xấu hổ, ngượng". Ví dụ: He felt embarrassed about his mistake. - Anh ấy thấy ngượng về lỗi của mình.', 9),
  ('41000000-0000-0000-0016-000000000001', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000001', 'Nghĩa của từ "city" là gì?', 3, '"city" /ˈsɪti/ (n.) nghĩa là "thành phố". Ví dụ: Ho Chi Minh City is a big city. - Thành phố Hồ Chí Minh là một thành phố lớn.', 1);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0016-000000000002', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000002', 'Từ nào có nghĩa là "đường phố"?', 2, '"street" /striːt/ (n.) nghĩa là "đường phố". Ví dụ: The street is full of people. - Đường phố đầy người.', 2),
  ('41000000-0000-0000-0016-000000000003', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Be careful when you cross the ______."\n(Nghĩa: Hãy cẩn thận khi bạn băng qua đường.)', 0, '"road" /rəʊd/ (n.) nghĩa là "con đường". Ví dụ: Be careful when you cross the road. - Hãy cẩn thận khi bạn băng qua đường.', 3),
  ('41000000-0000-0000-0016-000000000004', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000004', 'Nghĩa của từ "bridge" là gì?', 3, '"bridge" /brɪdʒ/ (n.) nghĩa là "cây cầu". Ví dụ: We walked across the bridge. - Chúng tôi đi bộ qua cây cầu.', 4),
  ('41000000-0000-0000-0016-000000000005', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000005', 'Từ nào có nghĩa là "giao thông"?', 2, '"traffic" /ˈtræfɪk/ (n.) nghĩa là "giao thông". Ví dụ: The traffic is terrible this morning. - Sáng nay giao thông tệ khủng khiếp.', 5),
  ('41000000-0000-0000-0016-000000000006', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I go to school by ______."\n(Nghĩa: Tôi đi học bằng xe buýt.)', 0, '"bus" /bʌs/ (n.) nghĩa là "xe buýt". Ví dụ: I go to school by bus. - Tôi đi học bằng xe buýt.', 6),
  ('41000000-0000-0000-0016-000000000007', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000007', 'Nghĩa của từ "train" là gì?', 1, '"train" /treɪn/ (n.) nghĩa là "tàu hỏa". Ví dụ: The train leaves at noon. - Tàu hỏa khởi hành vào buổi trưa.', 7),
  ('41000000-0000-0000-0016-000000000008', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000008', 'Từ nào có nghĩa là "xe taxi"?', 2, '"taxi" /ˈtæksi/ (n.) nghĩa là "xe taxi". Ví dụ: Let us take a taxi. - Chúng ta hãy đi taxi.', 8),
  ('41000000-0000-0000-0016-000000000009', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He rides a ______ to work."\n(Nghĩa: Anh ấy đạp xe đạp đi làm.)', 2, '"bicycle" /ˈbaɪsɪkl/ (n.) nghĩa là "xe đạp". Ví dụ: He rides a bicycle to work. - Anh ấy đạp xe đạp đi làm.', 9),
  ('41000000-0000-0000-0016-000000000010', '40000000-0000-0000-0016-000000000001', '30000000-0000-0000-0016-000000000010', 'Nghĩa của từ "motorbike" là gì?', 2, '"motorbike" /ˈməʊtəbaɪk/ (n.) nghĩa là "xe máy". Ví dụ: Many people use a motorbike in Vietnam. - Nhiều người dùng xe máy ở Việt Nam.', 10),
  ('41000000-0000-0000-0016-000000000011', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000011', 'Từ nào có nghĩa là "tàu điện ngầm"?', 1, '"subway" /ˈsʌbweɪ/ (n.) nghĩa là "tàu điện ngầm". Ví dụ: The subway is fast and cheap. - Tàu điện ngầm vừa nhanh vừa rẻ.', 1),
  ('41000000-0000-0000-0016-000000000012', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is two blocks away."\n(Nghĩa: Nhà ga cách đây hai dãy nhà.)', 1, '"station" /ˈsteɪʃn/ (n.) nghĩa là "nhà ga, trạm". Ví dụ: The station is two blocks away. - Nhà ga cách đây hai dãy nhà.', 2),
  ('41000000-0000-0000-0016-000000000013', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000013', 'Nghĩa của từ "bus stop" là gì?', 2, '"bus stop" /ˈbʌs stɒp/ (n.) nghĩa là "trạm xe buýt". Ví dụ: I wait at the bus stop every morning. - Tôi đợi ở trạm xe buýt mỗi sáng.', 3),
  ('41000000-0000-0000-0016-000000000014', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000014', 'Từ nào có nghĩa là "góc đường"?', 1, '"corner" /ˈkɔːnə/ (n.) nghĩa là "góc đường". Ví dụ: Turn left at the corner. - Hãy rẽ trái ở góc đường.', 4),
  ('41000000-0000-0000-0016-000000000015', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Stop at the ______."\n(Nghĩa: Hãy dừng lại ở ngã tư.)', 0, '"crossroads" /ˈkrɒsrəʊdz/ (n.) nghĩa là "ngã tư". Ví dụ: Stop at the crossroads. - Hãy dừng lại ở ngã tư.', 5),
  ('41000000-0000-0000-0016-000000000016', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000016', 'Nghĩa của từ "traffic light" là gì?', 1, '"traffic light" /ˈtræfɪk laɪt/ (n.) nghĩa là "đèn giao thông". Ví dụ: Stop at the red traffic light. - Hãy dừng lại ở đèn giao thông màu đỏ.', 6),
  ('41000000-0000-0000-0016-000000000017', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000017', 'Từ nào có nghĩa là "vỉa hè"?', 2, '"pavement" /ˈpeɪvmənt/ (n.) nghĩa là "vỉa hè". Ví dụ: Do not ride on the pavement. - Đừng đi xe trên vỉa hè.', 7),
  ('41000000-0000-0000-0016-000000000018', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We walk in the ______ every evening."\n(Nghĩa: Chúng tôi đi dạo trong công viên mỗi tối.)', 0, '"park" /pɑːk/ (n.) nghĩa là "công viên". Ví dụ: We walk in the park every evening. - Chúng tôi đi dạo trong công viên mỗi tối.', 8),
  ('41000000-0000-0000-0016-000000000019', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000019', 'Nghĩa của từ "museum" là gì?', 1, '"museum" /mjuˈziːəm/ (n.) nghĩa là "bảo tàng". Ví dụ: The museum is open on Sundays. - Bảo tàng mở cửa vào Chủ nhật.', 9),
  ('41000000-0000-0000-0016-000000000020', '40000000-0000-0000-0016-000000000002', '30000000-0000-0000-0016-000000000020', 'Từ nào có nghĩa là "rạp chiếu phim"?', 0, '"cinema" /ˈsɪnəmə/ (n.) nghĩa là "rạp chiếu phim". Ví dụ: Let us go to the cinema tonight. - Tối nay chúng ta đi rạp chiếu phim nhé.', 10),
  ('41000000-0000-0000-0016-000000000021', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We had dinner at a nice ______."\n(Nghĩa: Chúng tôi ăn tối ở một nhà hàng đẹp.)', 3, '"restaurant" /ˈrestrɒnt/ (n.) nghĩa là "nhà hàng". Ví dụ: We had dinner at a nice restaurant. - Chúng tôi ăn tối ở một nhà hàng đẹp.', 1),
  ('41000000-0000-0000-0016-000000000022', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000022', 'Nghĩa của từ "market" là gì?', 0, '"market" /ˈmɑːkɪt/ (n.) nghĩa là "chợ". Ví dụ: She buys vegetables at the market. - Cô ấy mua rau ở chợ.', 2),
  ('41000000-0000-0000-0016-000000000023', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000023', 'Từ nào có nghĩa là "bưu điện"?', 3, '"post office" /ˈpəʊst ɒfɪs/ (n.) nghĩa là "bưu điện". Ví dụ: I need to go to the post office. - Tôi cần đến bưu điện.', 3),
  ('41000000-0000-0000-0016-000000000024', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is near the bank."\n(Nghĩa: Đồn cảnh sát ở gần ngân hàng.)', 2, '"police station" /pəˈliːs ˈsteɪʃn/ (n.) nghĩa là "đồn cảnh sát". Ví dụ: The police station is near the bank. - Đồn cảnh sát ở gần ngân hàng.', 4),
  ('41000000-0000-0000-0016-000000000025', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000025', 'Nghĩa của từ "turn left" là gì?', 1, '"turn left" /tɜːn left/ (phr.) nghĩa là "rẽ trái". Ví dụ: Turn left at the next street. - Hãy rẽ trái ở con đường tiếp theo.', 5),
  ('41000000-0000-0000-0016-000000000026', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000026', 'Từ nào có nghĩa là "đi thẳng"?', 1, '"go straight" /ɡəʊ streɪt/ (phr.) nghĩa là "đi thẳng". Ví dụ: Go straight for two hundred meters. - Hãy đi thẳng hai trăm mét.', 6),
  ('41000000-0000-0000-0016-000000000027', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The hotel is ______ the station."\n(Nghĩa: Khách sạn ở gần nhà ga.)', 3, '"near" /nɪə/ (prep.) nghĩa là "gần". Ví dụ: The hotel is near the station. - Khách sạn ở gần nhà ga.', 7),
  ('41000000-0000-0000-0016-000000000028', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000028', 'Nghĩa của từ "far" là gì?', 1, '"far" /fɑː/ (adv.) nghĩa là "xa". Ví dụ: Is it far from here? - Chỗ đó có xa đây không?', 8),
  ('41000000-0000-0000-0016-000000000029', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000029', 'Từ nào có nghĩa là "đối diện"?', 1, '"opposite" /ˈɒpəzɪt/ (prep.) nghĩa là "đối diện". Ví dụ: The bank is opposite the school. - Ngân hàng nằm đối diện trường học.', 9),
  ('41000000-0000-0000-0016-000000000030', '40000000-0000-0000-0016-000000000003', '30000000-0000-0000-0016-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"There is no ______ here."\n(Nghĩa: Ở đây không có chỗ đỗ xe.)', 1, '"parking" /ˈpɑːkɪŋ/ (n.) nghĩa là "bãi đỗ xe". Ví dụ: There is no parking here. - Ở đây không có chỗ đỗ xe.', 10),
  ('41000000-0000-0000-0017-000000000001', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000001', 'Nghĩa của từ "clothes" là gì?', 2, '"clothes" /kləʊðz/ (n.) nghĩa là "quần áo". Ví dụ: I need to buy some new clothes. - Tôi cần mua một ít quần áo mới.', 1),
  ('41000000-0000-0000-0017-000000000002', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000002', 'Từ nào có nghĩa là "áo sơ mi"?', 0, '"shirt" /ʃɜːt/ (n.) nghĩa là "áo sơ mi". Ví dụ: He is wearing a white shirt. - Anh ấy đang mặc áo sơ mi trắng.', 2),
  ('41000000-0000-0000-0017-000000000003', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"I like this blue ______."\n(Nghĩa: Tôi thích chiếc áo thun màu xanh này.)', 2, '"t-shirt" /ˈtiː ʃɜːt/ (n.) nghĩa là "áo thun". Ví dụ: I like this blue t-shirt. - Tôi thích chiếc áo thun màu xanh này.', 3),
  ('41000000-0000-0000-0017-000000000004', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000004', 'Nghĩa của từ "dress" là gì?', 1, '"dress" /dres/ (n.) nghĩa là "chiếc váy liền". Ví dụ: She wore a red dress to the party. - Cô ấy mặc một chiếc váy đỏ đến bữa tiệc.', 4),
  ('41000000-0000-0000-0017-000000000005', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000005', 'Từ nào có nghĩa là "chân váy"?', 1, '"skirt" /skɜːt/ (n.) nghĩa là "chân váy". Ví dụ: This skirt is too short. - Chiếc chân váy này quá ngắn.', 5),
  ('41000000-0000-0000-0017-000000000006', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"These ______ are too long."\n(Nghĩa: Chiếc quần dài này quá dài.)', 2, '"trousers" /ˈtraʊzəz/ (n.) nghĩa là "quần dài". Ví dụ: These trousers are too long. - Chiếc quần dài này quá dài.', 6),
  ('41000000-0000-0000-0017-000000000007', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000007', 'Nghĩa của từ "jeans" là gì?', 2, '"jeans" /dʒiːnz/ (n.) nghĩa là "quần bò". Ví dụ: I wear jeans every day. - Tôi mặc quần bò mỗi ngày.', 7),
  ('41000000-0000-0000-0017-000000000008', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000008', 'Từ nào có nghĩa là "quần short"?', 0, '"shorts" /ʃɔːts/ (n.) nghĩa là "quần short". Ví dụ: He wears shorts in summer. - Anh ấy mặc quần short vào mùa hè.', 8),
  ('41000000-0000-0000-0017-000000000009', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Take your ______, it is cold."\n(Nghĩa: Hãy mang theo áo khoác, trời lạnh đấy.)', 2, '"jacket" /ˈdʒækɪt/ (n.) nghĩa là "áo khoác". Ví dụ: Take your jacket, it is cold. - Hãy mang theo áo khoác, trời lạnh đấy.', 9),
  ('41000000-0000-0000-0017-000000000010', '40000000-0000-0000-0017-000000000001', '30000000-0000-0000-0017-000000000010', 'Nghĩa của từ "coat" là gì?', 0, '"coat" /kəʊt/ (n.) nghĩa là "áo choàng dày". Ví dụ: She put on her winter coat. - Cô ấy mặc chiếc áo choàng mùa đông.', 10),
  ('41000000-0000-0000-0017-000000000011', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000011', 'Từ nào có nghĩa là "áo len"?', 0, '"sweater" /ˈswetə/ (n.) nghĩa là "áo len". Ví dụ: This sweater keeps me warm. - Chiếc áo len này giữ ấm cho tôi.', 1);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0017-000000000012', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He wore a black ______."\n(Nghĩa: Anh ấy mặc bộ com-lê màu đen.)', 3, '"suit" /suːt/ (n.) nghĩa là "bộ com-lê". Ví dụ: He wore a black suit. - Anh ấy mặc bộ com-lê màu đen.', 2),
  ('41000000-0000-0000-0017-000000000013', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000013', 'Nghĩa của từ "uniform" là gì?', 3, '"uniform" /ˈjuːnɪfɔːm/ (n.) nghĩa là "đồng phục". Ví dụ: Students wear a uniform at school. - Học sinh mặc đồng phục ở trường.', 3),
  ('41000000-0000-0000-0017-000000000014', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000014', 'Từ nào có nghĩa là "đôi tất"?', 2, '"socks" /sɒks/ (n.) nghĩa là "đôi tất". Ví dụ: I need a new pair of socks. - Tôi cần một đôi tất mới.', 4),
  ('41000000-0000-0000-0017-000000000015', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"These ______ are comfortable."\n(Nghĩa: Đôi giày này rất thoải mái.)', 0, '"shoes" /ʃuːz/ (n.) nghĩa là "đôi giày". Ví dụ: These shoes are comfortable. - Đôi giày này rất thoải mái.', 5),
  ('41000000-0000-0000-0017-000000000016', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000016', 'Nghĩa của từ "boots" là gì?', 2, '"boots" /buːts/ (n.) nghĩa là "đôi ủng". Ví dụ: She wears boots when it rains. - Cô ấy đi ủng khi trời mưa.', 6),
  ('41000000-0000-0000-0017-000000000017', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000017', 'Từ nào có nghĩa là "dép quai hậu"?', 1, '"sandals" /ˈsændlz/ (n.) nghĩa là "dép quai hậu". Ví dụ: I wear sandals in summer. - Tôi đi dép quai hậu vào mùa hè.', 7),
  ('41000000-0000-0000-0017-000000000018', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He wears a ______ in the sun."\n(Nghĩa: Anh ấy đội mũ khi trời nắng.)', 1, '"hat" /hæt/ (n.) nghĩa là "cái mũ". Ví dụ: He wears a hat in the sun. - Anh ấy đội mũ khi trời nắng.', 8),
  ('41000000-0000-0000-0017-000000000019', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000019', 'Nghĩa của từ "scarf" là gì?', 0, '"scarf" /skɑːf/ (n.) nghĩa là "khăn quàng cổ". Ví dụ: She wore a warm scarf. - Cô ấy quàng một chiếc khăn ấm.', 9),
  ('41000000-0000-0000-0017-000000000020', '40000000-0000-0000-0017-000000000002', '30000000-0000-0000-0017-000000000020', 'Từ nào có nghĩa là "găng tay"?', 0, '"gloves" /ɡlʌvz/ (n.) nghĩa là "găng tay". Ví dụ: Wear gloves in winter. - Hãy đeo găng tay vào mùa đông.', 10),
  ('41000000-0000-0000-0017-000000000021', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He needs a new ______."\n(Nghĩa: Anh ấy cần một chiếc dây lưng mới.)', 3, '"belt" /belt/ (n.) nghĩa là "dây lưng". Ví dụ: He needs a new belt. - Anh ấy cần một chiếc dây lưng mới.', 1),
  ('41000000-0000-0000-0017-000000000022', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000022', 'Nghĩa của từ "tie" là gì?', 0, '"tie" /taɪ/ (n.) nghĩa là "cà vạt". Ví dụ: My father wears a tie to work. - Bố tôi đeo cà vạt đi làm.', 2),
  ('41000000-0000-0000-0017-000000000023', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000023', 'Từ nào có nghĩa là "cái túi"?', 2, '"bag" /bæɡ/ (n.) nghĩa là "cái túi". Ví dụ: She carries a small bag. - Cô ấy mang một chiếc túi nhỏ.', 3),
  ('41000000-0000-0000-0017-000000000024', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"He wears ______ to read."\n(Nghĩa: Anh ấy đeo kính để đọc.)', 1, '"glasses" /ˈɡlɑːsɪz/ (n.) nghĩa là "kính mắt". Ví dụ: He wears glasses to read. - Anh ấy đeo kính để đọc.', 4),
  ('41000000-0000-0000-0017-000000000025', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000025', 'Nghĩa của từ "watch" là gì?', 2, '"watch" /wɒtʃ/ (n.) nghĩa là "đồng hồ đeo tay". Ví dụ: My watch is five minutes fast. - Đồng hồ của tôi nhanh năm phút.', 5),
  ('41000000-0000-0000-0017-000000000026', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000026', 'Từ nào có nghĩa là "dây chuyền"?', 3, '"necklace" /ˈnekləs/ (n.) nghĩa là "dây chuyền". Ví dụ: She wore a beautiful necklace. - Cô ấy đeo một sợi dây chuyền rất đẹp.', 6),
  ('41000000-0000-0000-0017-000000000027', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"What do you ______ to work?"\n(Nghĩa: Bạn mặc gì khi đi làm?)', 2, '"wear" /weə/ (v.) nghĩa là "mặc, đeo". Ví dụ: What do you wear to work? - Bạn mặc gì khi đi làm?', 7),
  ('41000000-0000-0000-0017-000000000028', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000028', 'Nghĩa của từ "fit" là gì?', 2, '"fit" /fɪt/ (v.) nghĩa là "vừa vặn". Ví dụ: This shirt does not fit me. - Chiếc áo này không vừa với tôi.', 8),
  ('41000000-0000-0000-0017-000000000029', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000029', 'Từ nào có nghĩa là "thời trang"?', 0, '"fashion" /ˈfæʃn/ (n.) nghĩa là "thời trang". Ví dụ: She is interested in fashion. - Cô ấy quan tâm đến thời trang.', 9),
  ('41000000-0000-0000-0017-000000000030', '40000000-0000-0000-0017-000000000003', '30000000-0000-0000-0017-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"These shoes are very ______."\n(Nghĩa: Đôi giày này rất thoải mái.)', 3, '"comfortable" /ˈkʌmftəbl/ (adj.) nghĩa là "thoải mái". Ví dụ: These shoes are very comfortable. - Đôi giày này rất thoải mái.', 10),
  ('41000000-0000-0000-0018-000000000001', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000001', 'Nghĩa của từ "environment" là gì?', 2, '"environment" /ɪnˈvaɪrənmənt/ (n.) nghĩa là "môi trường". Ví dụ: We must protect the environment. - Chúng ta phải bảo vệ môi trường.', 1),
  ('41000000-0000-0000-0018-000000000002', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000002', 'Từ nào có nghĩa là "sự ô nhiễm"?', 1, '"pollution" /pəˈluːʃn/ (n.) nghĩa là "sự ô nhiễm". Ví dụ: Air pollution is a serious problem. - Ô nhiễm không khí là một vấn đề nghiêm trọng.', 2),
  ('41000000-0000-0000-0018-000000000003', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000003', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ is getting warmer."\n(Nghĩa: Khí hậu đang ấm lên.)', 2, '"climate" /ˈklaɪmət/ (n.) nghĩa là "khí hậu". Ví dụ: The climate is getting warmer. - Khí hậu đang ấm lên.', 3),
  ('41000000-0000-0000-0018-000000000004', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000004', 'Nghĩa của từ "global warming" là gì?', 0, '"global warming" /ˌɡləʊbl ˈwɔːmɪŋ/ (n.) nghĩa là "sự nóng lên toàn cầu". Ví dụ: Global warming melts the ice. - Sự nóng lên toàn cầu làm tan băng.', 4),
  ('41000000-0000-0000-0018-000000000005', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000005', 'Từ nào có nghĩa là "khí nhà kính"?', 1, '"greenhouse gas" /ˈɡriːnhaʊs ɡæs/ (n.) nghĩa là "khí nhà kính". Ví dụ: Cars produce greenhouse gas. - Ô tô thải ra khí nhà kính.', 5),
  ('41000000-0000-0000-0018-000000000006', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000006', 'Chọn từ thích hợp để điền vào chỗ trống:\n"We should ______ paper and plastic."\n(Nghĩa: Chúng ta nên tái chế giấy và nhựa.)', 0, '"recycle" /ˌriːˈsaɪkl/ (v.) nghĩa là "tái chế". Ví dụ: We should recycle paper and plastic. - Chúng ta nên tái chế giấy và nhựa.', 6),
  ('41000000-0000-0000-0018-000000000007', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000007', 'Nghĩa của từ "waste" là gì?', 3, '"waste" /weɪst/ (n.) nghĩa là "rác thải, sự lãng phí". Ví dụ: Reduce food waste at home. - Hãy giảm lượng thức ăn lãng phí ở nhà.', 7),
  ('41000000-0000-0000-0018-000000000008', '40000000-0000-0000-0018-000000000001', '30000000-0000-0000-0018-000000000008', 'Từ nào có nghĩa là "nhựa"?', 1, '"plastic" /ˈplæstɪk/ (n.) nghĩa là "nhựa". Ví dụ: Plastic takes hundreds of years to break down. - Nhựa mất hàng trăm năm để phân hủy.', 8),
  ('41000000-0000-0000-0018-000000000009', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000009', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Please put the ______ in the bin."\n(Nghĩa: Hãy bỏ rác vào thùng.)', 1, '"rubbish" /ˈrʌbɪʃ/ (n.) nghĩa là "rác". Ví dụ: Please put the rubbish in the bin. - Hãy bỏ rác vào thùng.', 1),
  ('41000000-0000-0000-0018-000000000010', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000010', 'Nghĩa của từ "energy" là gì?', 0, '"energy" /ˈenədʒi/ (n.) nghĩa là "năng lượng". Ví dụ: Solar energy is clean. - Năng lượng mặt trời là năng lượng sạch.', 2),
  ('41000000-0000-0000-0018-000000000011', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000011', 'Từ nào có nghĩa là "thuộc mặt trời"?', 3, '"solar" /ˈsəʊlə/ (adj.) nghĩa là "thuộc mặt trời". Ví dụ: Solar panels produce electricity. - Các tấm pin mặt trời tạo ra điện.', 3),
  ('41000000-0000-0000-0018-000000000012', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000012', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The price of ______ keeps rising."\n(Nghĩa: Giá nhiên liệu cứ tăng liên tục.)', 1, '"fuel" /ˈfjuːəl/ (n.) nghĩa là "nhiên liệu". Ví dụ: The price of fuel keeps rising. - Giá nhiên liệu cứ tăng liên tục.', 4),
  ('41000000-0000-0000-0018-000000000013', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000013', 'Nghĩa của từ "electricity" là gì?', 1, '"electricity" /ɪˌlekˈtrɪsəti/ (n.) nghĩa là "điện". Ví dụ: We should save electricity. - Chúng ta nên tiết kiệm điện.', 5),
  ('41000000-0000-0000-0018-000000000014', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000014', 'Từ nào có nghĩa là "bảo vệ"?', 1, '"protect" /prəˈtekt/ (v.) nghĩa là "bảo vệ". Ví dụ: We need to protect endangered animals. - Chúng ta cần bảo vệ các loài động vật có nguy cơ tuyệt chủng.', 6),
  ('41000000-0000-0000-0018-000000000015', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000015', 'Chọn từ thích hợp để điền vào chỗ trống:\n"People try to ______ water."\n(Nghĩa: Mọi người cố gắng tiết kiệm nước.)', 3, '"conserve" /kənˈsɜːv/ (v.) nghĩa là "bảo tồn". Ví dụ: People try to conserve water. - Mọi người cố gắng tiết kiệm nước.', 7),
  ('41000000-0000-0000-0018-000000000016', '40000000-0000-0000-0018-000000000002', '30000000-0000-0000-0018-000000000016', 'Nghĩa của từ "damage" là gì?', 2, '"damage" /ˈdæmɪdʒ/ (v.) nghĩa là "gây hại". Ví dụ: Chemicals can damage the soil. - Hóa chất có thể gây hại cho đất.', 8),
  ('41000000-0000-0000-0018-000000000017', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000017', 'Từ nào có nghĩa là "có nguy cơ tuyệt chủng"?', 0, '"endangered" /ɪnˈdeɪndʒəd/ (adj.) nghĩa là "có nguy cơ tuyệt chủng". Ví dụ: The tiger is an endangered species. - Hổ là một loài có nguy cơ tuyệt chủng.', 1),
  ('41000000-0000-0000-0018-000000000018', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000018', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Dinosaurs became ______ millions of years ago."\n(Nghĩa: Khủng long đã tuyệt chủng cách đây hàng triệu năm.)', 0, '"extinct" /ɪkˈstɪŋkt/ (adj.) nghĩa là "tuyệt chủng". Ví dụ: Dinosaurs became extinct millions of years ago. - Khủng long đã tuyệt chủng cách đây hàng triệu năm.', 2),
  ('41000000-0000-0000-0018-000000000019', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000019', 'Nghĩa của từ "species" là gì?', 1, '"species" /ˈspiːʃiːz/ (n.) nghĩa là "loài (sinh vật)". Ví dụ: Many species live in the rainforest. - Nhiều loài sinh vật sống trong rừng mưa nhiệt đới.', 3),
  ('41000000-0000-0000-0018-000000000020', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000020', 'Từ nào có nghĩa là "môi trường sống"?', 3, '"habitat" /ˈhæbɪtæt/ (n.) nghĩa là "môi trường sống". Ví dụ: Forests are the habitat of many animals. - Rừng là môi trường sống của nhiều loài vật.', 4),
  ('41000000-0000-0000-0018-000000000021', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000021', 'Chọn từ thích hợp để điền vào chỗ trống:\n"______ destroys wildlife."\n(Nghĩa: Nạn phá rừng hủy hoại động vật hoang dã.)', 1, '"deforestation" /diːˌfɒrɪˈsteɪʃn/ (n.) nghĩa là "nạn phá rừng". Ví dụ: Deforestation destroys wildlife. - Nạn phá rừng hủy hoại động vật hoang dã.', 5);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0000-0018-000000000022', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000022', 'Nghĩa của từ "flood" là gì?', 0, '"flood" /flʌd/ (n.) nghĩa là "trận lũ". Ví dụ: The flood destroyed many houses. - Trận lũ đã phá hủy nhiều ngôi nhà.', 6),
  ('41000000-0000-0000-0018-000000000023', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000023', 'Từ nào có nghĩa là "hạn hán"?', 3, '"drought" /draʊt/ (n.) nghĩa là "hạn hán". Ví dụ: The drought lasted three months. - Đợt hạn hán kéo dài ba tháng.', 7),
  ('41000000-0000-0000-0018-000000000024', '40000000-0000-0000-0018-000000000003', '30000000-0000-0000-0018-000000000024', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ______ shook the city."\n(Nghĩa: Trận động đất làm rung chuyển thành phố.)', 2, '"earthquake" /ˈɜːθkweɪk/ (n.) nghĩa là "trận động đất". Ví dụ: The earthquake shook the city. - Trận động đất làm rung chuyển thành phố.', 8),
  ('41000000-0000-0000-0018-000000000025', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000025', 'Nghĩa của từ "natural resource" là gì?', 3, '"natural resource" /ˈnætʃrəl rɪˈsɔːs/ (n.) nghĩa là "tài nguyên thiên nhiên". Ví dụ: Oil is a natural resource. - Dầu mỏ là một tài nguyên thiên nhiên.', 1),
  ('41000000-0000-0000-0018-000000000026', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000026', 'Từ nào có nghĩa là "bền vững"?', 2, '"sustainable" /səˈsteɪnəbl/ (adj.) nghĩa là "bền vững". Ví dụ: We need sustainable farming. - Chúng ta cần nông nghiệp bền vững.', 2),
  ('41000000-0000-0000-0018-000000000027', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000027', 'Chọn từ thích hợp để điền vào chỗ trống:\n"Wind is a ______ energy source."\n(Nghĩa: Gió là một nguồn năng lượng tái tạo.)', 2, '"renewable" /rɪˈnjuːəbl/ (adj.) nghĩa là "có thể tái tạo". Ví dụ: Wind is a renewable energy source. - Gió là một nguồn năng lượng tái tạo.', 3),
  ('41000000-0000-0000-0018-000000000028', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000028', 'Nghĩa của từ "carbon" là gì?', 3, '"carbon" /ˈkɑːbən/ (n.) nghĩa là "các-bon". Ví dụ: We must reduce carbon emissions. - Chúng ta phải giảm lượng khí thải các-bon.', 4),
  ('41000000-0000-0000-0018-000000000029', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000029', 'Từ nào có nghĩa là "khí thải"?', 2, '"emission" /ɪˈmɪʃn/ (n.) nghĩa là "khí thải". Ví dụ: Factory emission harms the air. - Khí thải nhà máy gây hại cho không khí.', 5),
  ('41000000-0000-0000-0018-000000000030', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000030', 'Chọn từ thích hợp để điền vào chỗ trống:\n"The ocean is a fragile ______."\n(Nghĩa: Đại dương là một hệ sinh thái mong manh.)', 3, '"ecosystem" /ˈiːkəʊsɪstəm/ (n.) nghĩa là "hệ sinh thái". Ví dụ: The ocean is a fragile ecosystem. - Đại dương là một hệ sinh thái mong manh.', 6),
  ('41000000-0000-0000-0018-000000000031', '40000000-0000-0000-0018-000000000004', '30000000-0000-0000-0018-000000000031', 'Nghĩa của từ "reduce" là gì?', 1, '"reduce" /rɪˈdjuːs/ (v.) nghĩa là "giảm bớt". Ví dụ: Let us reduce plastic bags. - Chúng ta hãy giảm số túi nhựa.', 7);
