INSERT INTO grammar_lessons (id, title, description, structure, content, usage_notes, icon_name, level, estimated_minutes, sort_order, is_published) VALUES
  ('20000000-0000-0000-0000-000000000006', 'To Be: am / is / are', 'Động từ to be dùng để giới thiệu, mô tả và nói về trạng thái.', 'S + am / is / are + noun / adjective', 'Động từ to be có ba dạng ở hiện tại: am (đi với I), is (he, she, it, danh từ số ít) và are (you, we, they, danh từ số nhiều).\nPhủ định: thêm not sau to be (am not, isn''t, aren''t).\nNghi vấn: đảo to be lên trước chủ ngữ: Are you a student?', 'Dạng rút gọn: I''m, you''re, he''s, she''s, it''s, we''re, they''re.\nTo be dùng để nói tên, tuổi, nghề nghiệp, quốc tịch và cảm giác: I am hungry.', 'person', 'A1', 8, 2, TRUE),
  ('20000000-0000-0000-0000-000000000007', 'There is / There are', 'Dùng để nói về sự tồn tại của người hay vật ở một nơi nào đó.', 'There is + singular noun / There are + plural noun', 'There is đi với danh từ số ít hoặc không đếm được; there are đi với danh từ số nhiều.\nPhủ định: There isn''t / There aren''t. Nghi vấn: Is there...? / Are there...?\nVới nhiều danh từ liệt kê, động từ hòa hợp với danh từ đứng ngay sau nó.', 'Thường đi với giới từ chỉ nơi chốn: on, in, under, next to, near.\nDùng there is/are để giới thiệu điều mới; dùng it is để nói về điều đã biết.', 'place', 'A1', 8, 4, TRUE),
  ('20000000-0000-0000-0000-000000000008', 'Articles: a / an / the', 'Cách dùng mạo từ không xác định (a, an) và mạo từ xác định (the).', 'a / an + singular countable noun; the + specific noun', 'A/an dùng trước danh từ đếm được số ít khi nói đến người hoặc vật chung chung, lần đầu được nhắc tới.\nAn dùng trước từ bắt đầu bằng nguyên âm (a, e, i, o, u theo cách phát âm): an apple, an hour.\nThe dùng khi người nghe đã biết ta nói về cái nào, hoặc vật là duy nhất: the sun, the moon.', 'Không dùng mạo từ trước danh từ số nhiều hoặc không đếm được khi nói chung: I like music.\nDùng a trước phụ âm (a university vì phát âm /juː/) và an trước nguyên âm (an umbrella).', 'label', 'A1', 10, 5, TRUE),
  ('20000000-0000-0000-0000-000000000009', 'Plural Nouns', 'Quy tắc chuyển danh từ số ít sang số nhiều, kể cả dạng bất quy tắc.', 'noun + s / es; irregular plural forms', 'Thông thường thêm -s: book - books.\nDanh từ tận cùng bằng s, x, z, ch, sh thêm -es: box - boxes, watch - watches.\nTận cùng bằng phụ âm + y đổi y thành i rồi thêm -es: baby - babies.\nDanh từ bất quy tắc: man - men, woman - women, child - children, foot - feet, tooth - teeth, mouse - mice.', 'Một số danh từ giữ nguyên ở số nhiều: sheep, fish, deer.\nDanh từ tận cùng bằng -f/-fe thường đổi thành -ves: leaf - leaves, knife - knives.', 'format_list_numbered', 'A1', 8, 6, TRUE),
  ('20000000-0000-0000-0000-000000000010', 'Countable & Uncountable Nouns', 'Phân biệt danh từ đếm được, không đếm được và cách dùng many, much.', 'many / a few + countable; much / a little + uncountable', 'Danh từ đếm được có số ít và số nhiều (an apple, two apples).\nDanh từ không đếm được không có dạng số nhiều và không dùng a/an: water, rice, money, advice, information.\nDùng many/a few với danh từ đếm được và much/a little với danh từ không đếm được.\nTrong câu hỏi How many? đi với đếm được, How much? đi với không đếm được.', 'Muốn đếm danh từ không đếm được ta dùng đơn vị: a glass of water, a piece of advice, a bottle of milk.\nMuch thường dùng trong câu phủ định và câu hỏi; câu khẳng định dùng a lot of.', 'scale', 'A1', 10, 7, TRUE),
  ('20000000-0000-0000-0000-000000000011', 'Subject Pronouns & Possessives', 'Đại từ nhân xưng, tính từ sở hữu và đại từ sở hữu.', 'I - my - mine; you - your - yours; he - his; she - her - hers', 'Đại từ chủ ngữ: I, you, he, she, it, we, they. Đại từ tân ngữ: me, you, him, her, it, us, them.\nTính từ sở hữu đứng trước danh từ: my, your, his, her, its, our, their.\nĐại từ sở hữu đứng một mình thay cho cụm danh từ: mine, yours, his, hers, ours, theirs.', 'Không dùng mạo từ cùng tính từ sở hữu: my book (không nói the my book).\nIt''s = it is; its = của nó (tính từ sở hữu).', 'people', 'A1', 10, 8, TRUE),
  ('20000000-0000-0000-0000-000000000012', 'Prepositions of Time and Place', 'Cách dùng in, on, at để chỉ thời gian và địa điểm.', 'in / on / at + time or place', 'Thời gian: at + giờ/thời điểm (at 7 o''clock, at night); on + ngày/thứ (on Monday, on 5th May); in + tháng/năm/mùa/buổi (in July, in 2025, in summer, in the morning).\nNơi chốn: at + điểm cụ thể (at the bus stop); on + bề mặt (on the table); in + không gian bao quanh (in the room, in Hanoi).', 'Một số cụm cố định: at home, at work, at school, on the left, in the middle, on the weekend (Mỹ) / at the weekend (Anh).', 'pin_drop', 'A1', 10, 9, TRUE),
  ('20000000-0000-0000-0000-000000000013', 'Wh- Questions', 'Đặt câu hỏi với who, what, where, when, why, how.', 'Wh-word + do/does/did + S + V?', 'Các từ để hỏi: who (ai), what (cái gì), where (ở đâu), when (khi nào), why (tại sao), which (cái nào), whose (của ai), how (như thế nào).\nVới động từ thường: Wh-word + do/does/did + chủ ngữ + động từ nguyên mẫu?\nVới to be: Wh-word + am/is/are + chủ ngữ?\nKhi từ để hỏi là chủ ngữ ta không cần trợ động từ: Who lives here?', 'How many/much, how long, how often, how old là các cụm hỏi thông dụng.\nTrả lời cho why thường mở đầu bằng because.', 'help_outline', 'A1', 10, 10, TRUE),
  ('20000000-0000-0000-0000-000000000014', 'Can / Can''t', 'Diễn tả khả năng, sự cho phép và lời đề nghị.', 'S + can / can''t + V (nguyên mẫu)', 'Can diễn tả khả năng (She can swim), sự cho phép (You can go now) và yêu cầu lịch sự (Can you help me?).\nSau can luôn là động từ nguyên mẫu không có to, và can không thêm -s với he/she/it.\nPhủ định: cannot (can''t). Nghi vấn: Can + S + V?', 'Quá khứ của can là could (She could swim when she was five).\nCannot viết liền; can not hiếm dùng.', 'check_circle', 'A1', 8, 11, TRUE),
  ('20000000-0000-0000-0000-000000000015', 'Adverbs of Frequency', 'Trạng từ chỉ tần suất và vị trí của chúng trong câu.', 'S + always / usually / often / sometimes / never + V', 'Thang tần suất: always (100%), usually (80%), often (60%), sometimes (40%), rarely/seldom (10%), never (0%).\nVị trí: đứng trước động từ thường (She always gets up early) và sau động từ to be (He is never late).\nSometimes, usually, often còn có thể đứng đầu hoặc cuối câu.', 'Never đã mang nghĩa phủ định nên không dùng thêm not: He never eats meat (không nói He doesn''t never...).\nCâu hỏi về tần suất: How often do you...?', 'repeat', 'A2', 8, 12, TRUE),
  ('20000000-0000-0000-0000-000000000016', 'Comparatives & Superlatives', 'So sánh hơn và so sánh nhất với tính từ ngắn và dài.', 'adj-er + than / more + adj + than; the + adj-est / the most + adj', 'Tính từ ngắn (1 âm tiết): thêm -er cho so sánh hơn, the -est cho so sánh nhất: tall - taller - the tallest.\nTính từ dài (từ 2 âm tiết trở lên): more + adj / the most + adj: more beautiful, the most expensive.\nTính từ tận cùng bằng phụ âm + y đổi y thành i: happy - happier - the happiest.\nBất quy tắc: good - better - the best; bad - worse - the worst; far - farther/further - the farthest/furthest.', 'So sánh bằng: as + adj + as (as tall as). So sánh hơn dùng than; so sánh nhất dùng the.\nCó thể nhấn mạnh bằng much/far: much taller, far more expensive.', 'trending_up', 'A2', 12, 13, TRUE),
  ('20000000-0000-0000-0000-000000000017', 'Past Continuous', 'Diễn tả hành động đang diễn ra tại một thời điểm trong quá khứ.', 'S + was / were + V-ing', 'Thì quá khứ tiếp diễn dùng cho hành động đang xảy ra tại một thời điểm cụ thể trong quá khứ.\nCũng dùng cho hành động đang diễn ra thì bị một hành động khác (quá khứ đơn) xen vào: I was cooking when the phone rang.\nPhủ định: was not / were not + V-ing. Nghi vấn: Was/Were + S + V-ing?', 'Dấu hiệu: at 8 o''clock last night, while, when, all day yesterday.\nWhile thường đi với quá khứ tiếp diễn; when thường đi với quá khứ đơn.', 'schedule', 'A2', 10, 15, TRUE),
  ('20000000-0000-0000-0000-000000000018', 'Future with Will', 'Diễn tả quyết định tức thời, dự đoán và lời hứa về tương lai.', 'S + will + V (nguyên mẫu)', 'Will dùng khi quyết định ngay lúc nói (I''ll answer the phone), đưa ra dự đoán (It will rain tomorrow), lời hứa hay lời đề nghị (I will help you).\nSau will luôn là động từ nguyên mẫu không có to.\nPhủ định: will not (won''t). Nghi vấn: Will + S + V?', 'Dấu hiệu: tomorrow, next week, in the future, I think, probably.\nDạng rút gọn: I''ll, you''ll, he''ll, she''ll, we''ll, they''ll.', 'bolt', 'A2', 10, 16, TRUE),
  ('20000000-0000-0000-0000-000000000019', 'Be Going To', 'Diễn tả kế hoạch đã định và dự đoán dựa trên bằng chứng ở hiện tại.', 'S + am / is / are + going to + V', 'Be going to dùng cho dự định đã có từ trước (I am going to study abroad) và dự đoán có căn cứ trong hiện tại (Look at the clouds! It is going to rain).\nPhủ định: am/is/are + not going to. Nghi vấn: Am/Is/Are + S + going to + V?', 'Will thường dùng cho quyết định tức thời, còn be going to dùng cho kế hoạch đã định trước.\nTrong văn nói gonna = going to.', 'directions_run', 'A2', 10, 17, TRUE),
  ('20000000-0000-0000-0000-000000000020', 'Must, Have to, Should', 'Diễn tả sự bắt buộc, sự cần thiết và lời khuyên.', 'S + must / have to / should + V', 'Must và have to diễn tả sự bắt buộc: must thường là quy định/ý kiến của người nói, have to là bắt buộc từ bên ngoài (luật lệ, công việc).\nShould diễn tả lời khuyên: You should drink more water.\nPhủ định: mustn''t (cấm), don''t have to (không cần thiết), shouldn''t (không nên).', 'Mustn''t và don''t have to khác nghĩa hoàn toàn: You mustn''t smoke here (bị cấm) và You don''t have to come (không cần đến).\nQuá khứ của have to là had to; must không có dạng quá khứ.', 'priority_high', 'A2', 10, 19, TRUE),
  ('20000000-0000-0000-0000-000000000021', 'Used To', 'Diễn tả thói quen hoặc trạng thái trong quá khứ nay không còn nữa.', 'S + used to + V (nguyên mẫu)', 'Used to + động từ nguyên mẫu nói về thói quen hoặc trạng thái đã từng có trong quá khứ nhưng hiện nay đã chấm dứt.\nPhủ định: didn''t use to + V. Nghi vấn: Did + S + use to + V?\nKhông nhầm với be used to + V-ing (quen với việc gì).', 'Used to chỉ có dạng quá khứ; hiện tại dùng hiện tại đơn.\nTrong câu phủ định và câu hỏi, did đã mang thì quá khứ nên ta viết use to (không có -d).', 'restore', 'A2', 8, 20, TRUE),
  ('20000000-0000-0000-0000-000000000022', 'Linking Words', 'Các từ nối thông dụng để nối ý và nối câu.', 'and / but / or / so / because / although + clause', 'And: thêm thông tin. But: tương phản. Or: lựa chọn.\nSo: chỉ kết quả (It was raining, so we stayed home). Because: chỉ nguyên nhân (We stayed home because it was raining).\nAlthough/though: dù, mặc dù (Although it was cold, we went out). Sau although là một mệnh đề đầy đủ.', 'Không dùng but cùng lúc với although trong một câu: Although he was tired, he kept working.\nKhi so và because đứng đầu mệnh đề thì dấu phẩy thường đặt trước so.', 'link', 'A2', 10, 21, TRUE),
  ('20000000-0000-0000-0000-000000000023', 'Quantifiers', 'Từ chỉ số lượng đi với danh từ đếm được và không đếm được.', 'some / any / a lot of / many / much / (a) few / (a) little', 'Some dùng trong câu khẳng định và lời mời/đề nghị; any dùng trong câu phủ định và câu hỏi.\nA few/few đi với danh từ đếm được số nhiều; a little/little đi với danh từ không đếm được.\nA few/a little mang nghĩa "một vài, đủ dùng"; few/little mang nghĩa "rất ít, gần như không có".', 'A lot of/lots of dùng được với cả hai loại danh từ, thường trong câu khẳng định.\nEnough đứng trước danh từ: enough money; đứng sau tính từ: old enough.', 'tune', 'A2', 10, 22, TRUE),
  ('20000000-0000-0000-0000-000000000024', 'Gerunds and Infinitives', 'Động từ theo sau bởi V-ing hoặc to + động từ nguyên mẫu.', 'V + V-ing / V + to + V', 'Một số động từ đi với V-ing: enjoy, avoid, finish, mind, suggest, keep, practice (She enjoys reading).\nMột số động từ đi với to + V: want, decide, hope, plan, need, agree, refuse, learn (He decided to leave).\nMột số động từ đi với cả hai: like, love, hate, start, begin (nghĩa gần như không đổi).\nGiới từ luôn được theo sau bởi V-ing: interested in learning, good at swimming.', 'Stop + V-ing nghĩa là ngừng làm việc đó; stop + to V nghĩa là dừng lại để làm việc khác.\nRemember/forget + to V nói về việc cần làm; remember/forget + V-ing nói về việc đã làm.', 'swap_horiz', 'B1', 12, 23, TRUE),
  ('20000000-0000-0000-0000-000000000025', 'Present Perfect Continuous', 'Nhấn mạnh quá trình của hành động kéo dài từ quá khứ đến hiện tại.', 'S + have / has + been + V-ing', 'Thì hiện tại hoàn thành tiếp diễn nhấn mạnh sự liên tục, thời gian kéo dài của hành động bắt đầu trong quá khứ và còn tiếp diễn hoặc vừa mới kết thúc.\nCấu trúc: S + have/has + been + V-ing.\nDùng với for + khoảng thời gian, since + mốc thời gian, all day, lately, recently.', 'Thì này nhấn mạnh quá trình (She has been working for two hours); hiện tại hoàn thành thường nhấn mạnh kết quả (She has finished the report).\nKhông dùng cho động từ chỉ trạng thái như know, like, have (sở hữu).', 'hourglass_bottom', 'B1', 12, 24, TRUE),
  ('20000000-0000-0000-0000-000000000026', 'Past Perfect', 'Diễn tả hành động đã xảy ra trước một hành động hoặc thời điểm khác trong quá khứ.', 'S + had + V3/V-ed', 'Thì quá khứ hoàn thành dùng để nói về hành động xảy ra và hoàn tất trước một hành động khác (hoặc một mốc thời gian) trong quá khứ.\nHành động xảy ra trước dùng past perfect, hành động sau dùng past simple: When I arrived, the film had started.\nPhủ định: had not (hadn''t) + V3. Nghi vấn: Had + S + V3?', 'Dấu hiệu: before, after, by the time, already, just, when, until then.\nDạng had giống nhau cho mọi chủ ngữ.', 'undo', 'B1', 12, 25, TRUE),
  ('20000000-0000-0000-0000-000000000027', 'Future Continuous', 'Diễn tả hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai.', 'S + will be + V-ing', 'Thì tương lai tiếp diễn dùng cho hành động sẽ đang xảy ra tại một thời điểm xác định trong tương lai.\nCấu trúc: S + will be + V-ing. Phủ định: will not be + V-ing. Nghi vấn: Will + S + be + V-ing?\nCũng dùng để hỏi lịch trình một cách lịch sự: Will you be using the car tonight?', 'Dấu hiệu: at this time tomorrow, at 8 p.m. next Monday, this time next week.\nKhác với will thường: I will call you (quyết định); I will be working at 8 (đang làm vào lúc đó).', 'update', 'B1', 10, 26, TRUE),
  ('20000000-0000-0000-0000-000000000028', 'Future Perfect', 'Diễn tả hành động sẽ hoàn thành trước một thời điểm trong tương lai.', 'S + will have + V3/V-ed', 'Thì tương lai hoàn thành dùng để nói về hành động sẽ hoàn tất trước một mốc thời gian trong tương lai.\nCấu trúc: S + will have + V3/V-ed. Phủ định: will not have + V3. Nghi vấn: Will + S + have + V3?', 'Dấu hiệu: by + mốc thời gian (by 2030, by next Friday), by the time + mệnh đề hiện tại đơn, before.\nVới by the time, mệnh đề thời gian dùng hiện tại đơn, không dùng will.', 'event_available', 'B1', 10, 27, TRUE),
  ('20000000-0000-0000-0000-000000000029', 'Passive Voice', 'Câu bị động nhấn mạnh hành động hoặc đối tượng chịu tác động.', 'S + be + V3/V-ed (+ by + agent)', 'Câu bị động dùng khi ta quan tâm đến hành động hoặc người/vật chịu tác động hơn là người thực hiện.\nCấu trúc: be + V3/V-ed, trong đó be chia theo thì của câu chủ động.\nHiện tại đơn: is/are + V3 (English is spoken here). Quá khứ đơn: was/were + V3 (The window was broken). Hiện tại hoàn thành: has/have been + V3. Tương lai: will be + V3.', 'Người thực hiện hành động được thêm bằng by khi cần thiết: The book was written by Tolstoy.\nChỉ động từ có tân ngữ (ngoại động từ) mới chuyển được sang bị động.', 'compare_arrows', 'B1', 14, 28, TRUE),
  ('20000000-0000-0000-0000-000000000030', 'Zero Conditional', 'Câu điều kiện loại 0 diễn tả sự thật hiển nhiên và quy luật tự nhiên.', 'If + S + V(hiện tại), S + V(hiện tại)', 'Câu điều kiện loại 0 nói về những điều luôn luôn đúng, chân lý khoa học hoặc thói quen: nếu điều kiện xảy ra thì kết quả chắc chắn xảy ra.\nCả mệnh đề if và mệnh đề chính đều dùng thì hiện tại đơn.\nIf có thể thay bằng when mà không đổi nghĩa.', 'Có thể đảo vị trí hai mệnh đề; khi mệnh đề if đứng đầu câu cần có dấu phẩy.\nMệnh đề chính cũng có thể là câu mệnh lệnh: If you feel sick, call a doctor.', 'alt_route', 'B1', 8, 29, TRUE),
  ('20000000-0000-0000-0000-000000000031', 'Second Conditional', 'Câu điều kiện loại 2 diễn tả tình huống không có thật hoặc khó xảy ra ở hiện tại.', 'If + S + V2/V-ed, S + would + V', 'Câu điều kiện loại 2 dùng cho giả định trái với thực tế ở hiện tại hoặc những điều rất khó xảy ra ở tương lai.\nMệnh đề if dùng quá khứ đơn, mệnh đề chính dùng would + động từ nguyên mẫu.\nVới to be, người ta thường dùng were cho mọi chủ ngữ: If I were you, I would go.', 'Dùng để khuyên bảo: If I were you, I would apologize.\nCould hoặc might có thể thay would để diễn tả khả năng: If I had a car, I could drive there.', 'alt_route', 'B1', 12, 31, TRUE),
  ('20000000-0000-0000-0000-000000000032', 'Third Conditional', 'Câu điều kiện loại 3 diễn tả điều không có thật trong quá khứ.', 'If + S + had + V3, S + would have + V3', 'Câu điều kiện loại 3 nói về giả định trái với sự thật đã xảy ra trong quá khứ và kết quả tưởng tượng của nó, thường mang ý tiếc nuối hoặc trách móc.\nMệnh đề if dùng quá khứ hoàn thành (had + V3), mệnh đề chính dùng would have + V3.\nCould have hoặc might have có thể thay would have để diễn tả khả năng.', 'Không dùng would have trong mệnh đề if.\nCó thể đảo vế: I would have passed if I had studied.', 'alt_route', 'B2', 12, 32, TRUE),
  ('20000000-0000-0000-0000-000000000033', 'Relative Clauses', 'Mệnh đề quan hệ bổ nghĩa cho danh từ đứng trước nó.', 'noun + who / which / that / whose / where + clause', 'Who dùng thay cho người, which dùng thay cho vật, that dùng cho cả người lẫn vật (trong mệnh đề xác định).\nWhose chỉ sự sở hữu: The man whose car was stolen called the police.\nWhere thay cho nơi chốn, when thay cho thời gian.\nMệnh đề quan hệ không xác định (thêm thông tin phụ) đặt giữa dấu phẩy và không dùng that.', 'Khi đại từ quan hệ là tân ngữ có thể lược bỏ trong mệnh đề xác định: The book (that) I read was great.\nKhông dùng thêm đại từ thừa: The man who lives next door is a doctor (không nói who he lives).', 'link', 'B1', 14, 33, TRUE),
  ('20000000-0000-0000-0000-000000000034', 'Reported Speech', 'Cách thuật lại lời nói của người khác.', 'S + said (that) + clause (lùi một thì)', 'Khi thuật lại lời nói, ta thường lùi thì về quá khứ một bậc và đổi đại từ, trạng từ chỉ thời gian/nơi chốn cho phù hợp.\nHiện tại đơn -> quá khứ đơn; hiện tại tiếp diễn -> quá khứ tiếp diễn; quá khứ đơn -> quá khứ hoàn thành; will -> would; can -> could.\nNow -> then, today -> that day, tomorrow -> the next day, yesterday -> the day before.\nCâu hỏi Yes/No dùng if/whether; câu hỏi Wh- giữ từ để hỏi và đổi sang trật tự câu khẳng định.', 'Say không có tân ngữ chỉ người (He said that...); tell cần tân ngữ (He told me that...).\nKhông lùi thì khi thuật lại chân lý hoặc khi sự việc vẫn còn đúng.', 'record_voice_over', 'B1', 14, 34, TRUE),
  ('20000000-0000-0000-0000-000000000035', 'Modal Verbs of Possibility', 'Diễn tả mức độ chắc chắn, suy đoán về hiện tại và tương lai.', 'S + must / may / might / could / can''t + V', 'Must dùng khi gần như chắc chắn điều gì đó đúng (He must be at home).\nMay, might, could dùng khi chỉ là khả năng (It may rain later). Might ít chắc chắn hơn may.\nCan''t dùng khi gần như chắc chắn điều gì đó không đúng (That can''t be true).\nSuy đoán về quá khứ: modal + have + V3 (She must have forgotten).', 'Mức độ chắc chắn giảm dần: must > may/might/could > can''t (phủ định chắc chắn).\nKhông dùng must not để nói điều không thể; dùng can''t.', 'psychology', 'B1', 10, 35, TRUE),
  ('20000000-0000-0000-0000-000000000036', 'Question Tags', 'Câu hỏi đuôi dùng để xác nhận thông tin hoặc mời người nghe đồng ý.', 'positive statement, negative tag? / negative statement, positive tag?', 'Câu hỏi đuôi gồm một câu trần thuật và một phần hỏi ngắn ở cuối.\nCâu khẳng định thì đuôi phủ định: You are a student, aren''t you? Câu phủ định thì đuôi khẳng định: She doesn''t like coffee, does she?\nĐuôi dùng trợ động từ hoặc to be của câu chính và đại từ thay cho chủ ngữ. Nếu câu chính không có trợ động từ, dùng do/does/did.', 'Trường hợp đặc biệt: I am ..., aren''t I?; Let''s ..., shall we?; Imperatives ..., will you?\nGiọng đi xuống nghĩa là xác nhận; giọng đi lên nghĩa là thực sự hỏi.', 'question_answer', 'B1', 10, 36, TRUE),
  ('20000000-0000-0000-0000-000000000037', 'Mixed Conditionals', 'Câu điều kiện hỗn hợp kết hợp giả định ở quá khứ với kết quả ở hiện tại và ngược lại.', 'If + S + had + V3, S + would + V  /  If + S + V2, S + would have + V3', 'Loại thông dụng nhất: điều kiện ở quá khứ, kết quả ở hiện tại: If + had + V3, would + V. Ví dụ: If I had studied medicine, I would be a doctor now.\nLoại còn lại: điều kiện ở hiện tại (luôn đúng), kết quả ở quá khứ: If + quá khứ đơn, would have + V3. Ví dụ: If I were braver, I would have spoken up.\nThường xuất hiện từ now/today ở mệnh đề kết quả khi nói về hiện tại.', 'Giúp biểu đạt tiếc nuối về quyết định trong quá khứ ảnh hưởng đến hiện tại.\nCần xác định đúng mốc thời gian của từng mệnh đề trước khi chọn thì.', 'alt_route', 'B2', 12, 37, TRUE),
  ('20000000-0000-0000-0000-000000000038', 'Wish and If Only', 'Diễn tả điều ước, sự tiếc nuối về hiện tại, quá khứ và tương lai.', 'S + wish + S + V2 / had V3 / would V', 'Ước điều không có thật ở hiện tại: wish + quá khứ đơn (I wish I had a car).\nTiếc nuối về quá khứ: wish + had + V3 (I wish I had studied harder).\nMong điều gì thay đổi ở tương lai hoặc phàn nàn về thói quen gây khó chịu: wish + would + V (I wish it would stop raining).\nIf only mạnh hơn wish và dùng cùng cấu trúc.', 'Sau wish dùng were cho mọi chủ ngữ trong văn trang trọng: I wish I were taller.\nKhông dùng wish + would với chính chủ ngữ của wish: nói I wish I could ... thay vì I wish I would ....', 'star_border', 'B2', 10, 38, TRUE),
  ('20000000-0000-0000-0000-000000000039', 'Causative: have / get something done', 'Cấu trúc nhờ hoặc thuê người khác làm việc gì đó cho mình.', 'S + have / get + object + V3/V-ed', 'Dùng have/get + tân ngữ + V3 khi ai đó làm việc gì cho ta (thường là dịch vụ): I had my hair cut (tôi đi cắt tóc).\nCấu trúc nhờ người cụ thể: have + người + V nguyên mẫu (I had the mechanic fix my car); get + người + to V.\nCũng dùng để nói về điều không may xảy ra với ta: He had his wallet stolen.', 'Get something done mang tính thân mật hơn have something done.\nChia thì ở have/get: She is having her house painted; We have had the car repaired.', 'build', 'B2', 10, 39, TRUE),
  ('20000000-0000-0000-0000-000000000040', 'Inversion with Negative Adverbs', 'Đảo ngữ sau các trạng từ phủ định để nhấn mạnh trong văn trang trọng.', 'Negative adverb + auxiliary + S + V', 'Khi trạng từ phủ định hoặc bán phủ định đứng đầu câu, ta đảo trợ động từ lên trước chủ ngữ để nhấn mạnh.\nCác trạng từ thường gặp: never, rarely, seldom, hardly ... when, no sooner ... than, not only ... but also, only after, little.\nVí dụ: Never have I seen such a beautiful place. Hardly had she arrived when the phone rang. Not only did he lie, but he also stole.', 'Nếu câu không có trợ động từ, dùng do/does/did: Rarely does he speak in public.\nDạng này chủ yếu dùng trong văn viết và phát biểu trang trọng.', 'flip', 'C1', 12, 40, TRUE);
INSERT INTO grammar_examples (id, grammar_lesson_id, sentence, translation, highlight, sort_order) VALUES
  ('21000000-0000-0000-0001-000000000001', '20000000-0000-0000-0000-000000000001', 'I drink coffee every morning.', 'Tôi uống cà phê mỗi sáng.', 'drink', 11),
  ('21000000-0000-0000-0001-000000000002', '20000000-0000-0000-0000-000000000001', 'Water boils at 100 degrees.', 'Nước sôi ở 100 độ.', 'boils', 12),
  ('21000000-0000-0000-0001-000000000003', '20000000-0000-0000-0000-000000000001', 'Does she live in Hanoi?', 'Cô ấy có sống ở Hà Nội không?', 'Does she live', 13),
  ('21000000-0000-0000-0001-000000000004', '20000000-0000-0000-0000-000000000001', 'He doesn''t eat meat.', 'Anh ấy không ăn thịt.', 'doesn''t eat', 14),
  ('21000000-0000-0000-0006-000000000001', '20000000-0000-0000-0000-000000000006', 'I am a student.', 'Tôi là một học sinh.', 'am', 1),
  ('21000000-0000-0000-0006-000000000002', '20000000-0000-0000-0000-000000000006', 'She is from Vietnam.', 'Cô ấy đến từ Việt Nam.', 'is', 2),
  ('21000000-0000-0000-0006-000000000003', '20000000-0000-0000-0000-000000000006', 'We are very happy today.', 'Hôm nay chúng tôi rất vui.', 'are', 3),
  ('21000000-0000-0000-0006-000000000004', '20000000-0000-0000-0000-000000000006', 'Are they at home?', 'Họ có ở nhà không?', 'Are they', 4),
  ('21000000-0000-0000-0002-000000000001', '20000000-0000-0000-0000-000000000002', 'I am studying English now.', 'Bây giờ tôi đang học tiếng Anh.', 'am studying', 11),
  ('21000000-0000-0000-0002-000000000002', '20000000-0000-0000-0000-000000000002', 'Look! It is raining.', 'Nhìn kìa! Trời đang mưa.', 'is raining', 12),
  ('21000000-0000-0000-0002-000000000003', '20000000-0000-0000-0000-000000000002', 'They are not watching TV.', 'Họ không xem TV.', 'are not watching', 13),
  ('21000000-0000-0000-0002-000000000004', '20000000-0000-0000-0000-000000000002', 'What are you doing?', 'Bạn đang làm gì vậy?', 'are you doing', 14),
  ('21000000-0000-0000-0007-000000000001', '20000000-0000-0000-0000-000000000007', 'There is a book on the table.', 'Có một quyển sách trên bàn.', 'There is', 1),
  ('21000000-0000-0000-0007-000000000002', '20000000-0000-0000-0000-000000000007', 'There are three chairs in the room.', 'Có ba cái ghế trong phòng.', 'There are', 2),
  ('21000000-0000-0000-0007-000000000003', '20000000-0000-0000-0000-000000000007', 'Is there a bank near here?', 'Gần đây có ngân hàng không?', 'Is there', 3),
  ('21000000-0000-0000-0007-000000000004', '20000000-0000-0000-0000-000000000007', 'There aren''t any students in the class.', 'Không có học sinh nào trong lớp.', 'There aren''t', 4),
  ('21000000-0000-0000-0008-000000000001', '20000000-0000-0000-0000-000000000008', 'I have a dog and a cat.', 'Tôi có một con chó và một con mèo.', 'a dog', 1),
  ('21000000-0000-0000-0008-000000000002', '20000000-0000-0000-0000-000000000008', 'She eats an apple every day.', 'Cô ấy ăn một quả táo mỗi ngày.', 'an apple', 2),
  ('21000000-0000-0000-0008-000000000003', '20000000-0000-0000-0000-000000000008', 'The dog is very friendly.', 'Con chó đó rất thân thiện.', 'The dog', 3),
  ('21000000-0000-0000-0008-000000000004', '20000000-0000-0000-0000-000000000008', 'The sun rises in the east.', 'Mặt trời mọc ở hướng đông.', 'The sun', 4),
  ('21000000-0000-0000-0009-000000000001', '20000000-0000-0000-0000-000000000009', 'There are two boxes on the table.', 'Có hai cái hộp trên bàn.', 'boxes', 1),
  ('21000000-0000-0000-0009-000000000002', '20000000-0000-0000-0000-000000000009', 'The children are playing outside.', 'Bọn trẻ đang chơi ngoài trời.', 'children', 2),
  ('21000000-0000-0000-0009-000000000003', '20000000-0000-0000-0000-000000000009', 'I have three babies in my class.', 'Tôi có ba em bé trong lớp.', 'babies', 3),
  ('21000000-0000-0000-0009-000000000004', '20000000-0000-0000-0000-000000000009', 'Brush your teeth twice a day.', 'Hãy đánh răng hai lần một ngày.', 'teeth', 4),
  ('21000000-0000-0000-0010-000000000001', '20000000-0000-0000-0000-000000000010', 'How many apples do you want?', 'Bạn muốn bao nhiêu quả táo?', 'How many', 1),
  ('21000000-0000-0000-0010-000000000002', '20000000-0000-0000-0000-000000000010', 'How much water do you drink?', 'Bạn uống bao nhiêu nước?', 'How much', 2),
  ('21000000-0000-0000-0010-000000000003', '20000000-0000-0000-0000-000000000010', 'She gave me a piece of advice.', 'Cô ấy cho tôi một lời khuyên.', 'a piece of advice', 3),
  ('21000000-0000-0000-0010-000000000004', '20000000-0000-0000-0000-000000000010', 'I don''t have much money.', 'Tôi không có nhiều tiền.', 'much money', 4),
  ('21000000-0000-0000-0011-000000000001', '20000000-0000-0000-0000-000000000011', 'This is my bag.', 'Đây là cái túi của tôi.', 'my', 1),
  ('21000000-0000-0000-0011-000000000002', '20000000-0000-0000-0000-000000000011', 'She loves her job.', 'Cô ấy yêu công việc của mình.', 'her', 2),
  ('21000000-0000-0000-0011-000000000003', '20000000-0000-0000-0000-000000000011', 'The red car is ours.', 'Chiếc xe màu đỏ là của chúng tôi.', 'ours', 3),
  ('21000000-0000-0000-0011-000000000004', '20000000-0000-0000-0000-000000000011', 'Please help me.', 'Làm ơn giúp tôi.', 'me', 4),
  ('21000000-0000-0000-0012-000000000001', '20000000-0000-0000-0000-000000000012', 'The class starts at 8 o''clock.', 'Lớp học bắt đầu lúc 8 giờ.', 'at 8 o''clock', 1),
  ('21000000-0000-0000-0012-000000000002', '20000000-0000-0000-0000-000000000012', 'My birthday is on Friday.', 'Sinh nhật tôi vào thứ Sáu.', 'on Friday', 2),
  ('21000000-0000-0000-0012-000000000003', '20000000-0000-0000-0000-000000000012', 'We go to the beach in summer.', 'Chúng tôi đi biển vào mùa hè.', 'in summer', 3),
  ('21000000-0000-0000-0012-000000000004', '20000000-0000-0000-0000-000000000012', 'The keys are on the table.', 'Chìa khóa ở trên bàn.', 'on the table', 4),
  ('21000000-0000-0000-0013-000000000001', '20000000-0000-0000-0000-000000000013', 'Where do you live?', 'Bạn sống ở đâu?', 'Where do you live', 1),
  ('21000000-0000-0000-0013-000000000002', '20000000-0000-0000-0000-000000000013', 'What is your name?', 'Tên bạn là gì?', 'What is', 2),
  ('21000000-0000-0000-0013-000000000003', '20000000-0000-0000-0000-000000000013', 'Why did she leave early?', 'Tại sao cô ấy về sớm?', 'Why did', 3),
  ('21000000-0000-0000-0013-000000000004', '20000000-0000-0000-0000-000000000013', 'How often do you exercise?', 'Bạn tập thể dục thường xuyên thế nào?', 'How often', 4);
INSERT INTO grammar_examples (id, grammar_lesson_id, sentence, translation, highlight, sort_order) VALUES
  ('21000000-0000-0000-0014-000000000001', '20000000-0000-0000-0000-000000000014', 'She can speak three languages.', 'Cô ấy nói được ba ngôn ngữ.', 'can speak', 1),
  ('21000000-0000-0000-0014-000000000002', '20000000-0000-0000-0000-000000000014', 'I can''t find my keys.', 'Tôi không tìm thấy chìa khóa.', 'can''t find', 2),
  ('21000000-0000-0000-0014-000000000003', '20000000-0000-0000-0000-000000000014', 'Can you open the window, please?', 'Bạn mở cửa sổ giúp tôi được không?', 'Can you open', 3),
  ('21000000-0000-0000-0014-000000000004', '20000000-0000-0000-0000-000000000014', 'Birds can fly, but fish can''t.', 'Chim biết bay, nhưng cá thì không.', 'can fly', 4),
  ('21000000-0000-0000-0015-000000000001', '20000000-0000-0000-0000-000000000015', 'I always brush my teeth after dinner.', 'Tôi luôn đánh răng sau bữa tối.', 'always brush', 1),
  ('21000000-0000-0000-0015-000000000002', '20000000-0000-0000-0000-000000000015', 'She is never late for school.', 'Cô ấy không bao giờ đi học muộn.', 'is never', 2),
  ('21000000-0000-0000-0015-000000000003', '20000000-0000-0000-0000-000000000015', 'We sometimes eat out on Sundays.', 'Thỉnh thoảng chúng tôi ăn ngoài vào Chủ nhật.', 'sometimes eat', 3),
  ('21000000-0000-0000-0015-000000000004', '20000000-0000-0000-0000-000000000015', 'How often do you go to the gym?', 'Bạn đến phòng tập thường xuyên thế nào?', 'How often', 4),
  ('21000000-0000-0000-0016-000000000001', '20000000-0000-0000-0000-000000000016', 'My brother is taller than me.', 'Anh tôi cao hơn tôi.', 'taller than', 1),
  ('21000000-0000-0000-0016-000000000002', '20000000-0000-0000-0000-000000000016', 'This is the most interesting book I have read.', 'Đây là quyển sách thú vị nhất tôi từng đọc.', 'the most interesting', 2),
  ('21000000-0000-0000-0016-000000000003', '20000000-0000-0000-0000-000000000016', 'Today is hotter than yesterday.', 'Hôm nay nóng hơn hôm qua.', 'hotter than', 3),
  ('21000000-0000-0000-0016-000000000004', '20000000-0000-0000-0000-000000000016', 'She is the best student in the class.', 'Cô ấy là học sinh giỏi nhất lớp.', 'the best', 4),
  ('21000000-0000-0000-0003-000000000001', '20000000-0000-0000-0000-000000000003', 'We visited Hue last summer.', 'Mùa hè năm ngoái chúng tôi đã đến thăm Huế.', 'visited', 11),
  ('21000000-0000-0000-0003-000000000002', '20000000-0000-0000-0000-000000000003', 'She didn''t come to the party.', 'Cô ấy đã không đến bữa tiệc.', 'didn''t come', 12),
  ('21000000-0000-0000-0003-000000000003', '20000000-0000-0000-0000-000000000003', 'Did you finish your homework?', 'Bạn đã làm xong bài tập chưa?', 'Did you finish', 13),
  ('21000000-0000-0000-0003-000000000004', '20000000-0000-0000-0000-000000000003', 'He bought a new phone two days ago.', 'Anh ấy đã mua một chiếc điện thoại mới hai ngày trước.', 'bought', 14),
  ('21000000-0000-0000-0017-000000000001', '20000000-0000-0000-0000-000000000017', 'I was watching TV at nine last night.', 'Chín giờ tối qua tôi đang xem TV.', 'was watching', 1),
  ('21000000-0000-0000-0017-000000000002', '20000000-0000-0000-0000-000000000017', 'She was cooking when I arrived.', 'Cô ấy đang nấu ăn khi tôi đến.', 'was cooking', 2),
  ('21000000-0000-0000-0017-000000000003', '20000000-0000-0000-0000-000000000017', 'They were playing football while it was raining.', 'Họ đang chơi bóng trong khi trời đang mưa.', 'were playing', 3),
  ('21000000-0000-0000-0017-000000000004', '20000000-0000-0000-0000-000000000017', 'Were you sleeping at 10 p.m.?', 'Lúc 10 giờ tối bạn có đang ngủ không?', 'Were you sleeping', 4),
  ('21000000-0000-0000-0018-000000000001', '20000000-0000-0000-0000-000000000018', 'I will call you tomorrow.', 'Ngày mai tôi sẽ gọi cho bạn.', 'will call', 1),
  ('21000000-0000-0000-0018-000000000002', '20000000-0000-0000-0000-000000000018', 'It''s hot. I''ll open the window.', 'Nóng quá. Tôi sẽ mở cửa sổ.', 'I''ll open', 2),
  ('21000000-0000-0000-0018-000000000003', '20000000-0000-0000-0000-000000000018', 'I think she will pass the exam.', 'Tôi nghĩ cô ấy sẽ đậu kỳ thi.', 'will pass', 3),
  ('21000000-0000-0000-0018-000000000004', '20000000-0000-0000-0000-000000000018', 'Will you marry me?', 'Em sẽ lấy anh chứ?', 'Will you marry', 4),
  ('21000000-0000-0000-0019-000000000001', '20000000-0000-0000-0000-000000000019', 'I am going to visit my grandparents this weekend.', 'Cuối tuần này tôi sẽ đi thăm ông bà.', 'am going to visit', 1),
  ('21000000-0000-0000-0019-000000000002', '20000000-0000-0000-0000-000000000019', 'Look at those clouds! It is going to rain.', 'Nhìn những đám mây kia kìa! Trời sắp mưa.', 'is going to rain', 2),
  ('21000000-0000-0000-0019-000000000003', '20000000-0000-0000-0000-000000000019', 'They are not going to buy a car.', 'Họ sẽ không mua xe ô tô.', 'are not going to buy', 3),
  ('21000000-0000-0000-0019-000000000004', '20000000-0000-0000-0000-000000000019', 'Are you going to join the club?', 'Bạn có định tham gia câu lạc bộ không?', 'Are you going to join', 4),
  ('21000000-0000-0000-0004-000000000001', '20000000-0000-0000-0000-000000000004', 'I have finished my homework.', 'Tôi đã làm xong bài tập.', 'have finished', 11),
  ('21000000-0000-0000-0004-000000000002', '20000000-0000-0000-0000-000000000004', 'She has lived here for ten years.', 'Cô ấy đã sống ở đây mười năm.', 'has lived', 12),
  ('21000000-0000-0000-0004-000000000003', '20000000-0000-0000-0000-000000000004', 'Have you ever been to Japan?', 'Bạn đã bao giờ đến Nhật Bản chưa?', 'Have you ever been', 13),
  ('21000000-0000-0000-0004-000000000004', '20000000-0000-0000-0000-000000000004', 'They haven''t seen that film yet.', 'Họ vẫn chưa xem bộ phim đó.', 'haven''t seen', 14),
  ('21000000-0000-0000-0020-000000000001', '20000000-0000-0000-0000-000000000020', 'You must wear a helmet.', 'Bạn phải đội mũ bảo hiểm.', 'must wear', 1),
  ('21000000-0000-0000-0020-000000000002', '20000000-0000-0000-0000-000000000020', 'I have to get up at 5 every day.', 'Tôi phải dậy lúc 5 giờ mỗi ngày.', 'have to get up', 2),
  ('21000000-0000-0000-0020-000000000003', '20000000-0000-0000-0000-000000000020', 'You should see a doctor.', 'Bạn nên đi khám bác sĩ.', 'should see', 3),
  ('21000000-0000-0000-0020-000000000004', '20000000-0000-0000-0000-000000000020', 'You don''t have to pay. It is free.', 'Bạn không cần trả tiền. Nó miễn phí.', 'don''t have to pay', 4),
  ('21000000-0000-0000-0021-000000000001', '20000000-0000-0000-0000-000000000021', 'I used to play football every day.', 'Trước đây tôi chơi bóng đá mỗi ngày.', 'used to play', 1),
  ('21000000-0000-0000-0021-000000000002', '20000000-0000-0000-0000-000000000021', 'She used to live in Hanoi.', 'Trước kia cô ấy sống ở Hà Nội.', 'used to live', 2),
  ('21000000-0000-0000-0021-000000000003', '20000000-0000-0000-0000-000000000021', 'We didn''t use to have a car.', 'Trước đây chúng tôi không có xe hơi.', 'didn''t use to have', 3),
  ('21000000-0000-0000-0021-000000000004', '20000000-0000-0000-0000-000000000021', 'Did you use to walk to school?', 'Trước đây bạn có đi bộ đến trường không?', 'Did you use to walk', 4);
INSERT INTO grammar_examples (id, grammar_lesson_id, sentence, translation, highlight, sort_order) VALUES
  ('21000000-0000-0000-0022-000000000001', '20000000-0000-0000-0000-000000000022', 'I like tea, but my sister likes coffee.', 'Tôi thích trà, nhưng em gái tôi thích cà phê.', 'but', 1),
  ('21000000-0000-0000-0022-000000000002', '20000000-0000-0000-0000-000000000022', 'It was raining, so we stayed at home.', 'Trời mưa nên chúng tôi ở nhà.', 'so', 2),
  ('21000000-0000-0000-0022-000000000003', '20000000-0000-0000-0000-000000000022', 'She was late because she missed the bus.', 'Cô ấy đến muộn vì lỡ xe buýt.', 'because', 3),
  ('21000000-0000-0000-0022-000000000004', '20000000-0000-0000-0000-000000000022', 'Although he was tired, he kept working.', 'Mặc dù mệt, anh ấy vẫn tiếp tục làm việc.', 'Although', 4),
  ('21000000-0000-0000-0023-000000000001', '20000000-0000-0000-0000-000000000023', 'I have some questions for you.', 'Tôi có vài câu hỏi cho bạn.', 'some', 1),
  ('21000000-0000-0000-0023-000000000002', '20000000-0000-0000-0000-000000000023', 'We don''t have any eggs.', 'Chúng tôi không có quả trứng nào.', 'any', 2),
  ('21000000-0000-0000-0023-000000000003', '20000000-0000-0000-0000-000000000023', 'She has a few friends in this city.', 'Cô ấy có vài người bạn ở thành phố này.', 'a few', 3),
  ('21000000-0000-0000-0023-000000000004', '20000000-0000-0000-0000-000000000023', 'There is little sugar left.', 'Còn rất ít đường.', 'little', 4),
  ('21000000-0000-0000-0024-000000000001', '20000000-0000-0000-0000-000000000024', 'She enjoys reading novels.', 'Cô ấy thích đọc tiểu thuyết.', 'enjoys reading', 1),
  ('21000000-0000-0000-0024-000000000002', '20000000-0000-0000-0000-000000000024', 'He decided to study abroad.', 'Anh ấy quyết định đi du học.', 'decided to study', 2),
  ('21000000-0000-0000-0024-000000000003', '20000000-0000-0000-0000-000000000024', 'I am interested in learning French.', 'Tôi quan tâm đến việc học tiếng Pháp.', 'interested in learning', 3),
  ('21000000-0000-0000-0024-000000000004', '20000000-0000-0000-0000-000000000024', 'They stopped to take a photo.', 'Họ dừng lại để chụp một bức ảnh.', 'stopped to take', 4),
  ('21000000-0000-0000-0025-000000000001', '20000000-0000-0000-0000-000000000025', 'I have been learning English for three years.', 'Tôi đã học tiếng Anh được ba năm.', 'have been learning', 1),
  ('21000000-0000-0000-0025-000000000002', '20000000-0000-0000-0000-000000000025', 'She has been working since 8 o''clock.', 'Cô ấy làm việc từ lúc 8 giờ.', 'has been working', 2),
  ('21000000-0000-0000-0025-000000000003', '20000000-0000-0000-0000-000000000025', 'It has been raining all day.', 'Trời mưa suốt cả ngày.', 'has been raining', 3),
  ('21000000-0000-0000-0025-000000000004', '20000000-0000-0000-0000-000000000025', 'How long have you been waiting?', 'Bạn đã đợi bao lâu rồi?', 'have you been waiting', 4),
  ('21000000-0000-0000-0026-000000000001', '20000000-0000-0000-0000-000000000026', 'When I arrived, the film had already started.', 'Khi tôi đến, bộ phim đã bắt đầu rồi.', 'had already started', 1),
  ('21000000-0000-0000-0026-000000000002', '20000000-0000-0000-0000-000000000026', 'She had finished her work before he called.', 'Cô ấy đã làm xong việc trước khi anh ấy gọi.', 'had finished', 2),
  ('21000000-0000-0000-0026-000000000003', '20000000-0000-0000-0000-000000000026', 'They hadn''t eaten anything by noon.', 'Đến trưa họ vẫn chưa ăn gì.', 'hadn''t eaten', 3),
  ('21000000-0000-0000-0026-000000000004', '20000000-0000-0000-0000-000000000026', 'Had you seen him before the party?', 'Bạn đã gặp anh ấy trước bữa tiệc chưa?', 'Had you seen', 4),
  ('21000000-0000-0000-0027-000000000001', '20000000-0000-0000-0000-000000000027', 'At 8 p.m. tomorrow, I will be watching the match.', '8 giờ tối mai tôi sẽ đang xem trận đấu.', 'will be watching', 1),
  ('21000000-0000-0000-0027-000000000002', '20000000-0000-0000-0000-000000000027', 'This time next week, we will be flying to Paris.', 'Giờ này tuần sau chúng tôi sẽ đang bay đến Paris.', 'will be flying', 2),
  ('21000000-0000-0000-0027-000000000003', '20000000-0000-0000-0000-000000000027', 'She won''t be working on Sunday.', 'Chủ nhật cô ấy sẽ không làm việc.', 'won''t be working', 3),
  ('21000000-0000-0000-0027-000000000004', '20000000-0000-0000-0000-000000000027', 'Will you be staying here tonight?', 'Tối nay bạn có ở lại đây không?', 'Will you be staying', 4),
  ('21000000-0000-0000-0028-000000000001', '20000000-0000-0000-0000-000000000028', 'I will have finished the report by Friday.', 'Tôi sẽ hoàn thành bản báo cáo trước thứ Sáu.', 'will have finished', 1),
  ('21000000-0000-0000-0028-000000000002', '20000000-0000-0000-0000-000000000028', 'By 2030, she will have graduated.', 'Đến năm 2030 cô ấy sẽ đã tốt nghiệp.', 'will have graduated', 2),
  ('21000000-0000-0000-0028-000000000003', '20000000-0000-0000-0000-000000000028', 'They won''t have arrived by six.', 'Họ sẽ chưa đến kịp trước sáu giờ.', 'won''t have arrived', 3),
  ('21000000-0000-0000-0028-000000000004', '20000000-0000-0000-0000-000000000028', 'Will you have finished by noon?', 'Bạn sẽ làm xong trước buổi trưa chứ?', 'Will you have finished', 4),
  ('21000000-0000-0000-0029-000000000001', '20000000-0000-0000-0000-000000000029', 'English is spoken all over the world.', 'Tiếng Anh được nói trên khắp thế giới.', 'is spoken', 1),
  ('21000000-0000-0000-0029-000000000002', '20000000-0000-0000-0000-000000000029', 'The window was broken yesterday.', 'Cửa sổ bị vỡ hôm qua.', 'was broken', 2),
  ('21000000-0000-0000-0029-000000000003', '20000000-0000-0000-0000-000000000029', 'The letter will be sent tomorrow.', 'Lá thư sẽ được gửi vào ngày mai.', 'will be sent', 3),
  ('21000000-0000-0000-0029-000000000004', '20000000-0000-0000-0000-000000000029', 'This house was built by my grandfather.', 'Ngôi nhà này do ông tôi xây.', 'was built by', 4),
  ('21000000-0000-0000-0030-000000000001', '20000000-0000-0000-0000-000000000030', 'If you heat ice, it melts.', 'Nếu bạn làm nóng đá thì nó tan chảy.', 'heat', 1),
  ('21000000-0000-0000-0030-000000000002', '20000000-0000-0000-0000-000000000030', 'If it rains, the streets get wet.', 'Nếu trời mưa thì đường phố bị ướt.', 'rains', 2),
  ('21000000-0000-0000-0030-000000000003', '20000000-0000-0000-0000-000000000030', 'Plants die if they don''t get water.', 'Cây chết nếu không được tưới nước.', 'die', 3),
  ('21000000-0000-0000-0030-000000000004', '20000000-0000-0000-0000-000000000030', 'If you mix red and blue, you get purple.', 'Nếu trộn đỏ với xanh bạn được màu tím.', 'mix', 4),
  ('21000000-0000-0000-0005-000000000001', '20000000-0000-0000-0000-000000000005', 'If it rains, I will stay at home.', 'Nếu trời mưa, tôi sẽ ở nhà.', 'If it rains', 11),
  ('21000000-0000-0000-0005-000000000002', '20000000-0000-0000-0000-000000000005', 'If you study hard, you will pass the exam.', 'Nếu học chăm chỉ, bạn sẽ đậu kỳ thi.', 'will pass', 12),
  ('21000000-0000-0000-0005-000000000003', '20000000-0000-0000-0000-000000000005', 'She will be angry if you are late.', 'Cô ấy sẽ giận nếu bạn đến muộn.', 'will be angry', 13),
  ('21000000-0000-0000-0005-000000000004', '20000000-0000-0000-0000-000000000005', 'Unless you hurry, you will miss the bus.', 'Nếu không nhanh lên, bạn sẽ lỡ xe buýt.', 'Unless you hurry', 14);
INSERT INTO grammar_examples (id, grammar_lesson_id, sentence, translation, highlight, sort_order) VALUES
  ('21000000-0000-0000-0031-000000000001', '20000000-0000-0000-0000-000000000031', 'If I won the lottery, I would buy a house.', 'Nếu trúng số, tôi sẽ mua nhà.', 'would buy', 1),
  ('21000000-0000-0000-0031-000000000002', '20000000-0000-0000-0000-000000000031', 'If I were you, I would study harder.', 'Nếu tôi là bạn, tôi sẽ học chăm hơn.', 'If I were you', 2),
  ('21000000-0000-0000-0031-000000000003', '20000000-0000-0000-0000-000000000031', 'She would travel more if she had more money.', 'Cô ấy sẽ đi du lịch nhiều hơn nếu có nhiều tiền hơn.', 'would travel', 3),
  ('21000000-0000-0000-0031-000000000004', '20000000-0000-0000-0000-000000000031', 'What would you do if you saw a ghost?', 'Bạn sẽ làm gì nếu nhìn thấy ma?', 'would you do', 4),
  ('21000000-0000-0000-0032-000000000001', '20000000-0000-0000-0000-000000000032', 'If I had studied, I would have passed the exam.', 'Nếu tôi đã học bài thì tôi đã đậu kỳ thi.', 'had studied', 1),
  ('21000000-0000-0000-0032-000000000002', '20000000-0000-0000-0000-000000000032', 'If she had left earlier, she wouldn''t have missed the train.', 'Nếu cô ấy đi sớm hơn thì cô ấy đã không lỡ chuyến tàu.', 'wouldn''t have missed', 2),
  ('21000000-0000-0000-0032-000000000003', '20000000-0000-0000-0000-000000000032', 'We would have won if we had played better.', 'Chúng tôi đã thắng nếu chúng tôi chơi tốt hơn.', 'would have won', 3),
  ('21000000-0000-0000-0032-000000000004', '20000000-0000-0000-0000-000000000032', 'What would you have done if you had seen him?', 'Bạn đã làm gì nếu bạn nhìn thấy anh ấy?', 'would you have done', 4),
  ('21000000-0000-0000-0033-000000000001', '20000000-0000-0000-0000-000000000033', 'The woman who lives next door is a nurse.', 'Người phụ nữ sống cạnh nhà là một y tá.', 'who lives', 1),
  ('21000000-0000-0000-0033-000000000002', '20000000-0000-0000-0000-000000000033', 'This is the book which I bought yesterday.', 'Đây là quyển sách tôi đã mua hôm qua.', 'which I bought', 2),
  ('21000000-0000-0000-0033-000000000003', '20000000-0000-0000-0000-000000000033', 'He is the man whose car was stolen.', 'Ông ấy là người có chiếc xe bị trộm.', 'whose car', 3),
  ('21000000-0000-0000-0033-000000000004', '20000000-0000-0000-0000-000000000033', 'That is the restaurant where we had dinner.', 'Đó là nhà hàng nơi chúng tôi đã ăn tối.', 'where we had dinner', 4),
  ('21000000-0000-0000-0034-000000000001', '20000000-0000-0000-0000-000000000034', 'She said that she was tired.', 'Cô ấy nói rằng cô ấy mệt.', 'was tired', 1),
  ('21000000-0000-0000-0034-000000000002', '20000000-0000-0000-0000-000000000034', 'He told me that he would call me the next day.', 'Anh ấy bảo tôi rằng ngày hôm sau anh ấy sẽ gọi cho tôi.', 'would call', 2),
  ('21000000-0000-0000-0034-000000000003', '20000000-0000-0000-0000-000000000034', 'They said they had finished the work.', 'Họ nói họ đã làm xong công việc.', 'had finished', 3),
  ('21000000-0000-0000-0034-000000000004', '20000000-0000-0000-0000-000000000034', 'She asked me where I lived.', 'Cô ấy hỏi tôi sống ở đâu.', 'where I lived', 4),
  ('21000000-0000-0000-0035-000000000001', '20000000-0000-0000-0000-000000000035', 'He has been working all day. He must be tired.', 'Anh ấy làm việc cả ngày. Chắc anh ấy mệt.', 'must be tired', 1),
  ('21000000-0000-0000-0035-000000000002', '20000000-0000-0000-0000-000000000035', 'It might rain this afternoon.', 'Chiều nay có thể trời mưa.', 'might rain', 2),
  ('21000000-0000-0000-0035-000000000003', '20000000-0000-0000-0000-000000000035', 'That can''t be her. She is in London.', 'Đó không thể là cô ấy. Cô ấy đang ở Luân Đôn.', 'can''t be', 3),
  ('21000000-0000-0000-0035-000000000004', '20000000-0000-0000-0000-000000000035', 'She may have missed the bus.', 'Có thể cô ấy đã lỡ xe buýt.', 'may have missed', 4),
  ('21000000-0000-0000-0036-000000000001', '20000000-0000-0000-0000-000000000036', 'You are tired, aren''t you?', 'Bạn mệt, phải không?', 'aren''t you', 1),
  ('21000000-0000-0000-0036-000000000002', '20000000-0000-0000-0000-000000000036', 'She likes tea, doesn''t she?', 'Cô ấy thích trà, đúng không?', 'doesn''t she', 2),
  ('21000000-0000-0000-0036-000000000003', '20000000-0000-0000-0000-000000000036', 'They didn''t come, did they?', 'Họ đã không đến, đúng không?', 'did they', 3),
  ('21000000-0000-0000-0036-000000000004', '20000000-0000-0000-0000-000000000036', 'Let''s go to the beach, shall we?', 'Chúng ta đi biển nhé?', 'shall we', 4),
  ('21000000-0000-0000-0037-000000000001', '20000000-0000-0000-0000-000000000037', 'If I had taken the job, I would be rich now.', 'Nếu tôi nhận công việc đó, bây giờ tôi đã giàu rồi.', 'would be rich', 1),
  ('21000000-0000-0000-0037-000000000002', '20000000-0000-0000-0000-000000000037', 'If she were more careful, she wouldn''t have made that mistake.', 'Nếu cô ấy cẩn thận hơn thì cô ấy đã không mắc lỗi đó.', 'wouldn''t have made', 2),
  ('21000000-0000-0000-0037-000000000003', '20000000-0000-0000-0000-000000000037', 'If we had left earlier, we would be at the airport now.', 'Nếu chúng ta đi sớm hơn thì giờ chúng ta đã ở sân bay.', 'would be at the airport', 3),
  ('21000000-0000-0000-0037-000000000004', '20000000-0000-0000-0000-000000000037', 'If he were taller, he would have joined the team.', 'Nếu anh ấy cao hơn thì anh ấy đã vào đội rồi.', 'would have joined', 4),
  ('21000000-0000-0000-0038-000000000001', '20000000-0000-0000-0000-000000000038', 'I wish I had a bigger house.', 'Giá mà tôi có ngôi nhà lớn hơn.', 'had a bigger house', 1),
  ('21000000-0000-0000-0038-000000000002', '20000000-0000-0000-0000-000000000038', 'She wishes she had studied more.', 'Cô ấy ước mình đã học nhiều hơn.', 'had studied more', 2),
  ('21000000-0000-0000-0038-000000000003', '20000000-0000-0000-0000-000000000038', 'If only it would stop raining!', 'Giá mà trời tạnh mưa!', 'would stop', 3),
  ('21000000-0000-0000-0038-000000000004', '20000000-0000-0000-0000-000000000038', 'I wish I could speak Japanese.', 'Tôi ước tôi có thể nói tiếng Nhật.', 'could speak', 4),
  ('21000000-0000-0000-0039-000000000001', '20000000-0000-0000-0000-000000000039', 'I had my hair cut yesterday.', 'Hôm qua tôi đã đi cắt tóc.', 'had my hair cut', 1),
  ('21000000-0000-0000-0039-000000000002', '20000000-0000-0000-0000-000000000039', 'We are having our house painted.', 'Chúng tôi đang thuê người sơn nhà.', 'having our house painted', 2),
  ('21000000-0000-0000-0039-000000000003', '20000000-0000-0000-0000-000000000039', 'She got her phone repaired.', 'Cô ấy đã đem điện thoại đi sửa.', 'got her phone repaired', 3),
  ('21000000-0000-0000-0039-000000000004', '20000000-0000-0000-0000-000000000039', 'He had his wallet stolen on the bus.', 'Anh ấy bị trộm mất ví trên xe buýt.', 'had his wallet stolen', 4),
  ('21000000-0000-0000-0040-000000000001', '20000000-0000-0000-0000-000000000040', 'Never have I seen such a beautiful sunset.', 'Tôi chưa bao giờ thấy hoàng hôn đẹp đến thế.', 'Never have I seen', 1),
  ('21000000-0000-0000-0040-000000000002', '20000000-0000-0000-0000-000000000040', 'Hardly had she sat down when the phone rang.', 'Cô ấy vừa ngồi xuống thì điện thoại reo.', 'Hardly had she sat', 2),
  ('21000000-0000-0000-0040-000000000003', '20000000-0000-0000-0000-000000000040', 'No sooner had we left than it started to rain.', 'Chúng tôi vừa rời đi thì trời bắt đầu mưa.', 'No sooner had we left', 3),
  ('21000000-0000-0000-0040-000000000004', '20000000-0000-0000-0000-000000000040', 'Not only did he lie, but he also stole money.', 'Anh ta không chỉ nói dối mà còn lấy trộm tiền.', 'Not only did he lie', 4);
