INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0001-0001-000000000001', '40000000-0000-0001-0001-000000000001', NULL, 'She ______ to school every day.', 1, 'Chủ ngữ "she" là ngôi thứ ba số ít nên động từ thêm -es: goes.', 1),
  ('41000000-0000-0001-0001-000000000002', '40000000-0000-0001-0001-000000000001', NULL, 'They ______ football on Sundays.', 2, 'Chủ ngữ "they" là số nhiều nên động từ giữ nguyên: play.', 2),
  ('41000000-0000-0001-0001-000000000003', '40000000-0000-0001-0001-000000000001', NULL, 'My brother ______ like vegetables.', 1, '"My brother" tương đương "he" nên dùng doesn''t + động từ nguyên mẫu.', 3),
  ('41000000-0000-0001-0001-000000000004', '40000000-0000-0001-0001-000000000001', NULL, '______ you speak English?', 0, 'Với chủ ngữ "you" ta mượn trợ động từ Do để đặt câu hỏi.', 4),
  ('41000000-0000-0001-0001-000000000005', '40000000-0000-0001-0001-000000000001', NULL, 'The sun ______ in the east.', 0, 'Sự thật hiển nhiên dùng hiện tại đơn; "the sun" là ngôi thứ ba số ít nên thêm -s: rises.', 5),
  ('41000000-0000-0001-0001-000000000006', '40000000-0000-0001-0001-000000000001', NULL, 'He doesn''t ______ coffee.', 2, 'Sau doesn''t, động từ luôn ở dạng nguyên mẫu: drink.', 6),
  ('41000000-0000-0001-0006-000000000001', '40000000-0000-0001-0006-000000000001', NULL, 'I ______ a teacher.', 0, 'Chủ ngữ "I" đi với am.', 1),
  ('41000000-0000-0001-0006-000000000002', '40000000-0000-0001-0006-000000000001', NULL, 'She ______ my sister.', 0, 'Chủ ngữ "she" đi với is.', 2),
  ('41000000-0000-0001-0006-000000000003', '40000000-0000-0001-0006-000000000001', NULL, 'They ______ in the garden.', 2, 'Chủ ngữ "they" đi với are.', 3),
  ('41000000-0000-0001-0006-000000000004', '40000000-0000-0001-0006-000000000001', NULL, '______ you tired?', 0, 'Câu hỏi với "you" dùng Are đảo lên đầu câu.', 4),
  ('41000000-0000-0001-0006-000000000005', '40000000-0000-0001-0006-000000000001', NULL, 'My parents ______ at work now.', 2, '"My parents" là số nhiều nên dùng are.', 5),
  ('41000000-0000-0001-0006-000000000006', '40000000-0000-0001-0006-000000000001', NULL, 'It ______ not cold today.', 2, 'Chủ ngữ "it" đi với is: It is not cold.', 6),
  ('41000000-0000-0001-0002-000000000001', '40000000-0000-0001-0002-000000000001', NULL, 'She ______ her homework now.', 1, '"Now" là dấu hiệu của hiện tại tiếp diễn: is doing.', 1),
  ('41000000-0000-0001-0002-000000000002', '40000000-0000-0001-0002-000000000001', NULL, 'Look! The children ______ in the garden.', 3, '"Look!" báo hiệu hành động đang xảy ra: are playing.', 2),
  ('41000000-0000-0001-0002-000000000003', '40000000-0000-0001-0002-000000000001', NULL, 'I ______ to music at the moment.', 1, '"At the moment" đi với hiện tại tiếp diễn: am listening.', 3),
  ('41000000-0000-0001-0002-000000000004', '40000000-0000-0001-0002-000000000001', NULL, 'He ______ not sleeping now.', 2, 'Chủ ngữ "he" đi với is: He is not sleeping.', 4),
  ('41000000-0000-0001-0002-000000000005', '40000000-0000-0001-0002-000000000001', NULL, 'What ______ you doing?', 3, 'Với "you" ta dùng are: What are you doing?', 5),
  ('41000000-0000-0001-0002-000000000006', '40000000-0000-0001-0002-000000000001', NULL, 'We ______ dinner right now.', 3, '"Right now" cho biết hành động đang diễn ra: are having.', 6),
  ('41000000-0000-0001-0007-000000000001', '40000000-0000-0001-0007-000000000001', NULL, 'There ______ a cat under the table.', 2, '"A cat" là số ít nên dùng there is.', 1),
  ('41000000-0000-0001-0007-000000000002', '40000000-0000-0001-0007-000000000001', NULL, 'There ______ many people in the park.', 1, '"Many people" là số nhiều nên dùng there are.', 2),
  ('41000000-0000-0001-0007-000000000003', '40000000-0000-0001-0007-000000000001', NULL, '______ there a supermarket near your house?', 0, '"A supermarket" là số ít: Is there...?', 3),
  ('41000000-0000-0001-0007-000000000004', '40000000-0000-0001-0007-000000000001', NULL, 'There ______ any milk in the fridge.', 3, '"Milk" là danh từ không đếm được nên dùng isn''t.', 4),
  ('41000000-0000-0001-0007-000000000005', '40000000-0000-0001-0007-000000000001', NULL, 'There ______ two windows in my room.', 1, '"Two windows" là số nhiều nên dùng there are.', 5),
  ('41000000-0000-0001-0007-000000000006', '40000000-0000-0001-0007-000000000001', NULL, '______ there any eggs?', 2, '"Any eggs" là số nhiều nên dùng Are there...?', 6),
  ('41000000-0000-0001-0008-000000000001', '40000000-0000-0001-0008-000000000001', NULL, 'I need ______ umbrella.', 1, '"Umbrella" bắt đầu bằng nguyên âm nên dùng an.', 1),
  ('41000000-0000-0001-0008-000000000002', '40000000-0000-0001-0008-000000000001', NULL, 'She is ______ teacher.', 0, '"Teacher" bắt đầu bằng phụ âm nên dùng a.', 2),
  ('41000000-0000-0001-0008-000000000003', '40000000-0000-0001-0008-000000000001', NULL, 'We saw a movie. ______ movie was great.', 1, 'Phim đã được nhắc tới ở câu trước nên dùng The.', 3),
  ('41000000-0000-0001-0008-000000000004', '40000000-0000-0001-0008-000000000001', NULL, 'He waited for ______ hour.', 2, '"Hour" có âm h câm, phát âm bắt đầu bằng nguyên âm nên dùng an.', 4),
  ('41000000-0000-0001-0008-000000000005', '40000000-0000-0001-0008-000000000001', NULL, '______ moon goes around the Earth.', 2, 'Mặt trăng là duy nhất nên dùng the.', 5),
  ('41000000-0000-0001-0008-000000000006', '40000000-0000-0001-0008-000000000001', NULL, 'My father is ______ engineer.', 1, '"Engineer" bắt đầu bằng nguyên âm nên dùng an.', 6),
  ('41000000-0000-0001-0009-000000000001', '40000000-0000-0001-0009-000000000001', NULL, 'One child, two ______.', 0, '"Child" là danh từ bất quy tắc: children.', 1),
  ('41000000-0000-0001-0009-000000000002', '40000000-0000-0001-0009-000000000001', NULL, 'One box, two ______.', 3, 'Danh từ tận cùng bằng x thêm -es: boxes.', 2),
  ('41000000-0000-0001-0009-000000000003', '40000000-0000-0001-0009-000000000001', NULL, 'One baby, two ______.', 1, 'Phụ âm + y đổi y thành i rồi thêm -es: babies.', 3),
  ('41000000-0000-0001-0009-000000000004', '40000000-0000-0001-0009-000000000001', NULL, 'One man, two ______.', 1, '"Man" có số nhiều bất quy tắc: men.', 4),
  ('41000000-0000-0001-0009-000000000005', '40000000-0000-0001-0009-000000000001', NULL, 'One foot, two ______.', 1, '"Foot" có số nhiều bất quy tắc: feet.', 5),
  ('41000000-0000-0001-0009-000000000006', '40000000-0000-0001-0009-000000000001', NULL, 'One sheep, two ______.', 1, '"Sheep" giữ nguyên ở số nhiều.', 6),
  ('41000000-0000-0001-0010-000000000001', '40000000-0000-0001-0010-000000000001', NULL, 'How ______ students are in your class?', 2, '"Students" đếm được nên dùng How many.', 1),
  ('41000000-0000-0001-0010-000000000002', '40000000-0000-0001-0010-000000000001', NULL, 'How ______ milk do you need?', 1, '"Milk" không đếm được nên dùng How much.', 2),
  ('41000000-0000-0001-0010-000000000003', '40000000-0000-0001-0010-000000000001', NULL, 'Which word is uncountable?', 2, '"Rice" không đếm được; các từ còn lại đều có số nhiều.', 3),
  ('41000000-0000-0001-0010-000000000004', '40000000-0000-0001-0010-000000000001', NULL, 'I need some ______ about the trip.', 3, '"Information" không đếm được nên không thêm -s hay a/an.', 4);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0001-0010-000000000005', '40000000-0000-0001-0010-000000000001', NULL, 'There are ______ books on the shelf.', 0, '"Books" đếm được nên dùng a few.', 5),
  ('41000000-0000-0001-0010-000000000006', '40000000-0000-0001-0010-000000000001', NULL, 'She drinks ______ water every day.', 0, '"Water" không đếm được; a lot of đi được với cả hai loại.', 6),
  ('41000000-0000-0001-0011-000000000001', '40000000-0000-0001-0011-000000000001', NULL, 'This is Tom. ______ sister is a doctor.', 3, 'Cần tính từ sở hữu của "Tom" (nam): his.', 1),
  ('41000000-0000-0001-0011-000000000002', '40000000-0000-0001-0011-000000000001', NULL, 'I like Anna. I often talk to ______.', 0, 'Sau giới từ "to" cần đại từ tân ngữ: her.', 2),
  ('41000000-0000-0001-0011-000000000003', '40000000-0000-0001-0011-000000000001', NULL, 'They are my friends. I love ______.', 1, 'Làm tân ngữ cho "love" nên dùng them.', 3),
  ('41000000-0000-0001-0011-000000000004', '40000000-0000-0001-0011-000000000001', NULL, 'That book is not yours. It is ______.', 3, 'Đại từ sở hữu đứng một mình: mine.', 4),
  ('41000000-0000-0001-0011-000000000005', '40000000-0000-0001-0011-000000000001', NULL, 'The dog is hungry. ______ bowl is empty.', 1, '"Its" là tính từ sở hữu của "it"; it''s = it is.', 5),
  ('41000000-0000-0001-0011-000000000006', '40000000-0000-0001-0011-000000000001', NULL, 'We love ______ new house.', 2, 'Trước danh từ cần tính từ sở hữu: our.', 6),
  ('41000000-0000-0001-0012-000000000001', '40000000-0000-0001-0012-000000000001', NULL, 'I wake up ______ 6 a.m.', 3, 'Giờ cụ thể dùng at.', 1),
  ('41000000-0000-0001-0012-000000000002', '40000000-0000-0001-0012-000000000001', NULL, 'My birthday is ______ June.', 2, 'Tháng dùng in.', 2),
  ('41000000-0000-0001-0012-000000000003', '40000000-0000-0001-0012-000000000001', NULL, 'We have a meeting ______ Monday.', 3, 'Thứ trong tuần dùng on.', 3),
  ('41000000-0000-0001-0012-000000000004', '40000000-0000-0001-0012-000000000001', NULL, 'She lives ______ Da Nang.', 3, 'Thành phố (không gian rộng) dùng in.', 4),
  ('41000000-0000-0001-0012-000000000005', '40000000-0000-0001-0012-000000000001', NULL, 'The picture is ______ the wall.', 1, 'Vật treo trên bề mặt tường dùng on.', 5),
  ('41000000-0000-0001-0012-000000000006', '40000000-0000-0001-0012-000000000001', NULL, 'I study ______ night.', 3, '"At night" là cụm cố định.', 6),
  ('41000000-0000-0001-0013-000000000001', '40000000-0000-0001-0013-000000000001', NULL, '______ do you live? - In Hue.', 2, 'Câu trả lời chỉ nơi chốn nên từ để hỏi là Where.', 1),
  ('41000000-0000-0001-0013-000000000002', '40000000-0000-0001-0013-000000000001', NULL, '______ is your birthday? - On May 5th.', 1, 'Câu trả lời chỉ thời gian nên dùng When.', 2),
  ('41000000-0000-0001-0013-000000000003', '40000000-0000-0001-0013-000000000001', NULL, '______ are you late? - Because of the traffic.', 0, 'Câu trả lời giải thích lý do nên dùng Why.', 3),
  ('41000000-0000-0001-0013-000000000004', '40000000-0000-0001-0013-000000000001', NULL, '______ is that man? - He is my uncle.', 3, 'Hỏi về người nên dùng Who.', 4),
  ('41000000-0000-0001-0013-000000000005', '40000000-0000-0001-0013-000000000001', NULL, 'What time ______ the film start?', 1, 'Chủ ngữ "the film" là ngôi thứ ba số ít nên dùng does.', 5),
  ('41000000-0000-0001-0013-000000000006', '40000000-0000-0001-0013-000000000001', NULL, 'How ______ is this bag? - It is ten dollars.', 2, 'Hỏi giá tiền dùng How much.', 6),
  ('41000000-0000-0001-0014-000000000001', '40000000-0000-0001-0014-000000000001', NULL, 'She ______ play the piano very well.', 1, 'Can không thêm -s: She can play.', 1),
  ('41000000-0000-0001-0014-000000000002', '40000000-0000-0001-0014-000000000001', NULL, 'I ______ swim. I am afraid of water.', 3, 'Câu sau cho thấy người nói không biết bơi: can''t.', 2),
  ('41000000-0000-0001-0014-000000000003', '40000000-0000-0001-0014-000000000001', NULL, '______ you help me with this bag?', 0, 'Yêu cầu lịch sự dùng Can you...?', 3),
  ('41000000-0000-0001-0014-000000000004', '40000000-0000-0001-0014-000000000001', NULL, 'He can ______ English and French.', 0, 'Sau can là động từ nguyên mẫu không có to: speak.', 4),
  ('41000000-0000-0001-0014-000000000005', '40000000-0000-0001-0014-000000000001', NULL, 'Babies ______ walk when they are born.', 3, 'Trẻ sơ sinh không biết đi nên dùng can''t.', 5),
  ('41000000-0000-0001-0014-000000000006', '40000000-0000-0001-0014-000000000001', NULL, 'You ______ use my phone if you want.', 0, 'Can diễn tả sự cho phép: You can use...', 6),
  ('41000000-0000-0001-0015-000000000001', '40000000-0000-0001-0015-000000000001', NULL, 'I ______ eat meat. I am a vegetarian.', 3, 'Người ăn chay không ăn thịt, nên trạng từ phù hợp là never (không bao giờ).', 1),
  ('41000000-0000-0001-0015-000000000002', '40000000-0000-0001-0015-000000000001', NULL, 'She is ______ late.', 1, 'Trạng từ tần suất đứng sau động từ to be: is never late.', 2),
  ('41000000-0000-0001-0015-000000000003', '40000000-0000-0001-0015-000000000001', NULL, 'I ______ go to the cinema on Sundays. It is my habit.', 3, '"It is my habit" cho thấy tần suất cao: usually.', 3),
  ('41000000-0000-0001-0015-000000000004', '40000000-0000-0001-0015-000000000001', NULL, 'They ______ visit their grandparents. About once a year.', 0, '"Once a year" là tần suất rất thấp: rarely.', 4),
  ('41000000-0000-0001-0015-000000000005', '40000000-0000-0001-0015-000000000001', NULL, 'How ______ do you exercise? - Three times a week.', 2, 'Hỏi về tần suất dùng How often.', 5),
  ('41000000-0000-0001-0015-000000000006', '40000000-0000-0001-0015-000000000001', NULL, 'My mother ______ cooks dinner. I never cook.', 2, 'Mẹ nấu cơm thay vì "tôi không bao giờ nấu" nên là always.', 6),
  ('41000000-0000-0001-0016-000000000001', '40000000-0000-0001-0016-000000000001', NULL, 'My house is ______ than yours.', 0, 'Tính từ ngắn gấp đôi phụ âm cuối: big - bigger.', 1),
  ('41000000-0000-0001-0016-000000000002', '40000000-0000-0001-0016-000000000001', NULL, 'This is the ______ film I have ever seen.', 3, 'Tính từ dài ở so sánh nhất: the most + adj.', 2),
  ('41000000-0000-0001-0016-000000000003', '40000000-0000-0001-0016-000000000001', NULL, 'She is ______ than her sister.', 1, '"Careful" là tính từ dài nên dùng more careful.', 3),
  ('41000000-0000-0001-0016-000000000004', '40000000-0000-0001-0016-000000000001', NULL, 'Tom is the ______ boy in our class.', 2, 'So sánh nhất với tính từ ngắn: the tallest.', 4),
  ('41000000-0000-0001-0016-000000000005', '40000000-0000-0001-0016-000000000001', NULL, 'Her English is ______ than mine.', 2, '"Good" có so sánh hơn bất quy tắc: better.', 5),
  ('41000000-0000-0001-0016-000000000006', '40000000-0000-0001-0016-000000000001', NULL, 'This exam was ______ than the last one.', 3, '"Bad" có so sánh hơn bất quy tắc: worse.', 6),
  ('41000000-0000-0001-0003-000000000001', '40000000-0000-0001-0003-000000000001', NULL, 'I ______ to the store yesterday.', 2, '"Yesterday" là dấu hiệu quá khứ đơn; quá khứ của go là went.', 1),
  ('41000000-0000-0001-0003-000000000002', '40000000-0000-0001-0003-000000000001', NULL, 'She ______ her keys last night.', 3, 'Quá khứ của lose là lost.', 2);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0001-0003-000000000003', '40000000-0000-0001-0003-000000000001', NULL, 'They ______ football last Sunday.', 0, '"Last Sunday" báo hiệu quá khứ đơn: played.', 3),
  ('41000000-0000-0001-0003-000000000004', '40000000-0000-0001-0003-000000000001', NULL, 'He didn''t ______ the answer.', 1, 'Sau didn''t động từ ở dạng nguyên mẫu: know.', 4),
  ('41000000-0000-0001-0003-000000000005', '40000000-0000-0001-0003-000000000001', NULL, '______ you see the film last night?', 2, 'Câu hỏi quá khứ đơn dùng Did.', 5),
  ('41000000-0000-0001-0003-000000000006', '40000000-0000-0001-0003-000000000001', NULL, 'We ______ breakfast at seven this morning.', 3, 'Hành động đã xong trong sáng nay: had.', 6),
  ('41000000-0000-0001-0017-000000000001', '40000000-0000-0001-0017-000000000001', NULL, 'At 7 p.m. yesterday, I ______ dinner.', 0, 'Hành động đang diễn ra tại thời điểm 7 giờ tối qua: was having.', 1),
  ('41000000-0000-0001-0017-000000000002', '40000000-0000-0001-0017-000000000001', NULL, 'She ______ a book when the lights went out.', 0, 'Hành động đang diễn ra thì bị xen vào: was reading.', 2),
  ('41000000-0000-0001-0017-000000000003', '40000000-0000-0001-0017-000000000001', NULL, 'They ______ TV at that time.', 1, 'Chủ ngữ "they" đi với were: were watching.', 3),
  ('41000000-0000-0001-0017-000000000004', '40000000-0000-0001-0017-000000000001', NULL, 'What ______ you doing at 9 last night?', 0, 'Chủ ngữ "you" đi với were.', 4),
  ('41000000-0000-0001-0017-000000000005', '40000000-0000-0001-0017-000000000001', NULL, 'I ______ walking home when it started to rain.', 3, 'Chủ ngữ "I" đi với was: I was walking.', 5),
  ('41000000-0000-0001-0017-000000000006', '40000000-0000-0001-0017-000000000001', NULL, 'While he ______ the car, his phone rang.', 0, '"While" đi với hành động đang diễn ra trong quá khứ: was driving.', 6),
  ('41000000-0000-0001-0018-000000000001', '40000000-0000-0001-0018-000000000001', NULL, 'I think it ______ rain tomorrow.', 1, '"Tomorrow" và "I think" gợi ý dự đoán tương lai: will rain.', 1),
  ('41000000-0000-0001-0018-000000000002', '40000000-0000-0001-0018-000000000001', NULL, 'The phone is ringing. I ______ answer it.', 3, 'Quyết định tức thời ngay lúc nói dùng will.', 2),
  ('41000000-0000-0001-0018-000000000003', '40000000-0000-0001-0018-000000000001', NULL, 'She is sick, so she ______ come to the party tomorrow.', 3, 'Cô ấy bị ốm nên ngày mai sẽ không đến: won''t.', 3),
  ('41000000-0000-0001-0018-000000000004', '40000000-0000-0001-0018-000000000001', NULL, 'Will you ______ me with my homework?', 2, 'Sau will là động từ nguyên mẫu: help.', 4),
  ('41000000-0000-0001-0018-000000000005', '40000000-0000-0001-0018-000000000001', NULL, 'I promise I ______ tell anyone.', 2, 'Lời hứa về tương lai dùng will/won''t.', 5),
  ('41000000-0000-0001-0018-000000000006', '40000000-0000-0001-0018-000000000001', NULL, 'Next year, we ______ 20 years old.', 3, 'Sự việc ở tương lai: will be.', 6),
  ('41000000-0000-0001-0019-000000000001', '40000000-0000-0001-0019-000000000001', NULL, 'I ______ going to learn French next year.', 2, 'Chủ ngữ "I" đi với am: I am going to learn.', 1),
  ('41000000-0000-0001-0019-000000000002', '40000000-0000-0001-0019-000000000001', NULL, 'Look at the sky! It ______ going to rain.', 0, 'Dự đoán có căn cứ; "it" đi với is.', 2),
  ('41000000-0000-0001-0019-000000000003', '40000000-0000-0001-0019-000000000001', NULL, 'She ______ going to be a doctor.', 1, 'Chủ ngữ "she" đi với is.', 3),
  ('41000000-0000-0001-0019-000000000004', '40000000-0000-0001-0019-000000000001', NULL, 'We are going ______ buy a new house.', 1, 'Cấu trúc đúng: be going to + V.', 4),
  ('41000000-0000-0001-0019-000000000005', '40000000-0000-0001-0019-000000000001', NULL, '______ they going to visit us?', 2, 'Chủ ngữ "they" nên dùng Are: Are they going to...?', 5),
  ('41000000-0000-0001-0019-000000000006', '40000000-0000-0001-0019-000000000001', NULL, 'He isn''t going ______ the party tonight.', 1, 'Cấu trúc: be going to + động từ nguyên mẫu: to attend.', 6),
  ('41000000-0000-0001-0004-000000000001', '40000000-0000-0001-0004-000000000001', NULL, 'I ______ never eaten sushi.', 2, 'Chủ ngữ "I" đi với have.', 1),
  ('41000000-0000-0001-0004-000000000002', '40000000-0000-0001-0004-000000000001', NULL, 'She ______ already finished her work.', 0, 'Chủ ngữ "she" đi với has.', 2),
  ('41000000-0000-0001-0004-000000000003', '40000000-0000-0001-0004-000000000001', NULL, 'We have lived here ______ 2020.', 3, 'Since + mốc thời gian (2020).', 3),
  ('41000000-0000-0001-0004-000000000004', '40000000-0000-0001-0004-000000000001', NULL, 'They have known each other ______ ten years.', 1, 'For + khoảng thời gian (ten years).', 4),
  ('41000000-0000-0001-0004-000000000005', '40000000-0000-0001-0004-000000000001', NULL, 'Have you ______ visited Da Lat?', 0, '"Ever" đi với hiện tại hoàn thành trong câu hỏi về trải nghiệm.', 5),
  ('41000000-0000-0001-0004-000000000006', '40000000-0000-0001-0004-000000000001', NULL, 'He ______ his keys. He cannot open the door.', 1, 'Hành động có kết quả ở hiện tại (không mở được cửa): has lost.', 6),
  ('41000000-0000-0001-0020-000000000001', '40000000-0000-0001-0020-000000000001', NULL, 'You ______ drive fast here. It is dangerous.', 3, 'Điều cấm làm: mustn''t.', 1),
  ('41000000-0000-0001-0020-000000000002', '40000000-0000-0001-0020-000000000001', NULL, 'Tomorrow is Sunday. I ______ go to school.', 1, 'Chủ nhật được nghỉ nên không cần đi học: don''t have to.', 2),
  ('41000000-0000-0001-0020-000000000003', '40000000-0000-0001-0020-000000000001', NULL, 'You look tired. You ______ rest.', 2, 'Lời khuyên dùng should.', 3),
  ('41000000-0000-0001-0020-000000000004', '40000000-0000-0001-0020-000000000001', NULL, 'She ______ wear a uniform at work.', 3, 'Chủ ngữ "she" đi với has to.', 4),
  ('41000000-0000-0001-0020-000000000005', '40000000-0000-0001-0020-000000000001', NULL, 'Students ______ be quiet in the exam.', 0, 'Quy định bắt buộc: must be quiet.', 5),
  ('41000000-0000-0001-0020-000000000006', '40000000-0000-0001-0020-000000000001', NULL, 'I forgot my book, so I ______ borrow yours.', 2, 'Chủ ngữ "I" đi với have to.', 6),
  ('41000000-0000-0001-0021-000000000001', '40000000-0000-0001-0021-000000000001', NULL, 'I ______ smoke, but I stopped last year.', 3, 'Thói quen trong quá khứ nay đã bỏ: used to + V.', 1),
  ('41000000-0000-0001-0021-000000000002', '40000000-0000-0001-0021-000000000001', NULL, 'He ______ to be very shy.', 3, 'Cấu trúc: used to + V.', 2),
  ('41000000-0000-0001-0021-000000000003', '40000000-0000-0001-0021-000000000001', NULL, 'Did you ______ to live in this town?', 1, 'Sau did dùng use to (không có -d).', 3),
  ('41000000-0000-0001-0021-000000000004', '40000000-0000-0001-0021-000000000001', NULL, 'We ______ have a dog when I was a child.', 2, 'Trạng thái trong quá khứ: used to have.', 4),
  ('41000000-0000-0001-0021-000000000005', '40000000-0000-0001-0021-000000000001', NULL, 'She ______ eat vegetables, but now she loves them.', 1, 'Trước đây không ăn, giờ đã khác: didn''t use to.', 5),
  ('41000000-0000-0001-0021-000000000006', '40000000-0000-0001-0021-000000000001', NULL, 'They ______ live in the countryside. Now they live in the city.', 0, 'Thói quen/trạng thái đã chấm dứt: used to live.', 6);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0001-0022-000000000001', '40000000-0000-0001-0022-000000000001', NULL, 'I was hungry, ______ I ate a sandwich.', 1, 'Vế sau là kết quả của vế trước: so.', 1),
  ('41000000-0000-0001-0022-000000000002', '40000000-0000-0001-0022-000000000001', NULL, 'She stayed at home ______ she was sick.', 1, 'Vế sau là nguyên nhân: because.', 2),
  ('41000000-0000-0001-0022-000000000003', '40000000-0000-0001-0022-000000000001', NULL, 'He is rich, ______ he is not happy.', 2, 'Hai ý tương phản: but.', 3),
  ('41000000-0000-0001-0022-000000000004', '40000000-0000-0001-0022-000000000001', NULL, 'Do you want tea ______ coffee?', 3, 'Đưa ra lựa chọn: or.', 4),
  ('41000000-0000-0001-0022-000000000005', '40000000-0000-0001-0022-000000000001', NULL, '______ it was cold, we went swimming.', 3, 'Hai vế đối lập, cần từ nhường bộ ở đầu câu: Although.', 5),
  ('41000000-0000-0001-0022-000000000006', '40000000-0000-0001-0022-000000000001', NULL, 'I studied hard, ______ I passed the exam.', 1, 'Kết quả của việc học chăm: so.', 6),
  ('41000000-0000-0001-0023-000000000001', '40000000-0000-0001-0023-000000000001', NULL, 'Would you like ______ tea?', 2, 'Lời mời trong câu hỏi dùng some.', 1),
  ('41000000-0000-0001-0023-000000000002', '40000000-0000-0001-0023-000000000001', NULL, 'I don''t have ______ money.', 2, 'Câu phủ định dùng any.', 2),
  ('41000000-0000-0001-0023-000000000003', '40000000-0000-0001-0023-000000000001', NULL, 'There are only ______ students in class today. Most are absent.', 0, '"Students" đếm được nên dùng a few/few; "only" cho thấy ít.', 3),
  ('41000000-0000-0001-0023-000000000004', '40000000-0000-0001-0023-000000000001', NULL, 'We have ______ time. Let us hurry!', 0, '"Time" không đếm được và ý là gần như không còn: little.', 4),
  ('41000000-0000-0001-0023-000000000005', '40000000-0000-0001-0023-000000000001', NULL, 'Is there ______ milk in the fridge?', 2, 'Câu hỏi dùng any; "milk" không đếm được.', 5),
  ('41000000-0000-0001-0023-000000000006', '40000000-0000-0001-0023-000000000001', NULL, 'He has ______ friends, so he feels lonely.', 3, 'Ý nghĩa tiêu cực (gần như không có bạn): few + danh từ đếm được.', 6),
  ('41000000-0000-0001-0024-000000000001', '40000000-0000-0001-0024-000000000001', NULL, 'I enjoy ______ to music.', 1, 'Enjoy đi với V-ing: listening.', 1),
  ('41000000-0000-0001-0024-000000000002', '40000000-0000-0001-0024-000000000001', NULL, 'She wants ______ a doctor.', 1, 'Want đi với to + V: to be.', 2),
  ('41000000-0000-0001-0024-000000000003', '40000000-0000-0001-0024-000000000001', NULL, 'He is good at ______ pictures.', 1, 'Sau giới từ "at" dùng V-ing: drawing.', 3),
  ('41000000-0000-0001-0024-000000000004', '40000000-0000-0001-0024-000000000001', NULL, 'We decided ______ a new car.', 1, 'Decide đi với to + V: to buy.', 4),
  ('41000000-0000-0001-0024-000000000005', '40000000-0000-0001-0024-000000000001', NULL, 'Please avoid ______ in the library.', 3, 'Avoid đi với V-ing: talking.', 5),
  ('41000000-0000-0001-0024-000000000006', '40000000-0000-0001-0024-000000000001', NULL, 'I have finished ______ my homework.', 0, 'Finish đi với V-ing: doing.', 6),
  ('41000000-0000-0001-0025-000000000001', '40000000-0000-0001-0025-000000000001', NULL, 'I ______ here for two hours.', 3, '"For two hours" kéo dài đến hiện tại: have been waiting.', 1),
  ('41000000-0000-0001-0025-000000000002', '40000000-0000-0001-0025-000000000001', NULL, 'She ______ English since 2020.', 1, '"Since 2020" đi với hiện tại hoàn thành tiếp diễn: has been studying.', 2),
  ('41000000-0000-0001-0025-000000000003', '40000000-0000-0001-0025-000000000001', NULL, 'They ______ all morning.', 1, '"All morning" nhấn mạnh quá trình: have been playing.', 3),
  ('41000000-0000-0001-0025-000000000004', '40000000-0000-0001-0025-000000000001', NULL, 'How long ______ you been living here?', 2, 'Chủ ngữ "you" đi với have: How long have you been living...', 4),
  ('41000000-0000-0001-0025-000000000005', '40000000-0000-0001-0025-000000000001', NULL, 'It ______ raining since breakfast.', 3, 'Chủ ngữ "it" đi với has been.', 5),
  ('41000000-0000-0001-0025-000000000006', '40000000-0000-0001-0025-000000000001', NULL, 'He is tired because he ______ all night.', 0, 'Quá trình kéo dài dẫn đến kết quả hiện tại (mệt): has been working.', 6),
  ('41000000-0000-0001-0026-000000000001', '40000000-0000-0001-0026-000000000001', NULL, 'When we got to the station, the train ______.', 0, 'Tàu rời đi trước khi chúng tôi đến: had left.', 1),
  ('41000000-0000-0001-0026-000000000002', '40000000-0000-0001-0026-000000000001', NULL, 'She ______ dinner before I came home.', 3, 'Hành động nấu xảy ra trước hành động "I came home": had cooked.', 2),
  ('41000000-0000-0001-0026-000000000003', '40000000-0000-0001-0026-000000000001', NULL, 'By the time he arrived, we ______ our lunch.', 2, '"By the time + quá khứ đơn" đi với past perfect: had finished.', 3),
  ('41000000-0000-0001-0026-000000000004', '40000000-0000-0001-0026-000000000001', NULL, 'I ______ never seen snow before I went to Japan.', 3, 'Trước một mốc trong quá khứ dùng had + V3: had never seen.', 4),
  ('41000000-0000-0001-0026-000000000005', '40000000-0000-0001-0026-000000000001', NULL, '______ they left when you arrived?', 1, 'Câu hỏi past perfect dùng Had đảo lên đầu câu.', 5),
  ('41000000-0000-0001-0026-000000000006', '40000000-0000-0001-0026-000000000001', NULL, 'He was sad because he ______ his keys.', 0, 'Mất chìa khóa xảy ra trước nỗi buồn: had lost.', 6),
  ('41000000-0000-0001-0027-000000000001', '40000000-0000-0001-0027-000000000001', NULL, 'At 9 a.m. tomorrow, I ______ in a meeting.', 0, 'Hành động đang diễn ra tại một thời điểm tương lai: will be sitting.', 1),
  ('41000000-0000-0001-0027-000000000002', '40000000-0000-0001-0027-000000000001', NULL, 'This time next month, they ______ on the beach.', 0, '"This time next month" đi với tương lai tiếp diễn.', 2),
  ('41000000-0000-0001-0027-000000000003', '40000000-0000-0001-0027-000000000001', NULL, 'I ______ studying at eight tonight, so please call later.', 0, 'Cấu trúc: will be + V-ing.', 3),
  ('41000000-0000-0001-0027-000000000004', '40000000-0000-0001-0027-000000000001', NULL, '______ you be using the computer this evening?', 0, 'Câu hỏi tương lai tiếp diễn dùng Will đảo lên đầu.', 4),
  ('41000000-0000-0001-0027-000000000005', '40000000-0000-0001-0027-000000000001', NULL, 'She ______ working tomorrow. She has a day off.', 3, 'Phủ định tương lai tiếp diễn: won''t be working.', 5),
  ('41000000-0000-0001-0027-000000000006', '40000000-0000-0001-0027-000000000001', NULL, 'At this time tomorrow, we ______ to Da Nang.', 2, '"At this time tomorrow" đi với tương lai tiếp diễn.', 6),
  ('41000000-0000-0001-0028-000000000001', '40000000-0000-0001-0028-000000000001', NULL, 'By next year, I ______ my degree.', 1, '"By next year" là mốc tương lai: will have finished.', 1),
  ('41000000-0000-0001-0028-000000000002', '40000000-0000-0001-0028-000000000001', NULL, 'She ______ the cake by the time guests arrive.', 0, '"By the time" kèm hành động hoàn tất trước: will have baked.', 2),
  ('41000000-0000-0001-0028-000000000003', '40000000-0000-0001-0028-000000000001', NULL, 'We ______ here for ten years by 2030.', 3, 'Mốc "by 2030" đi với tương lai hoàn thành: will have lived.', 3),
  ('41000000-0000-0001-0028-000000000004', '40000000-0000-0001-0028-000000000001', NULL, 'By the time you come, I ______ cooking.', 0, 'Hành động sẽ hoàn tất trước mốc tương lai.', 4);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0001-0028-000000000005', '40000000-0000-0001-0028-000000000001', NULL, '______ they have left by 8 o''clock?', 3, 'Câu hỏi tương lai hoàn thành dùng Will đảo lên đầu.', 5),
  ('41000000-0000-0001-0028-000000000006', '40000000-0000-0001-0028-000000000001', NULL, 'He ______ not have completed the project by Monday.', 3, 'Phủ định tương lai hoàn thành: will not have completed.', 6),
  ('41000000-0000-0001-0029-000000000001', '40000000-0000-0001-0029-000000000001', NULL, 'This car ______ in Japan.', 0, 'Chiếc xe được sản xuất: is made (bị động hiện tại đơn).', 1),
  ('41000000-0000-0001-0029-000000000002', '40000000-0000-0001-0029-000000000001', NULL, 'The thief ______ by the police yesterday.', 1, 'Quá khứ đơn bị động: was caught.', 2),
  ('41000000-0000-0001-0029-000000000003', '40000000-0000-0001-0029-000000000001', NULL, 'The homework ______ before Friday.', 3, 'Bị động với modal: must be + V3.', 3),
  ('41000000-0000-0001-0029-000000000004', '40000000-0000-0001-0029-000000000001', NULL, 'Many trees ______ in the park last year.', 2, '"Many trees" là số nhiều, quá khứ: were planted.', 4),
  ('41000000-0000-0001-0029-000000000005', '40000000-0000-0001-0029-000000000001', NULL, 'The results ______ tomorrow.', 1, 'Bị động tương lai: will be announced.', 5),
  ('41000000-0000-0001-0029-000000000006', '40000000-0000-0001-0029-000000000001', NULL, 'The room ______ cleaned every day.', 0, 'Bị động hiện tại đơn với chủ ngữ số ít: is cleaned.', 6),
  ('41000000-0000-0001-0030-000000000001', '40000000-0000-0001-0030-000000000001', NULL, 'If you heat water to 100 degrees, it ______.', 3, 'Chân lý khoa học dùng hiện tại đơn: boils.', 1),
  ('41000000-0000-0001-0030-000000000002', '40000000-0000-0001-0030-000000000001', NULL, 'If I ______ coffee in the evening, I can''t sleep.', 3, 'Câu điều kiện loại 0: If + hiện tại đơn.', 2),
  ('41000000-0000-0001-0030-000000000003', '40000000-0000-0001-0030-000000000001', NULL, 'Ice ______ if the temperature rises.', 1, 'Quy luật tự nhiên: hiện tại đơn.', 3),
  ('41000000-0000-0001-0030-000000000004', '40000000-0000-0001-0030-000000000001', NULL, 'If you ______ a plant, it grows.', 0, 'Mệnh đề if dùng hiện tại đơn: water.', 4),
  ('41000000-0000-0001-0030-000000000005', '40000000-0000-0001-0030-000000000001', NULL, 'If people ______ enough, they feel tired.', 3, 'Sự thật chung: hiện tại đơn phủ định.', 5),
  ('41000000-0000-0001-0030-000000000006', '40000000-0000-0001-0030-000000000001', NULL, 'When the sun sets, it ______ dark.', 3, '"When" thay if trong câu điều kiện loại 0: hiện tại đơn.', 6),
  ('41000000-0000-0001-0005-000000000001', '40000000-0000-0001-0005-000000000001', NULL, 'If it ______ tomorrow, we will cancel the picnic.', 1, 'Mệnh đề if dùng hiện tại đơn: rains.', 1),
  ('41000000-0000-0001-0005-000000000002', '40000000-0000-0001-0005-000000000001', NULL, 'If you ______ hard, you will succeed.', 0, 'If + hiện tại đơn, S + will + V.', 2),
  ('41000000-0000-0001-0005-000000000003', '40000000-0000-0001-0005-000000000001', NULL, 'She ______ you if you ask her.', 0, 'Mệnh đề chính dùng will + V: will help.', 3),
  ('41000000-0000-0001-0005-000000000004', '40000000-0000-0001-0005-000000000001', NULL, 'If I ______ time, I will call you.', 1, 'Mệnh đề if dùng hiện tại đơn: have.', 4),
  ('41000000-0000-0001-0005-000000000005', '40000000-0000-0001-0005-000000000001', NULL, '______ you hurry, you will miss the train.', 1, 'Unless = if not: Unless you hurry...', 5),
  ('41000000-0000-0001-0005-000000000006', '40000000-0000-0001-0005-000000000001', NULL, 'If he ______ late again, the boss will be angry.', 3, 'Mệnh đề if dùng hiện tại đơn: is.', 6),
  ('41000000-0000-0001-0031-000000000001', '40000000-0000-0001-0031-000000000001', NULL, 'If I ______ rich, I would travel around the world.', 3, 'Giả định không có thật ở hiện tại: If I were...', 1),
  ('41000000-0000-0001-0031-000000000002', '40000000-0000-0001-0031-000000000001', NULL, 'If she ______ more time, she would learn French.', 1, 'Mệnh đề if dùng quá khứ đơn: had.', 2),
  ('41000000-0000-0001-0031-000000000003', '40000000-0000-0001-0031-000000000001', NULL, 'I ______ buy that car if I had enough money.', 3, 'Mệnh đề chính của loại 2 dùng would + V.', 3),
  ('41000000-0000-0001-0031-000000000004', '40000000-0000-0001-0031-000000000001', NULL, 'If I ______ you, I would apologize.', 1, 'Lời khuyên: If I were you...', 4),
  ('41000000-0000-0001-0031-000000000005', '40000000-0000-0001-0031-000000000001', NULL, 'What would you do if you ______ a million dollars?', 2, 'Mệnh đề if dùng quá khứ đơn: won.', 5),
  ('41000000-0000-0001-0031-000000000006', '40000000-0000-0001-0031-000000000001', NULL, 'They ______ be happier if they lived in the countryside.', 2, 'Giả định ở hiện tại dùng would + V.', 6),
  ('41000000-0000-0001-0032-000000000001', '40000000-0000-0001-0032-000000000001', NULL, 'If I ______ earlier, I would have caught the bus.', 3, 'Mệnh đề if loại 3 dùng quá khứ hoàn thành: had left.', 1),
  ('41000000-0000-0001-0032-000000000002', '40000000-0000-0001-0032-000000000001', NULL, 'She would have passed if she ______ harder.', 2, 'Mệnh đề if dùng had + V3: had studied.', 2),
  ('41000000-0000-0001-0032-000000000003', '40000000-0000-0001-0032-000000000001', NULL, 'If it hadn''t rained, we ______ to the beach.', 0, 'Mệnh đề chính loại 3: would have + V3.', 3),
  ('41000000-0000-0001-0032-000000000004', '40000000-0000-0001-0032-000000000001', NULL, 'They ______ the match if they had trained more.', 0, 'Kết quả tưởng tượng trong quá khứ: would have won.', 4),
  ('41000000-0000-0001-0032-000000000005', '40000000-0000-0001-0032-000000000001', NULL, 'If you ______ me, I would have helped you.', 1, 'Mệnh đề if loại 3: had called.', 5),
  ('41000000-0000-0001-0032-000000000006', '40000000-0000-0001-0032-000000000001', NULL, 'I ______ him if I had known he was ill.', 0, 'Tiếc nuối trong quá khứ: would have visited.', 6),
  ('41000000-0000-0001-0033-000000000001', '40000000-0000-0001-0033-000000000001', NULL, 'The boy ______ is sitting there is my brother.', 2, 'Thay thế cho người và làm chủ ngữ: who.', 1),
  ('41000000-0000-0001-0033-000000000002', '40000000-0000-0001-0033-000000000001', NULL, 'The phone ______ I bought is very good.', 1, 'Thay thế cho vật: which (hoặc that).', 2),
  ('41000000-0000-0001-0033-000000000003', '40000000-0000-0001-0033-000000000001', NULL, 'She is the girl ______ father is a pilot.', 0, 'Chỉ sự sở hữu "bố của cô gái": whose.', 3),
  ('41000000-0000-0001-0033-000000000004', '40000000-0000-0001-0033-000000000001', NULL, 'This is the town ______ I was born.', 3, 'Thay thế cho nơi chốn: where.', 4),
  ('41000000-0000-0001-0033-000000000005', '40000000-0000-0001-0033-000000000001', NULL, 'The cat ______ sleeps on my bed is called Tom.', 2, 'Thay thế cho vật làm chủ ngữ: that (hoặc which).', 5),
  ('41000000-0000-0001-0033-000000000006', '40000000-0000-0001-0033-000000000001', NULL, 'I met a man ______ works for NASA.', 2, 'Thay thế cho người: who.', 6),
  ('41000000-0000-0001-0034-000000000001', '40000000-0000-0001-0034-000000000001', NULL, '"I am hungry," she said. -> She said that she ______ hungry.', 0, 'Lùi thì: am -> was.', 1),
  ('41000000-0000-0001-0034-000000000002', '40000000-0000-0001-0034-000000000001', NULL, '"I will help you," he said. -> He said he ______ help me.', 0, 'Lùi thì: will -> would.', 2);
INSERT INTO quiz_questions (id, quiz_id, flashcard_id, question_text, correct_option_index, explanation, sort_order) VALUES
  ('41000000-0000-0001-0034-000000000003', '40000000-0000-0001-0034-000000000001', NULL, '"We went to Paris," they said. -> They said they ______ to Paris.', 2, 'Lùi thì: quá khứ đơn -> quá khứ hoàn thành.', 3),
  ('41000000-0000-0001-0034-000000000004', '40000000-0000-0001-0034-000000000001', NULL, '"Where do you live?" she asked me. -> She asked me where I ______.', 2, 'Câu hỏi gián tiếp: lùi thì và dùng trật tự câu khẳng định.', 4),
  ('41000000-0000-0001-0034-000000000005', '40000000-0000-0001-0034-000000000001', NULL, 'He told ______ that he was busy.', 0, 'Tell cần tân ngữ trực tiếp: told me.', 5),
  ('41000000-0000-0001-0034-000000000006', '40000000-0000-0001-0034-000000000001', NULL, '"Are you tired?" he asked. -> He asked ______ I was tired.', 1, 'Câu hỏi Yes/No chuyển sang gián tiếp dùng if/whether.', 6),
  ('41000000-0000-0001-0035-000000000001', '40000000-0000-0001-0035-000000000001', NULL, 'Look at those dark clouds. It ______ rain soon.', 1, 'Có dấu hiệu nhưng chưa chắc chắn: might.', 1),
  ('41000000-0000-0001-0035-000000000002', '40000000-0000-0001-0035-000000000001', NULL, 'He has lived here for 20 years. He ______ know the area well.', 2, 'Gần như chắc chắn: must.', 2),
  ('41000000-0000-0001-0035-000000000003', '40000000-0000-0001-0035-000000000001', NULL, 'You ______ be serious! That is impossible.', 0, 'Chắc chắn là không thể: can''t.', 3),
  ('41000000-0000-0001-0035-000000000004', '40000000-0000-0001-0035-000000000001', NULL, 'I am not sure, but she ______ be at the library.', 3, 'Chỉ là khả năng, không chắc chắn: could.', 4),
  ('41000000-0000-0001-0035-000000000005', '40000000-0000-0001-0035-000000000001', NULL, 'The lights are off. They ______ have gone out.', 2, 'Suy đoán gần như chắc chắn về quá khứ: must have gone.', 5),
  ('41000000-0000-0001-0035-000000000006', '40000000-0000-0001-0035-000000000001', NULL, 'He ______ have forgotten the meeting. He is never late.', 3, 'Vì anh ấy không bao giờ trễ nên khó có chuyện quên: can''t have forgotten.', 6),
  ('41000000-0000-0001-0036-000000000001', '40000000-0000-0001-0036-000000000001', NULL, 'You are a teacher, ______?', 3, 'Câu khẳng định với are thì đuôi là aren''t you.', 1),
  ('41000000-0000-0001-0036-000000000002', '40000000-0000-0001-0036-000000000001', NULL, 'She doesn''t like fish, ______?', 1, 'Câu phủ định thì đuôi khẳng định: does she.', 2),
  ('41000000-0000-0001-0036-000000000003', '40000000-0000-0001-0036-000000000001', NULL, 'They went to school yesterday, ______?', 0, 'Quá khứ đơn khẳng định thì đuôi didn''t they.', 3),
  ('41000000-0000-0001-0036-000000000004', '40000000-0000-0001-0036-000000000001', NULL, 'He can swim, ______?', 3, 'Trợ động từ can thì đuôi can''t he.', 4),
  ('41000000-0000-0001-0036-000000000005', '40000000-0000-0001-0036-000000000001', NULL, 'Let''s have lunch, ______?', 3, 'Với Let''s ta dùng shall we.', 5),
  ('41000000-0000-0001-0036-000000000006', '40000000-0000-0001-0036-000000000001', NULL, 'I am late, ______?', 2, 'Trường hợp đặc biệt của I am: aren''t I.', 6),
  ('41000000-0000-0001-0037-000000000001', '40000000-0000-0001-0037-000000000001', NULL, 'If I had studied harder, I ______ a better job now.', 2, 'Điều kiện trong quá khứ, kết quả ở hiện tại: would + V.', 1),
  ('41000000-0000-0001-0037-000000000002', '40000000-0000-0001-0037-000000000001', NULL, 'If she ______ shy, she would have spoken at the meeting.', 2, 'Điều kiện luôn đúng ở hiện tại, kết quả ở quá khứ: If + quá khứ đơn.', 2),
  ('41000000-0000-0001-0037-000000000003', '40000000-0000-0001-0037-000000000001', NULL, 'If we had saved money, we ______ rich now.', 0, 'Kết quả ở hiện tại (now): would be.', 3),
  ('41000000-0000-0001-0037-000000000004', '40000000-0000-0001-0037-000000000001', NULL, 'If I were taller, I ______ basketball for the national team ten years ago.', 0, 'Kết quả đã xảy ra trong quá khứ: would have played.', 4),
  ('41000000-0000-0001-0037-000000000005', '40000000-0000-0001-0037-000000000001', NULL, 'If they ______ the map, they wouldn''t be lost now.', 3, 'Điều kiện trong quá khứ: had taken.', 5),
  ('41000000-0000-0001-0037-000000000006', '40000000-0000-0001-0037-000000000001', NULL, 'I would be at home now if I ______ the last bus.', 1, 'Điều kiện đã không xảy ra trong quá khứ: hadn''t missed.', 6),
  ('41000000-0000-0001-0038-000000000001', '40000000-0000-0001-0038-000000000001', NULL, 'I wish I ______ more free time. I am so busy.', 3, 'Ước điều không có thật ở hiện tại: wish + quá khứ đơn.', 1),
  ('41000000-0000-0001-0038-000000000002', '40000000-0000-0001-0038-000000000001', NULL, 'She wishes she ______ to the party last night.', 2, 'Tiếc nuối về quá khứ: wish + had + V3.', 2),
  ('41000000-0000-0001-0038-000000000003', '40000000-0000-0001-0038-000000000001', NULL, 'I wish it ______ raining. I want to go out.', 2, 'Mong thay đổi ở tương lai: wish + would + V.', 3),
  ('41000000-0000-0001-0038-000000000004', '40000000-0000-0001-0038-000000000001', NULL, 'If only I ______ the answer!', 2, 'Ước điều ở hiện tại: if only + quá khứ đơn.', 4),
  ('41000000-0000-0001-0038-000000000005', '40000000-0000-0001-0038-000000000001', NULL, 'I wish I ______ taller.', 0, 'Điều không thật ở hiện tại: wish + were.', 5),
  ('41000000-0000-0001-0038-000000000006', '40000000-0000-0001-0038-000000000001', NULL, 'He wishes he ______ the exam. He failed.', 0, 'Tiếc nuối về quá khứ: had passed.', 6),
  ('41000000-0000-0001-0039-000000000001', '40000000-0000-0001-0039-000000000001', NULL, 'I ______ my car washed every week.', 2, 'Cấu trúc: have + tân ngữ + V3: have my car washed.', 1),
  ('41000000-0000-0001-0039-000000000002', '40000000-0000-0001-0039-000000000001', NULL, 'She had her hair ______ at the salon.', 2, 'Sau tân ngữ dùng V3: cut.', 2),
  ('41000000-0000-0001-0039-000000000003', '40000000-0000-0001-0039-000000000001', NULL, 'We are ______ the kitchen painted next week.', 1, 'Thuê người sơn: having + tân ngữ + V3.', 3),
  ('41000000-0000-0001-0039-000000000004', '40000000-0000-0001-0039-000000000001', NULL, 'He got his bike ______.', 1, 'Cấu trúc: get + tân ngữ + V3: repaired.', 4),
  ('41000000-0000-0001-0039-000000000005', '40000000-0000-0001-0039-000000000001', NULL, 'I need to ______ my eyes tested.', 3, 'Cấu trúc: have + tân ngữ + V3.', 5),
  ('41000000-0000-0001-0039-000000000006', '40000000-0000-0001-0039-000000000001', NULL, 'They had their house ______ in the storm.', 2, 'Điều không may xảy ra với họ: had + tân ngữ + V3.', 6),
  ('41000000-0000-0001-0040-000000000001', '40000000-0000-0001-0040-000000000001', NULL, 'Never ______ such a delicious meal.', 1, 'Never đứng đầu câu thì đảo trợ động từ: have I eaten.', 1),
  ('41000000-0000-0001-0040-000000000002', '40000000-0000-0001-0040-000000000001', NULL, 'Hardly ______ the room when the lights went out.', 0, 'Hardly + had + S + V3 + when.', 2),
  ('41000000-0000-0001-0040-000000000003', '40000000-0000-0001-0040-000000000001', NULL, 'No sooner had she arrived ______ it began to snow.', 0, 'No sooner ... than.', 3),
  ('41000000-0000-0001-0040-000000000004', '40000000-0000-0001-0040-000000000001', NULL, 'Not only ______ late, but he also forgot his book.', 3, 'Not only đứng đầu câu thì đảo to be: was he.', 4),
  ('41000000-0000-0001-0040-000000000005', '40000000-0000-0001-0040-000000000001', NULL, 'Rarely ______ to the cinema nowadays.', 3, 'Rarely đứng đầu câu: do + S + V.', 5),
